#!/usr/bin/env node
/**
 * Sync PO documents from Smartsheet to VF Storage + procurement_documents table
 *
 * Sources:
 *   1. Item Receipts       (8404664677519236)  — invoices & delivery notes
 *   2. Delivery Note Reg.  (84737013010308)    — delivery notes
 *   3. Quote Approval Reg. (1589086541270916)  — supplier quotes
 *
 * Usage:
 *   node scripts/sync-smartsheet-po-documents.js [limit]
 *
 * Idempotent — uses notes='smartsheet:{attachmentId}' for dedup.
 */

const { neon } = require('@neondatabase/serverless');
require('dotenv').config({ path: '.env.local' });

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
const DATABASE_URL = process.env.DATABASE_URL;
const SMARTSHEET_API_TOKEN = process.env.SMARTSHEET_API_TOKEN || 'X6McWWfPeBK7G3t7c5qIwQUfJu2gGbtatV2sz';
const SMARTSHEET_API_BASE = 'https://api.smartsheet.com/2.0';
const VF_STORAGE_URL = process.env.VF_STORAGE_URL || 'http://100.96.203.105:8091';

const sql = neon(DATABASE_URL);

// Sheet definitions
const SHEETS = [
  {
    name: 'Item Receipts',
    id: '8404664677519236',
    poColumn: 'PO Number',
    docNameColumn: 'Invoice/Delivery Note Number',
    contextColumn: 'Supplier',
    defaultDocType: null, // inferred from filename
  },
  {
    name: 'Delivery Note Register',
    id: '84737013010308',
    poColumn: 'PROC - RECON VF PO#',
    docNameColumn: 'Delivery Note Number',
    contextColumn: null,
    defaultDocType: 'delivery_note',
  },
  {
    name: 'Quote Approval Register',
    id: '1589086541270916',
    poColumn: 'PO Number',
    docNameColumn: 'Quote Number',
    contextColumn: null,
    defaultDocType: 'quote_pdf',
  },
];

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Infer document_type from filename when sheet doesn't have a fixed type */
function inferDocType(filename) {
  const lower = filename.toLowerCase();
  if (lower.includes('invoice') || lower.includes('inv')) return 'invoice';
  if (lower.includes('delivery') || lower.includes('dn') || lower.includes('pod')) return 'delivery_note';
  if (lower.includes('quote') || lower.includes('rfq')) return 'quote_pdf';
  if (lower.includes('receipt') || lower.includes('grv')) return 'receipt';
  return 'delivery_note'; // default for Item Receipts sheet
}

/** Guess MIME type from filename extension */
function guessMimeType(filename) {
  const ext = (filename.split('.').pop() || '').toLowerCase();
  const map = {
    pdf: 'application/pdf',
    jpg: 'image/jpeg',
    jpeg: 'image/jpeg',
    png: 'image/png',
    gif: 'image/gif',
    doc: 'application/msword',
    docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    xls: 'application/vnd.ms-excel',
    xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    csv: 'text/csv',
    txt: 'text/plain',
  };
  return map[ext] || 'application/octet-stream';
}

/** Rate-limited delay */
const delay = (ms) => new Promise((r) => setTimeout(r, ms));

// ---------------------------------------------------------------------------
// Smartsheet API
// ---------------------------------------------------------------------------

async function ssGet(path) {
  const res = await fetch(`${SMARTSHEET_API_BASE}${path}`, {
    headers: { Authorization: `Bearer ${SMARTSHEET_API_TOKEN}` },
  });
  if (!res.ok) {
    const body = await res.text().catch(() => '');
    throw new Error(`SS API ${res.status} for ${path}: ${body.substring(0, 200)}`);
  }
  return res.json();
}

/** Fetch full sheet (columns + rows) */
async function fetchSheet(sheetId) {
  return ssGet(`/sheets/${sheetId}`);
}

/** Fetch all attachments for a sheet, paginated */
async function fetchAllAttachments(sheetId) {
  const all = [];
  let page = 1;
  const pageSize = 100;

  while (true) {
    const data = await ssGet(`/sheets/${sheetId}/attachments?page=${page}&pageSize=${pageSize}`);
    all.push(...data.data);
    if (data.data.length < pageSize) break;
    page++;
    await delay(50);
  }

  return all;
}

/** Get temporary download URL for an attachment */
async function getAttachmentUrl(sheetId, attachmentId) {
  const data = await ssGet(`/sheets/${sheetId}/attachments/${attachmentId}`);
  return data.url;
}

// ---------------------------------------------------------------------------
// VF Storage upload
// ---------------------------------------------------------------------------

async function uploadToStorage(poId, filename, fileBuffer, mimeType) {
  const boundary = `----WebKitFormBoundary${Date.now().toString(16)}`;
  const storageName = `${poId}_${filename}`;

  const header = Buffer.from(
    `--${boundary}\r\n` +
    `Content-Disposition: form-data; name="file"; filename="${storageName}"\r\n` +
    `Content-Type: ${mimeType}\r\n\r\n`
  );
  const footer = Buffer.from(`\r\n--${boundary}--\r\n`);
  const body = Buffer.concat([header, fileBuffer, footer]);

  const response = await fetch(`${VF_STORAGE_URL}/upload/procurement/purchase_order`, {
    method: 'POST',
    body,
    headers: {
      'Content-Type': `multipart/form-data; boundary=${boundary}`,
      'Content-Length': body.length.toString(),
    },
  });

  if (!response.ok) {
    const errText = await response.text();
    throw new Error(`Storage upload failed (${response.status}): ${errText.substring(0, 200)}`);
  }

  const result = await response.json();

  // Build public HTTPS URL
  const storagePath = result.path || `procurement/purchase_order/${result.filename || storageName}`;
  const publicUrl = `https://vf.fibreflow.app/storage/${storagePath}`;

  return {
    url: publicUrl,
    path: storagePath,
    size: result.size || fileBuffer.length,
  };
}

// ---------------------------------------------------------------------------
// Main sync
// ---------------------------------------------------------------------------

async function syncPODocuments(limit) {
  const startTime = Date.now();
  const stats = { downloaded: 0, uploaded: 0, linked: 0, skipped: 0, unmatchedPOs: new Set(), errors: [] };

  console.log('='.repeat(60));
  console.log('Smartsheet PO Document Sync');
  console.log('='.repeat(60));

  // 1. Load PO lookup from DB
  console.log('\n1. Loading purchase orders...');
  const pos = await sql`
    SELECT id, external_po_number
    FROM purchase_orders
    WHERE external_po_number IS NOT NULL
  `;
  const poMap = new Map();
  for (const po of pos) {
    // Normalize: trim, uppercase for matching
    const key = po.external_po_number.trim().toUpperCase();
    poMap.set(key, po.id);
  }
  console.log(`   Loaded ${pos.length} POs with external_po_number`);

  // 2. Load already-synced attachment IDs for idempotency
  console.log('\n2. Checking for already-synced documents...');
  const synced = await sql`
    SELECT notes FROM procurement_documents
    WHERE notes LIKE 'smartsheet:%'
      AND is_active = true
  `;
  // Extract just the 'smartsheet:{id}' prefix (notes may contain '| context')
  const syncedIds = new Set(synced.map((r) => r.notes.split(' |')[0].trim()));
  console.log(`   Found ${syncedIds.size} already synced`);

  // 3. Collect all work items from all 3 sheets
  console.log('\n3. Fetching sheet data from Smartsheet...');
  const workItems = [];

  for (const sheet of SHEETS) {
    console.log(`\n   --- ${sheet.name} (${sheet.id}) ---`);

    // Fetch sheet columns + rows
    const sheetData = await fetchSheet(sheet.id);
    const columns = sheetData.columns || [];
    const rows = sheetData.rows || [];

    // Build column map: title → columnId
    const colMap = new Map();
    for (const col of columns) {
      colMap.set(col.title, col.id);
    }

    const poColId = colMap.get(sheet.poColumn);
    const docNameColId = sheet.docNameColumn ? colMap.get(sheet.docNameColumn) : null;
    const ctxColId = sheet.contextColumn ? colMap.get(sheet.contextColumn) : null;

    if (!poColId) {
      console.log(`   WARNING: PO column "${sheet.poColumn}" not found — skipping sheet`);
      continue;
    }

    // Build rowId → row data lookup
    const rowLookup = new Map();
    for (const row of rows) {
      const cells = row.cells || [];
      let poNumber = null;
      let docName = null;
      let context = null;

      for (const cell of cells) {
        if (cell.columnId === poColId && cell.value) poNumber = String(cell.value).trim();
        if (docNameColId && cell.columnId === docNameColId && cell.value) docName = String(cell.value).trim();
        if (ctxColId && cell.columnId === ctxColId && cell.value) context = String(cell.value).trim();
      }

      if (poNumber) {
        rowLookup.set(row.id, { poNumber, docName, context });
      }
    }

    console.log(`   Rows with PO numbers: ${rowLookup.size}`);

    // Fetch all attachments for the sheet
    const attachments = await fetchAllAttachments(sheet.id);
    console.log(`   Attachments: ${attachments.length}`);

    // Filter to ROW attachments and group
    let rowAttachments = 0;
    for (const att of attachments) {
      if (att.parentType !== 'ROW') continue;
      rowAttachments++;

      const rowData = rowLookup.get(att.parentId);
      if (!rowData) continue;

      workItems.push({
        sheetId: sheet.id,
        sheetName: sheet.name,
        attachmentId: att.id,
        attachmentName: att.name,
        mimeType: att.mimeType || guessMimeType(att.name),
        sizeInKb: att.sizeInKb || 0,
        poNumber: rowData.poNumber,
        docName: rowData.docName || att.name.replace(/\.[^/.]+$/, ''),
        context: rowData.context,
        docType: sheet.defaultDocType || inferDocType(att.name),
      });
    }

    console.log(`   Row attachments: ${rowAttachments}`);
  }

  console.log(`\n   Total work items: ${workItems.length}`);

  // Apply limit
  const toProcess = limit ? workItems.slice(0, limit) : workItems;
  if (limit) console.log(`   Processing limit: ${limit}`);

  // 4. Process each attachment
  console.log('\n4. Processing attachments...\n');
  let processed = 0;

  for (const item of toProcess) {
    processed++;
    const dedupKey = `smartsheet:${item.attachmentId}`;
    const progress = Math.round((processed / toProcess.length) * 100);

    // Skip if already synced
    if (syncedIds.has(dedupKey)) {
      stats.skipped++;
      continue;
    }

    // Normalize PO number and look up
    // Handle comma-separated or multi-PO references — take the first one
    const rawPO = item.poNumber.split(/[,;\/]/)[0].trim().toUpperCase();
    // Try exact match, then with PO prefix variants
    let poId = poMap.get(rawPO);
    if (!poId && !rawPO.startsWith('PO')) {
      poId = poMap.get(`PO${rawPO}`) || poMap.get(`PO-${rawPO}`) || poMap.get(`PO ${rawPO}`);
    }

    if (!poId) {
      stats.unmatchedPOs.add(item.poNumber);
      stats.skipped++;
      continue;
    }

    try {
      process.stdout.write(
        `\r   [${progress}%] ${stats.linked}/${processed} - ${item.attachmentName.substring(0, 45).padEnd(45)}  `
      );

      // Get download URL
      const downloadUrl = await getAttachmentUrl(item.sheetId, item.attachmentId);
      await delay(50);

      // Download file
      const fileResp = await fetch(downloadUrl);
      if (!fileResp.ok) throw new Error(`Download HTTP ${fileResp.status}`);
      const fileBuffer = Buffer.from(await fileResp.arrayBuffer());
      stats.downloaded++;

      // Upload to VF Storage
      const { url, path, size } = await uploadToStorage(
        poId,
        item.attachmentName,
        fileBuffer,
        item.mimeType
      );
      stats.uploaded++;

      // Insert procurement_documents row
      const notesValue = item.context
        ? `${dedupKey} | ${item.context}`
        : dedupKey;

      await sql`
        INSERT INTO procurement_documents (
          entity_type, entity_id, document_type, document_name,
          file_url, file_path, file_size, mime_type,
          uploaded_by, uploaded_by_name, notes, is_active
        ) VALUES (
          'purchase_order', ${poId}::uuid, ${item.docType}, ${item.docName},
          ${url}, ${path}, ${size}, ${item.mimeType},
          'system@fibreflow.app', 'Smartsheet Sync',
          ${notesValue}, true
        )
      `;
      stats.linked++;

      // Rate limit
      await delay(100);
    } catch (error) {
      stats.errors.push({
        attachmentId: item.attachmentId,
        name: item.attachmentName,
        po: item.poNumber,
        error: error.message,
      });
    }
  }

  // 5. Summary
  const duration = Math.round((Date.now() - startTime) / 1000);

  console.log('\n\n' + '='.repeat(60));
  console.log('SYNC COMPLETE');
  console.log('='.repeat(60));
  console.log(`Total work items:  ${workItems.length}`);
  console.log(`Processed:         ${toProcess.length}`);
  console.log(`Downloaded:        ${stats.downloaded}`);
  console.log(`Uploaded:          ${stats.uploaded}`);
  console.log(`Linked in DB:      ${stats.linked}`);
  console.log(`Skipped:           ${stats.skipped}`);
  console.log(`Unmatched POs:     ${stats.unmatchedPOs.size}`);
  console.log(`Errors:            ${stats.errors.length}`);
  console.log(`Duration:          ${duration}s`);
  console.log('='.repeat(60));

  if (stats.unmatchedPOs.size > 0) {
    const poList = [...stats.unmatchedPOs].sort();
    console.log(`\nUnmatched PO numbers (${poList.length}):`);
    poList.slice(0, 20).forEach((po) => console.log(`  - ${po}`));
    if (poList.length > 20) console.log(`  ... and ${poList.length - 20} more`);
  }

  if (stats.errors.length > 0 && stats.errors.length <= 10) {
    console.log('\nErrors:');
    stats.errors.forEach((e) => console.log(`  - [${e.po}] ${e.name}: ${e.error}`));
  } else if (stats.errors.length > 10) {
    console.log(`\nFirst 10 errors (of ${stats.errors.length}):`);
    stats.errors.slice(0, 10).forEach((e) => console.log(`  - [${e.po}] ${e.name}: ${e.error}`));
  }

  return { linked: stats.linked, errors: stats.errors.length };
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------
const limit = process.argv[2] ? parseInt(process.argv[2]) : null;
console.log(limit ? `Running with limit: ${limit}` : 'Running full sync...');

syncPODocuments(limit)
  .then((result) => {
    console.log('\nDone!');
    process.exit(result.errors > 0 ? 1 : 0);
  })
  .catch((err) => {
    console.error('\nFatal error:', err);
    process.exit(1);
  });

-- Migration 230: Add Smartsheet PO sync columns to purchase_orders
-- One-off import from Smartsheet "Stock IN" sheet (876851875499908)

ALTER TABLE purchase_orders ADD COLUMN IF NOT EXISTS external_po_number VARCHAR(100);
ALTER TABLE purchase_orders ADD COLUMN IF NOT EXISTS smartsheet_row_id BIGINT;
ALTER TABLE purchase_orders ADD COLUMN IF NOT EXISTS fully_billed BOOLEAN DEFAULT false;
ALTER TABLE purchase_orders ADD COLUMN IF NOT EXISTS cancelled BOOLEAN DEFAULT false;

ALTER TABLE purchase_orders ADD CONSTRAINT uq_po_external_number UNIQUE (external_po_number);

#!/usr/bin/env tsx
/**
 * One-off Import: Smartsheet "Stock IN" → FibreFlow purchase_orders
 *
 * Fetches sheet 876851875499908, groups rows by PO Number,
 * matches suppliers/projects by name, and inserts into purchase_orders
 * + purchase_order_items.
 *
 * Idempotent: uses ON CONFLICT (external_po_number) DO UPDATE.
 *
 * Usage:
 *   npx tsx scripts/import-smartsheet-stock-in.ts
 *   npx tsx scripts/import-smartsheet-stock-in.ts --dry-run
 */

import { neon } from '@neondatabase/serverless';

const DATABASE_URL = process.env.DATABASE_URL;
if (!DATABASE_URL) {
  // eslint-disable-next-line no-console
  console.error('DATABASE_URL is not set');
  process.exit(1);
}

const SMARTSHEET_TOKEN = process.env.SMARTSHEET_API_TOKEN;
if (!SMARTSHEET_TOKEN) {
  // eslint-disable-next-line no-console
  console.error('SMARTSHEET_API_TOKEN is not set');
  process.exit(1);
}

const sql = neon(DATABASE_URL);
const SHEET_ID = '876851875499908';
const SS_API = 'https://api.smartsheet.com/2.0';
const DRY_RUN = process.argv.includes('--dry-run');

// ─── Types ───────────────────────────────────────────────────────────────────

interface SmartsheetCell {
  columnId: number;
  value?: string | number | boolean | null;
  displayValue?: string;
}

interface SmartsheetRow {
  id: number;
  rowNumber: number;
  cells: SmartsheetCell[];
}

interface SmartsheetColumn {
  id: number;
  title: string;
  type: string;
}

interface SmartsheetSheet {
  name: string;
  totalRowCount: number;
  columns: SmartsheetColumn[];
  rows: SmartsheetRow[];
}

interface POGroup {
  poNumber: string;
  rows: SmartsheetRow[];
}

interface SupplierRow {
  id: number;
  name: string;
  trading_name: string | null;
}

interface ProjectRow {
  id: string;
  project_name: string;
}

// ─── Smartsheet fetch ────────────────────────────────────────────────────────

async function fetchSheet(): Promise<SmartsheetSheet> {
  const url = `${SS_API}/sheets/${SHEET_ID}`;
  const res = await fetch(url, {
    headers: { Authorization: `Bearer ${SMARTSHEET_TOKEN}` },
  });
  if (!res.ok) {
    throw new Error(`Smartsheet API ${res.status}: ${await res.text()}`);
  }
  return res.json() as Promise<SmartsheetSheet>;
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

function buildColumnMap(columns: SmartsheetColumn[]): Map<string, number> {
  const map = new Map<string, number>();
  for (const col of columns) {
    map.set(col.title, col.id);
  }
  return map;
}

function cellValue(row: SmartsheetRow, colId: number | undefined): string | number | boolean | null {
  if (!colId) return null;
  const cell = row.cells.find(c => c.columnId === colId);
  return cell?.value ?? null;
}

function cellDisplay(row: SmartsheetRow, colId: number | undefined): string | null {
  if (!colId) return null;
  const cell = row.cells.find(c => c.columnId === colId);
  return (cell?.displayValue ?? cell?.value?.toString()) || null;
}

function toNumber(val: unknown): number {
  if (val === null || val === undefined || val === '') return 0;
  const n = Number(val);
  return Number.isNaN(n) ? 0 : n;
}

function toDate(val: unknown): string | null {
  if (!val) return null;
  const s = String(val);
  // Smartsheet dates come as YYYY-MM-DD or ISO strings
  const d = new Date(s);
  if (Number.isNaN(d.getTime())) return null;
  return d.toISOString().slice(0, 10);
}

function toBool(val: unknown): boolean {
  if (typeof val === 'boolean') return val;
  if (typeof val === 'string') return val.toLowerCase() === 'true' || val === '1' || val.toLowerCase() === 'yes';
  return Boolean(val);
}

// ─── Smartsheet → FF supplier alias map ──────────────────────────────────────
// Smartsheet uses short names; FF has full registered names.
// Keys are lowercase Smartsheet names → FF supplier IDs.

const SUPPLIER_ALIASES: Record<string, number> = {
  'adendorff':        29, // ADENDORFF MACHINERY MART CC
  'agri development': 33, // AGRI DEVELOPMENT SUPPLIERS (PTY) LTD
  'averge':           17, // AVERGE TECHNOLOGIES (PTY) LTD
  'buco nelspruit':   34, // Buco Nelspruit
  'cfs':              18, // CABLE FEEDER SYSTEMS AFRICA CC
  'eurobyte':         19, // EUROBYTE TECHNOLOGY (PTY) LTD
  'fttx':             21, // FTTX AND ENERGY WAREHOUSE (PTY) LTD
  'lambda':           22, // LAMBDA TEST EQUIPMENT CC
  'lathoko':          35, // LATHOKO INDUSTRIAL (PTY) LTD
  'm4a':              23, // MANHOLES 4 AFRICA (PTY) LTD
  'neocom':           24, // NEOCOM SOLUTIONS (PTY) LTD
  'photonics':        25, // PHOTONICS FIBRE CABLING SOUTH AFRICA (PTY) LTD
  'rand safety':      36, // RAND SAFETY EQUIPMENT CC
  'rohcap':           26, // ROHCAP FIBRE MAINTENANCE (PTY) LTD
};

// ─── Lookup maps ─────────────────────────────────────────────────────────────

async function loadSuppliers(): Promise<Map<string, number>> {
  const rows = await sql`
    SELECT id, LOWER(name) as name, LOWER(COALESCE(trading_name, '')) as trading_name
    FROM suppliers
  ` as unknown as SupplierRow[];
  const map = new Map<string, number>();

  // Load DB names
  for (const r of rows) {
    map.set(String(r.name).toLowerCase(), r.id);
    if (r.trading_name) {
      map.set(String(r.trading_name).toLowerCase(), r.id);
    }
  }

  // Add hardcoded aliases (Smartsheet short names → FF IDs)
  for (const [alias, id] of Object.entries(SUPPLIER_ALIASES)) {
    map.set(alias, id);
  }

  return map;
}

// Smartsheet → FF project alias map
const PROJECT_ALIASES: Record<string, string> = {
  'mamelodi p1':  '7003dc06-9af7-4a7c-bc6c-a177d77784f2', // Mamelodi
  'tembisa 1':    '7d8b94d6-8e5a-4dbb-9ede-69ce3884e004', // Thembisa POP 1
  'tembisa 2':    'd3df9135-9aa3-415d-87b6-17cce547eb22', // Thembisa POP 2
  'tembisa 3':    '1de088dd-fe24-43fb-b8d3-94fca61ef91d', // Thembisa POP 3
  'tonga a':      'ce3bf310-d6ba-4ede-ab36-a8c902a5efc6', // Tonga
  'etwatwa':      'c7255076-1d2f-41ce-97bb-858b8c87ee27', // Etwatwa
};

async function loadProjects(): Promise<Map<string, string>> {
  const rows = await sql`
    SELECT id, LOWER(project_name) as project_name FROM projects
  ` as unknown as ProjectRow[];
  const map = new Map<string, string>();
  for (const r of rows) {
    map.set(String(r.project_name).toLowerCase(), String(r.id));
  }

  // Add hardcoded aliases (Smartsheet short names → FF project IDs)
  for (const [alias, id] of Object.entries(PROJECT_ALIASES)) {
    map.set(alias, id);
  }

  return map;
}

// ─── Status derivation ──────────────────────────────────────────────────────

function deriveStatus(
  cancelled: boolean,
  fullyBilled: boolean,
  items: Array<{ qtyOrdered: number; qtyReceived: number }>
): string {
  if (cancelled) return 'cancelled';
  if (fullyBilled) return 'closed';
  const allReceived = items.length > 0 && items.every(i => i.qtyReceived >= i.qtyOrdered && i.qtyOrdered > 0);
  const someReceived = items.some(i => i.qtyReceived > 0);
  if (allReceived) return 'received';
  if (someReceived) return 'partially_received';
  return 'sent';
}

// ─── Main ────────────────────────────────────────────────────────────────────

async function main() {
  // eslint-disable-next-line no-console
  console.log(`\n${'='.repeat(60)}`);
  // eslint-disable-next-line no-console
  console.log(`  Smartsheet Stock IN → FibreFlow PO Import${DRY_RUN ? ' (DRY RUN)' : ''}`);
  // eslint-disable-next-line no-console
  console.log(`${'='.repeat(60)}\n`);

  // 1. Fetch sheet
  // eslint-disable-next-line no-console
  console.log('Fetching Smartsheet...');
  const sheet = await fetchSheet();
  // eslint-disable-next-line no-console
  console.log(`  Sheet: "${sheet.name}" — ${sheet.rows.length} rows, ${sheet.columns.length} columns\n`);

  // 2. Build column ID map
  const colMap = buildColumnMap(sheet.columns);
  // eslint-disable-next-line no-console
  console.log('Column mapping:');
  for (const [title, id] of colMap) {
    // eslint-disable-next-line no-console
    console.log(`  ${title} → ${id}`);
  }
  // eslint-disable-next-line no-console
  console.log('');

  // Resolve expected column IDs
  const COL = {
    poNumber:      colMap.get('PO Number'),
    poDate:        colMap.get('PO Date'),
    supplier:      colMap.get('Supplier'),
    project:       colMap.get('Project'),
    department:    colMap.get('Department'),
    fullyBilled:   colMap.get('Fully Billed'),
    cancelled:     colMap.get('Cancelled'),
    eta:           colMap.get('ETA'),
    comments:      colMap.get('Comments'),
    totalExVat:    colMap.get('Total EX VAT'),
    totalInclVat:  colMap.get('Total INCL VAT'),
    item:          colMap.get('Item'),
    qty:           colMap.get('QTY'),
    unitPriceEx:   colMap.get('Unit Price Ex VAT'),
    stockReceived: colMap.get('Stock Received'),
  };

  // Warn on missing columns
  const missing = Object.entries(COL).filter(([, v]) => !v).map(([k]) => k);
  if (missing.length > 0) {
    // eslint-disable-next-line no-console
    console.warn(`WARNING: Missing columns: ${missing.join(', ')}`);
    // eslint-disable-next-line no-console
    console.warn('Available columns:', Array.from(colMap.keys()).join(', '));
  }

  // 3. Group rows by PO Number
  const poGroups = new Map<string, SmartsheetRow[]>();
  let skippedNoPoNum = 0;
  for (const row of sheet.rows) {
    const poNum = cellDisplay(row, COL.poNumber);
    if (!poNum || !poNum.trim()) {
      skippedNoPoNum++;
      continue;
    }
    const key = poNum.trim();
    if (!poGroups.has(key)) poGroups.set(key, []);
    poGroups.get(key)!.push(row);
  }

  // eslint-disable-next-line no-console
  console.log(`Grouped ${sheet.rows.length} rows into ${poGroups.size} POs (${skippedNoPoNum} rows without PO number skipped)\n`);

  // 4. Load lookup maps
  const supplierMap = await loadSuppliers();
  const projectMap = await loadProjects();
  // eslint-disable-next-line no-console
  console.log(`Loaded ${supplierMap.size} supplier name variants, ${projectMap.size} projects\n`);

  // 5. Process each PO
  let imported = 0;
  let updated = 0;
  let skippedCancelled = 0;
  let skippedNoSupplier = 0;
  const unmatchedSuppliers = new Set<string>();
  const unmatchedProjects = new Set<string>();

  for (const [poNumber, rows] of poGroups) {
    // Use first row for PO-level fields
    const firstRow = rows[0];
    const supplierName = cellDisplay(firstRow, COL.supplier)?.trim() || '';
    const projectName = cellDisplay(firstRow, COL.project)?.trim() || '';
    const department = cellDisplay(firstRow, COL.department)?.trim() || null;
    const fullyBilled = toBool(cellValue(firstRow, COL.fullyBilled));
    const cancelled = toBool(cellValue(firstRow, COL.cancelled));
    const poDate = toDate(cellValue(firstRow, COL.poDate));
    const eta = toDate(cellValue(firstRow, COL.eta));
    const comments = cellDisplay(firstRow, COL.comments)?.trim() || null;

    // Match supplier (required)
    const supplierId = supplierMap.get(supplierName.toLowerCase());
    if (!supplierId) {
      unmatchedSuppliers.add(supplierName);
      skippedNoSupplier++;
      continue;
    }

    // Match project (optional)
    const projectId = projectMap.get(projectName.toLowerCase()) || null;
    if (projectName && !projectId) {
      unmatchedProjects.add(projectName);
    }

    // Build items array
    const items = rows.map(row => {
      const desc = cellDisplay(row, COL.item)?.trim() || 'Item';
      const qtyOrdered = toNumber(cellValue(row, COL.qty));
      const unitPrice = toNumber(cellValue(row, COL.unitPriceEx));
      const qtyReceived = toNumber(cellValue(row, COL.stockReceived));
      return { desc, qtyOrdered, unitPrice, qtyReceived, rowId: row.id };
    });

    // Calculate totals from items
    const subtotal = items.reduce((s, i) => s + Math.round(i.qtyOrdered * i.unitPrice * 100) / 100, 0);
    const taxRate = 15;
    const taxAmount = Math.round(subtotal * (taxRate / 100) * 100) / 100;
    const totalAmount = Math.round((subtotal + taxAmount) * 100) / 100;

    // Derive status
    const status = deriveStatus(cancelled, fullyBilled, items);

    if (DRY_RUN) {
      // eslint-disable-next-line no-console
      console.log(`  [DRY] ${poNumber} | ${supplierName} | ${projectName || '(no project)'} | R${totalAmount.toFixed(2)} | ${status} | ${items.length} items`);
      imported++;
      continue;
    }

    // Upsert PO
    const poResult = await sql`
      INSERT INTO purchase_orders (
        po_number, external_po_number, status, supplier_id, project_id,
        department, order_date, expected_delivery_date, internal_notes,
        subtotal, tax_rate, tax_amount, total_amount,
        fully_billed, cancelled, smartsheet_row_id,
        payment_terms, currency, delivery_address, created_by,
        created_at, updated_at
      ) VALUES (
        ${poNumber}, ${poNumber}, ${status}, ${supplierId}, ${projectId},
        ${department}, ${poDate}, ${eta}, ${comments},
        ${subtotal}, ${taxRate}, ${taxAmount}, ${totalAmount},
        ${fullyBilled}, ${cancelled}, ${firstRow.id},
        'Net 30', 'ZAR', 'Smartsheet Import', 'smartsheet-import',
        NOW(), NOW()
      )
      ON CONFLICT (external_po_number) DO UPDATE SET
        status = EXCLUDED.status,
        supplier_id = EXCLUDED.supplier_id,
        project_id = EXCLUDED.project_id,
        department = EXCLUDED.department,
        order_date = EXCLUDED.order_date,
        expected_delivery_date = EXCLUDED.expected_delivery_date,
        internal_notes = EXCLUDED.internal_notes,
        subtotal = EXCLUDED.subtotal,
        tax_amount = EXCLUDED.tax_amount,
        total_amount = EXCLUDED.total_amount,
        fully_billed = EXCLUDED.fully_billed,
        cancelled = EXCLUDED.cancelled,
        updated_at = NOW()
      RETURNING id, (xmax = 0) AS inserted
    `;

    const poId = poResult[0].id;
    const wasInserted = poResult[0].inserted;

    if (wasInserted) {
      imported++;
    } else {
      updated++;
      // Delete old items on re-run before re-inserting
      await sql`DELETE FROM purchase_order_items WHERE purchase_order_id = ${poId}`;
    }

    // Insert items
    for (const item of items) {
      const lineTotal = Math.round(item.qtyOrdered * item.unitPrice * 100) / 100;
      const itemTax = Math.round(lineTotal * (taxRate / 100) * 100) / 100;

      await sql`
        INSERT INTO purchase_order_items (
          purchase_order_id, item_description, quantity_ordered,
          quantity_received, unit_price, tax_rate, tax_amount,
          total_price, uom, created_at
        ) VALUES (
          ${poId}, ${item.desc}, ${item.qtyOrdered},
          ${item.qtyReceived}, ${item.unitPrice}, ${taxRate}, ${itemTax},
          ${lineTotal}, 'ea', NOW()
        )
      `;
    }
  }

  // 6. Summary
  // eslint-disable-next-line no-console
  console.log(`\n${'='.repeat(60)}`);
  // eslint-disable-next-line no-console
  console.log('  IMPORT SUMMARY');
  // eslint-disable-next-line no-console
  console.log(`${'='.repeat(60)}`);
  // eslint-disable-next-line no-console
  console.log(`  Total PO groups:     ${poGroups.size}`);
  // eslint-disable-next-line no-console
  console.log(`  Imported (new):      ${imported}`);
  // eslint-disable-next-line no-console
  console.log(`  Updated (re-run):    ${updated}`);
  // eslint-disable-next-line no-console
  console.log(`  Skipped (no supplier): ${skippedNoSupplier}`);
  // eslint-disable-next-line no-console
  console.log(`  Skipped (no PO#):    ${skippedNoPoNum}`);

  if (unmatchedSuppliers.size > 0) {
    // eslint-disable-next-line no-console
    console.log(`\n  UNMATCHED SUPPLIERS (${unmatchedSuppliers.size}):`);
    for (const name of unmatchedSuppliers) {
      // eslint-disable-next-line no-console
      console.log(`    - "${name}"`);
    }
  }

  if (unmatchedProjects.size > 0) {
    // eslint-disable-next-line no-console
    console.log(`\n  UNMATCHED PROJECTS (${unmatchedProjects.size}) — imported with NULL project_id:`);
    for (const name of unmatchedProjects) {
      // eslint-disable-next-line no-console
      console.log(`    - "${name}"`);
    }
  }

  // eslint-disable-next-line no-console
  console.log(`\n${'='.repeat(60)}\n`);
}

main()
  .then(() => process.exit(0))
  .catch(err => {
    // eslint-disable-next-line no-console
    console.error('Import failed:', err);
    process.exit(1);
  });

