  const handleCancel = () => {
    router.push('/projects');
  };

  if (loading || !id) return <AppLayout><div>Loading...</div></AppLayout>;

  return (
    <AppLayout>
      <ProjectForm project={project} onSubmit={handleSubmit} onCancel={handleCancel} />
