/**
 * Document Manager Component
 * Manages document uploads and displays for pipeline approvals
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import {
  FileText,
  Upload,
  Trash2,
  CheckCircle,
  ExternalLink,
  Calendar,
  AlertTriangle,
  Loader2,
  X,
} from 'lucide-react';
import type {
  PipelineApprovalDocument,
  ApprovalDocumentType,
  UploadApprovalDocumentInput,
} from '../types';

interface DocumentManagerProps {
  approvalId: string;
  currentUserId?: string;
  readonly?: boolean;
  onDocumentChange?: () => void;
}

const DOCUMENT_TYPES: { value: ApprovalDocumentType; label: string }[] = [
  { value: 'application_form', label: 'Application Form' },
  { value: 'supporting_doc', label: 'Supporting Document' },
  { value: 'site_plan', label: 'Site Plan' },
  { value: 'route_map', label: 'Route Map' },
  { value: 'approval_certificate', label: 'Approval Certificate' },
  { value: 'rejection_letter', label: 'Rejection Letter' },
  { value: 'conditions_doc', label: 'Conditions Document' },
  { value: 'fee_receipt', label: 'Fee Receipt' },
  { value: 'correspondence', label: 'Correspondence' },
  { value: 'appeal_doc', label: 'Appeal Document' },
  { value: 'other', label: 'Other' },
];

function formatDate(date: string | null | undefined): string {
  if (!date) return '-';
  // Standard YYYY-MM-DD format
  return new Date(date).toISOString().split('T')[0];
}

function formatFileSize(bytes: number | null | undefined): string {
  if (!bytes) return '-';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function isExpiringSoon(expiryDate: string | null | undefined): boolean {
  if (!expiryDate) return false;
  const daysUntilExpiry = Math.ceil(
    (new Date(expiryDate).getTime() - Date.now()) / (1000 * 60 * 60 * 24)
  );
  return daysUntilExpiry > 0 && daysUntilExpiry <= 30;
}

function isExpired(expiryDate: string | null | undefined): boolean {
  if (!expiryDate) return false;
  return new Date(expiryDate) < new Date();
}

export function DocumentManager({
  approvalId,
  currentUserId,
  readonly = false,
  onDocumentChange,
}: DocumentManagerProps) {
  const [documents, setDocuments] = useState<PipelineApprovalDocument[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showUploadForm, setShowUploadForm] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [deleting, setDeleting] = useState<string | null>(null);

  // Upload form state
  const [uploadData, setUploadData] = useState({
    document_type: 'supporting_doc' as ApprovalDocumentType,
    document_name: '',
    description: '',
    file_url: '',
    file_name: '',
    file_size: undefined as number | undefined,
    document_date: new Date().toISOString().split('T')[0],
    issue_date: '',
    expiry_date: '',
    reference_number: '',
    issuing_authority: '',
  });

  const [uploadingFile, setUploadingFile] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  async function handleFileSelect(file: File) {
    setUploadingFile(true);
    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('type', 'pipeline');
      formData.append('category', 'approval-documents');
      const response = await fetch('/api/storage/upload', {
        method: 'POST',
        credentials: 'include',
        body: formData,
      });
      if (!response.ok) {
        const errData = await response.json().catch(() => null);
        throw new Error(errData?.error || 'Upload failed');
      }
      const data = await response.json();
      setUploadData((prev) => ({
        ...prev,
        file_url: data.url,
        file_name: prev.file_name || file.name,
      }));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'File upload failed');
    } finally {
      setUploadingFile(false);
    }
  }

  const fetchDocuments = useCallback(async () => {
    try {
      const response = await fetch(`/api/pipeline/approvals/${approvalId}/documents`);
      if (!response.ok) throw new Error('Failed to fetch documents');
      const data = await response.json();
      setDocuments(data.data?.documents || []);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load documents');
    } finally {
      setLoading(false);
    }
  }, [approvalId]);

  useEffect(() => {
    fetchDocuments();
  }, [fetchDocuments]);

  async function handleUpload() {
    if (!uploadData.document_name || !uploadData.file_name) {
      setError('Document name and file name are required');
      return;
    }

    setUploading(true);
    setError(null);

    try {
      const input: Partial<UploadApprovalDocumentInput> = {
        document_type: uploadData.document_type,
        document_name: uploadData.document_name,
        description: uploadData.description || undefined,
        file_name: uploadData.file_name,
        file_url: uploadData.file_url || undefined,
        file_size: uploadData.file_size,
        document_date: uploadData.document_date || undefined,
        issue_date: uploadData.issue_date || undefined,
        expiry_date: uploadData.expiry_date || undefined,
        reference_number: uploadData.reference_number || undefined,
        issuing_authority: uploadData.issuing_authority || undefined,
        uploaded_by: currentUserId || 'unknown',
      };

      const response = await fetch(`/api/pipeline/approvals/${approvalId}/documents`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(input),
      });

      if (!response.ok) throw new Error('Failed to upload document');

      await fetchDocuments();
      setShowUploadForm(false);
      setUploadData({
        document_type: 'supporting_doc',
        document_name: '',
        description: '',
        file_url: '',
        file_name: '',
        file_size: undefined,
        document_date: new Date().toISOString().split('T')[0],
        issue_date: '',
        expiry_date: '',
        reference_number: '',
        issuing_authority: '',
      });
      onDocumentChange?.();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to upload document');
    } finally {
      setUploading(false);
    }
  }

  async function handleDelete(docId: string) {
    if (!confirm('Are you sure you want to delete this document?')) return;

    setDeleting(docId);
    setError(null);

    try {
      const response = await fetch(
        `/api/pipeline/approvals/${approvalId}/documents/${docId}`,
        { method: 'DELETE' }
      );

      if (!response.ok) throw new Error('Failed to delete document');

      await fetchDocuments();
      onDocumentChange?.();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to delete document');
    } finally {
      setDeleting(null);
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="w-6 h-6 animate-spin text-[var(--ff-text-secondary)]" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {error && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-3">
          <p className="text-sm text-red-600">{error}</p>
        </div>
      )}

      {/* Document List */}
      {documents.length > 0 ? (
        <div className="space-y-2">
          {documents.map((doc) => (
            <div
              key={doc.id}
              className="flex items-start gap-3 p-3 bg-[var(--ff-bg-secondary)] rounded-lg group"
            >
              <div className="flex-shrink-0 p-2 bg-[var(--ff-bg-primary)] rounded-lg">
                <FileText className="w-5 h-5 text-[var(--ff-accent)]" />
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                  <p className="text-sm font-medium text-[var(--ff-text-primary)] truncate">
                    {doc.document_name}
                  </p>
                  {doc.is_verified && (
                    <CheckCircle className="w-4 h-4 text-green-500 flex-shrink-0" />
                  )}
                  {isExpired(doc.expiry_date) && (
                    <span className="text-xs px-1.5 py-0.5 bg-red-100 text-red-600 rounded">
                      Expired
                    </span>
                  )}
                  {isExpiringSoon(doc.expiry_date) && !isExpired(doc.expiry_date) && (
                    <span className="text-xs px-1.5 py-0.5 bg-amber-100 text-amber-600 rounded flex items-center gap-1">
                      <AlertTriangle className="w-3 h-3" />
                      Expiring
                    </span>
                  )}
                </div>
                <p className="text-xs text-[var(--ff-text-secondary)] mt-0.5">
                  {DOCUMENT_TYPES.find((t) => t.value === doc.document_type)?.label || doc.document_type}
                  {doc.file_size && ` • ${formatFileSize(doc.file_size)}`}
                  {doc.reference_number && ` • Ref: ${doc.reference_number}`}
                </p>
                {doc.expiry_date && (
                  <p className="text-xs text-[var(--ff-text-tertiary)] mt-0.5 flex items-center gap-1">
                    <Calendar className="w-3 h-3" />
                    Expires: {formatDate(doc.expiry_date)}
                  </p>
                )}
              </div>
              <div className="flex items-center gap-1 sm:opacity-0 sm:group-hover:opacity-100 transition-opacity">
                {doc.file_url && (
                  <a
                    href={doc.file_url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="p-1.5 hover:bg-[var(--ff-bg-primary)] rounded"
                    title="Open document"
                  >
                    <ExternalLink className="w-4 h-4 text-[var(--ff-text-secondary)]" />
                  </a>
                )}
                {!readonly && (
                  <button
                    onClick={() => handleDelete(doc.id)}
                    disabled={deleting === doc.id}
                    className="p-1.5 hover:bg-red-50 rounded text-red-500 disabled:opacity-50"
                    title="Delete document"
                  >
                    {deleting === doc.id ? (
                      <Loader2 className="w-4 h-4 animate-spin" />
                    ) : (
                      <Trash2 className="w-4 h-4" />
                    )}
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      ) : (
        <p className="text-sm text-[var(--ff-text-tertiary)] text-center py-4">
          No documents uploaded yet
        </p>
      )}

      {/* Upload Button / Form */}
      {!readonly && !showUploadForm && (
        <button
          onClick={() => setShowUploadForm(true)}
          className="w-full flex items-center justify-center gap-2 px-4 py-3 border-2 border-dashed border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-secondary)] hover:border-[var(--ff-accent)] hover:text-[var(--ff-accent)] transition-colors"
        >
          <Upload className="w-4 h-4" />
          Add Document
        </button>
      )}

      {/* Upload Form */}
      {showUploadForm && (
        <div className="bg-[var(--ff-bg-secondary)] rounded-lg p-4 space-y-4">
          <div className="flex items-center justify-between">
            <h4 className="text-sm font-medium text-[var(--ff-text-primary)]">
              Add Document
            </h4>
            <button
              onClick={() => setShowUploadForm(false)}
              className="p-1 hover:bg-[var(--ff-bg-primary)] rounded"
            >
              <X className="w-4 h-4 text-[var(--ff-text-secondary)]" />
            </button>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="col-span-2">
              <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                Document Name *
              </label>
              <input
                type="text"
                value={uploadData.document_name}
                onChange={(e) =>
                  setUploadData({ ...uploadData, document_name: e.target.value })
                }
                placeholder="e.g., Wayleave Application Form"
                className="w-full px-3 py-2 border border-[var(--ff-border-light)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--ff-accent)] bg-[var(--ff-bg-primary)]"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                Document Type *
              </label>
              <select
                value={uploadData.document_type}
                onChange={(e) =>
                  setUploadData({
                    ...uploadData,
                    document_type: e.target.value as ApprovalDocumentType,
                  })
                }
                className="w-full px-3 py-2 border border-[var(--ff-border-light)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--ff-accent)] bg-[var(--ff-bg-primary)]"
              >
                {DOCUMENT_TYPES.map((type) => (
                  <option key={type.value} value={type.value}>
                    {type.label}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                Reference Number
              </label>
              <input
                type="text"
                value={uploadData.reference_number}
                onChange={(e) =>
                  setUploadData({ ...uploadData, reference_number: e.target.value })
                }
                placeholder="e.g., WL-2024-001"
                className="w-full px-3 py-2 border border-[var(--ff-border-light)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--ff-accent)] bg-[var(--ff-bg-primary)]"
              />
            </div>

            <div className="col-span-2">
              <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                File Name *
              </label>
              <input
                type="text"
                value={uploadData.file_name}
                onChange={(e) =>
                  setUploadData({ ...uploadData, file_name: e.target.value })
                }
                placeholder="e.g., wayleave_application.pdf"
                className="w-full px-3 py-2 border border-[var(--ff-border-light)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--ff-accent)] bg-[var(--ff-bg-primary)]"
              />
            </div>

            <div className="col-span-2">
              <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                File URL
              </label>
              <input
                type="file"
                ref={fileInputRef}
                accept=".pdf,.jpg,.jpeg,.png,.doc,.docx,.xls,.xlsx"
                className="hidden"
                onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) handleFileSelect(file);
                  e.target.value = '';
                }}
              />
              <div className="flex gap-2">
                <button
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  disabled={uploadingFile}
                  className="flex items-center gap-1.5 px-3 py-2 border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-primary)] disabled:opacity-50 text-sm whitespace-nowrap"
                  title="Upload file"
                >
                  {uploadingFile ? <Loader2 className="w-4 h-4 animate-spin" /> : <Upload className="w-4 h-4" />}
                  {uploadingFile ? 'Uploading...' : 'Upload'}
                </button>
                <input
                  type="url"
                  value={uploadData.file_url}
                  onChange={(e) =>
                    setUploadData({ ...uploadData, file_url: e.target.value })
                  }
                  placeholder="https://... or upload a file"
                  className="flex-1 px-3 py-2 border border-[var(--ff-border-light)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--ff-accent)] bg-[var(--ff-bg-primary)]"
                />
              </div>
              <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">
                Upload a file or paste a URL
              </p>
            </div>

            <div>
              <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                Issue Date
              </label>
              <input
                type="date"
                value={uploadData.issue_date}
                onChange={(e) =>
                  setUploadData({ ...uploadData, issue_date: e.target.value })
                }
                className="w-full px-3 py-2 border border-[var(--ff-border-light)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--ff-accent)] bg-[var(--ff-bg-primary)]"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                Expiry Date
              </label>
              <input
                type="date"
                value={uploadData.expiry_date}
                onChange={(e) =>
                  setUploadData({ ...uploadData, expiry_date: e.target.value })
                }
                className="w-full px-3 py-2 border border-[var(--ff-border-light)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--ff-accent)] bg-[var(--ff-bg-primary)]"
              />
            </div>

            <div className="col-span-2">
              <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                Issuing Authority
              </label>
              <input
                type="text"
                value={uploadData.issuing_authority}
                onChange={(e) =>
                  setUploadData({ ...uploadData, issuing_authority: e.target.value })
                }
                placeholder="e.g., City of Johannesburg"
                className="w-full px-3 py-2 border border-[var(--ff-border-light)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--ff-accent)] bg-[var(--ff-bg-primary)]"
              />
            </div>

            <div className="col-span-2">
              <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                Description
              </label>
              <textarea
                value={uploadData.description}
                onChange={(e) =>
                  setUploadData({ ...uploadData, description: e.target.value })
                }
                rows={2}
                placeholder="Optional description..."
                className="w-full px-3 py-2 border border-[var(--ff-border-light)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--ff-accent)] bg-[var(--ff-bg-primary)]"
              />
            </div>
          </div>

          <div className="flex gap-2">
            <button
              onClick={handleUpload}
              disabled={uploading || !uploadData.document_name || !uploadData.file_name}
              className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-[var(--ff-accent)] text-white rounded-lg hover:bg-[var(--ff-accent-hover)] disabled:opacity-50"
            >
              {uploading ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  Uploading...
                </>
              ) : (
                <>
                  <Upload className="w-4 h-4" />
                  Add Document
                </>
              )}
            </button>
            <button
              onClick={() => setShowUploadForm(false)}
              disabled={uploading}
              className="px-4 py-2 border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-primary)]"
            >
              Cancel
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export default DocumentManager;

/**
 * Approval Detail Drawer Component
 * Shows approval details and allows workflow actions
 * NOW WITH INLINE EDITING FOR APPROVAL DETAILS
 */

import { useState } from 'react';
import {
  X,
  CheckCircle,
  XCircle,
  Clock,
  AlertTriangle,
  FileText,
  User,
  Building2,
  Phone,
  Mail,
  MapPin,
  Send,
  MessageSquare,
  ChevronRight,
  ChevronDown,
  Pencil,
  Save,
  Calendar,
  DollarSign,
} from 'lucide-react';
import type {
  PipelineProjectApprovalWithType,
  ApprovalStatus,
  InternalApprovalStatus,
  ServiceAuthority,
} from '../types';
import { DocumentManager } from './DocumentManager';
import { AuthorityPicker } from './AuthorityPicker';

interface ApprovalDetailDrawerProps {
  approval: PipelineProjectApprovalWithType;
  isOpen: boolean;
  onClose: () => void;
  onUpdate: () => void;
  currentUserId?: string;
  currentUserRole?: 'pm' | 'ops' | 'admin' | 'viewer';
}

const STATUS_CONFIG: Record<
  ApprovalStatus,
  { label: string; color: string; bgColor: string }
> = {
  not_started: { label: 'Not Started', color: 'text-muted-foreground', bgColor: 'bg-secondary' },
  preparing: { label: 'Preparing', color: 'text-blue-600', bgColor: 'bg-blue-100' },
  internal_review: { label: 'Internal Review', color: 'text-blue-600', bgColor: 'bg-blue-100' },
  submitted: { label: 'Submitted', color: 'text-purple-600', bgColor: 'bg-purple-100' },
  in_review: { label: 'Under Review', color: 'text-yellow-600', bgColor: 'bg-yellow-100' },
  additional_info_required: { label: 'Additional Info Required', color: 'text-orange-600', bgColor: 'bg-orange-100' },
  approved: { label: 'Approved', color: 'text-green-600', bgColor: 'bg-green-100' },
  rejected: { label: 'Rejected', color: 'text-red-600', bgColor: 'bg-red-100' },
  conditionally_approved: { label: 'Conditionally Approved', color: 'text-amber-600', bgColor: 'bg-amber-100' },
  expired: { label: 'Expired', color: 'text-red-600', bgColor: 'bg-red-100' },
  renewed: { label: 'Renewed', color: 'text-green-600', bgColor: 'bg-green-100' },
  withdrawn: { label: 'Withdrawn', color: 'text-muted-foreground', bgColor: 'bg-secondary' },
};

const INTERNAL_STATUS_CONFIG: Record<
  InternalApprovalStatus,
  { label: string; color: string; bgColor: string }
> = {
  pending: { label: 'Pending PM Approval', color: 'text-yellow-600', bgColor: 'bg-yellow-100' },
  pm_approved: { label: 'PM Approved', color: 'text-blue-600', bgColor: 'bg-blue-100' },
  ops_approved: { label: 'Ops Approved', color: 'text-green-600', bgColor: 'bg-green-100' },
  rejected: { label: 'Rejected', color: 'text-red-600', bgColor: 'bg-red-100' },
};

type EditSection = 'timeline' | 'references' | 'financial' | 'details' | 'followup' | null;

interface TimelineEditData {
  application_date: string;
  issue_date: string;
  expiry_date: string;
  approval_date: string;
}

interface ReferencesEditData {
  application_reference: string;
  approval_reference: string;
}

interface FinancialEditData {
  application_fee: string;
  fee_paid: boolean;
  fee_paid_date: string;
  fee_receipt_reference: string;
}

interface DetailsEditData {
  conditions: string;
  coverage_description: string;
  notes: string;
}

interface FollowupEditData {
  next_followup_date: string;
  followup_notes: string;
}

function formatDate(date: string | null | undefined): string {
  if (!date) return '-';
  return new Date(date).toISOString().split('T')[0] ?? '-';
}

function formatCurrency(value: number | null | undefined): string {
  if (value === null || value === undefined) return '-';
  return new Intl.NumberFormat('en-ZA', {
    style: 'currency',
    currency: 'ZAR',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(value);
}

export function ApprovalDetailDrawer({
  approval,
  isOpen,
  onClose,
  onUpdate,
  currentUserId,
  currentUserRole = 'viewer',
}: ApprovalDetailDrawerProps) {
  const [loading, setLoading] = useState(false);
  const [showSubmitForm, setShowSubmitForm] = useState(false);
  const [showApproveForm, setShowApproveForm] = useState(false);
  const [togglingRequired, setTogglingRequired] = useState(false);
  const [showRejectForm, setShowRejectForm] = useState(false);
  const [showAuthorityPicker, setShowAuthorityPicker] = useState(false);
  const [savingAuthority, setSavingAuthority] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Inline editing state
  const [editingSection, setEditingSection] = useState<EditSection>(null);
  const [timelineData, setTimelineData] = useState<TimelineEditData>({
    application_date: approval.application_date || '',
    issue_date: approval.issue_date || '',
    expiry_date: approval.expiry_date || '',
    approval_date: approval.approval_date || '',
  });
  const [referencesData, setReferencesData] = useState<ReferencesEditData>({
    application_reference: approval.application_reference || '',
    approval_reference: approval.approval_reference || '',
  });
  const [financialData, setFinancialData] = useState<FinancialEditData>({
    application_fee: approval.application_fee?.toString() || '',
    fee_paid: approval.fee_paid || false,
    fee_paid_date: approval.fee_paid_date || '',
    fee_receipt_reference: approval.fee_receipt_reference || '',
  });
  const [detailsData, setDetailsData] = useState<DetailsEditData>({
    conditions: approval.conditions || '',
    coverage_description: approval.coverage_description || '',
    notes: approval.notes || '',
  });
  const [followupData, setFollowupData] = useState<FollowupEditData>({
    next_followup_date: approval.next_followup_date || '',
    followup_notes: approval.followup_notes || '',
  });

  // Form state for submission
  const [submitData, setSubmitData] = useState({
    application_date: new Date().toISOString().split('T')[0],
    application_reference: '',
    application_fee: '',
    notes: '',
  });

  // Form state for approval (issue_date/expiry_date auto-copied from uploaded document by backend)
  const [approveData, setApproveData] = useState({
    approval_date: new Date().toISOString().split('T')[0],
    approval_reference: '',
    conditions: '',
    notes: '',
  });

  // Form state for rejection
  const [rejectData, setRejectData] = useState({
    rejection_reason: '',
    notes: '',
  });

  if (!isOpen) return null;

  const statusConfig = STATUS_CONFIG[approval.status];
  const internalStatusConfig = approval.internal_status
    ? INTERNAL_STATUS_CONFIG[approval.internal_status]
    : null;

  // Determine what actions are available
  const canPmApprove =
    (currentUserRole === 'pm' || currentUserRole === 'admin') &&
    approval.internal_status === 'pending';
  const canOpsApprove =
    (currentUserRole === 'ops' || currentUserRole === 'admin') &&
    approval.internal_status === 'pm_approved';
  const canFullApprove =
    currentUserRole === 'admin' &&
    approval.internal_status === 'pending';
  const canSubmit =
    approval.status === 'not_started' &&
    approval.internal_status === 'ops_approved';
  const canMarkApproved =
    (currentUserRole === 'admin' || currentUserRole === 'ops') &&
    ['submitted', 'in_review', 'additional_info_required', 'conditionally_approved'].includes(approval.status);
  const canMarkRejected =
    (currentUserRole === 'admin' || currentUserRole === 'ops') &&
    ['submitted', 'in_review', 'additional_info_required', 'conditionally_approved'].includes(approval.status);

  const hasActions = canPmApprove || canOpsApprove || canFullApprove || canSubmit || canMarkApproved || canMarkRejected;
  const canEdit = ['admin', 'pm', 'ops'].includes(currentUserRole);

  // Reset edit data when starting to edit a section
  function startEdit(section: EditSection) {
    if (section === 'timeline') {
      setTimelineData({
        application_date: approval.application_date || '',
        issue_date: approval.issue_date || '',
        expiry_date: approval.expiry_date || '',
        approval_date: approval.approval_date || '',
      });
    } else if (section === 'references') {
      setReferencesData({
        application_reference: approval.application_reference || '',
        approval_reference: approval.approval_reference || '',
      });
    } else if (section === 'financial') {
      setFinancialData({
        application_fee: approval.application_fee?.toString() || '',
        fee_paid: approval.fee_paid || false,
        fee_paid_date: approval.fee_paid_date || '',
        fee_receipt_reference: approval.fee_receipt_reference || '',
      });
    } else if (section === 'details') {
      setDetailsData({
        conditions: approval.conditions || '',
        coverage_description: approval.coverage_description || '',
        notes: approval.notes || '',
      });
    } else if (section === 'followup') {
      setFollowupData({
        next_followup_date: approval.next_followup_date || '',
        followup_notes: approval.followup_notes || '',
      });
    }
    setEditingSection(section);
  }

  function cancelEdit() {
    setEditingSection(null);
    setError(null);
  }

  async function saveEdit() {
    setLoading(true);
    setError(null);
    try {
      const updateData: any = { updated_by: currentUserId };

      if (editingSection === 'timeline') {
        updateData.application_date = timelineData.application_date || null;
        updateData.issue_date = timelineData.issue_date || null;
        updateData.expiry_date = timelineData.expiry_date || null;
        updateData.approval_date = timelineData.approval_date || null;
      } else if (editingSection === 'references') {
        updateData.application_reference = referencesData.application_reference || null;
        updateData.approval_reference = referencesData.approval_reference || null;
      } else if (editingSection === 'financial') {
        updateData.application_fee = financialData.application_fee
          ? parseFloat(financialData.application_fee)
          : null;
        updateData.fee_paid = financialData.fee_paid;
        updateData.fee_paid_date = financialData.fee_paid_date || null;
        updateData.fee_receipt_reference = financialData.fee_receipt_reference || null;
      } else if (editingSection === 'details') {
        updateData.conditions = detailsData.conditions || null;
        updateData.coverage_description = detailsData.coverage_description || null;
        updateData.notes = detailsData.notes || null;
      } else if (editingSection === 'followup') {
        updateData.next_followup_date = followupData.next_followup_date || null;
        updateData.followup_notes = followupData.followup_notes || null;
      }

      const response = await fetch(`/api/pipeline/approvals/${approval.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updateData),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to update approval');
      }

      onUpdate();
      setEditingSection(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    } finally {
      setLoading(false);
    }
  }

  async function handleInternalApprove(action: 'pm_approve' | 'ops_approve' | 'full_approve' | 'reject') {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`/api/pipeline/approvals/${approval.id}/internal-approve`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action,
          approved_by: currentUserId,
          notes: action === 'reject' ? rejectData.rejection_reason : '',
          rejection_reason: action === 'reject' ? rejectData.rejection_reason : undefined,
        }),
      });
      if (!response.ok) throw new Error('Failed to update approval');
      onUpdate();
      setShowRejectForm(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    } finally {
      setLoading(false);
    }
  }

  async function handleSubmitApplication() {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`/api/pipeline/approvals/${approval.id}/submit`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          application_date: submitData.application_date,
          application_reference: submitData.application_reference || undefined,
          application_fee: submitData.application_fee
            ? parseFloat(submitData.application_fee)
            : undefined,
          notes: submitData.notes || undefined,
          updated_by: currentUserId,
        }),
      });
      if (!response.ok) throw new Error('Failed to submit application');
      onUpdate();
      setShowSubmitForm(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    } finally {
      setLoading(false);
    }
  }

  async function handleMarkApproved() {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`/api/pipeline/approvals/${approval.id}/approve`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          approval_date: approveData.approval_date,
          approval_reference: approveData.approval_reference,
          conditions: approveData.conditions || undefined,
          notes: approveData.notes || undefined,
          updated_by: currentUserId,
        }),
      });
      if (!response.ok) throw new Error('Failed to mark as approved');
      onUpdate();
      setShowApproveForm(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    } finally {
      setLoading(false);
    }
  }

  async function handleMarkRejected() {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`/api/pipeline/approvals/${approval.id}/reject`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          rejection_date: new Date().toISOString().split('T')[0],
          rejection_reason: rejectData.rejection_reason,
          notes: rejectData.notes || undefined,
          updated_by: currentUserId,
        }),
      });
      if (!response.ok) throw new Error('Failed to mark as rejected');
      onUpdate();
      setShowRejectForm(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    } finally {
      setLoading(false);
    }
  }

  async function handleAuthoritySelect(authority: ServiceAuthority | null) {
    if (!authority) {
      setShowAuthorityPicker(false);
      return;
    }

    setSavingAuthority(true);
    setError(null);
    try {
      const response = await fetch(`/api/pipeline/approvals/${approval.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          service_authority_id: authority.id,
          authority_name: authority.authority_name,
          authority_contact_name: authority.contact_name,
          authority_contact_email: authority.contact_email,
          authority_contact_phone: authority.contact_phone,
          authority_address: authority.physical_address,
          updated_by: currentUserId,
        }),
      });
      if (!response.ok) throw new Error('Failed to update authority');
      onUpdate();
      setShowAuthorityPicker(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save authority');
    } finally {
      setSavingAuthority(false);
    }
  }

  return (
    <>
    {/* WCAG 2.1.2: Escape key closes drawer */}
    <div
      className="fixed inset-0 z-50 flex justify-end"
      onKeyDown={(e) => { if (e.key === 'Escape') onClose(); }}
    >
      {/* Backdrop — decorative, aria-hidden so AT ignores it */}
      <div
        className="fixed inset-0 bg-black/50"
        aria-hidden="true"
        onClick={onClose}
      />

      {/* Drawer — WCAG: role=dialog + aria-modal + aria-labelledby (1.3.1, 4.1.2) */}
      <div
        className="relative w-full max-w-lg bg-[var(--ff-bg-primary)] shadow-xl overflow-y-auto"
        role="dialog"
        aria-modal="true"
        aria-labelledby="approval-drawer-title"
      >
        {/* Header */}
        <div className="sticky top-0 bg-[var(--ff-bg-primary)] border-b border-[var(--ff-border-light)] p-4 z-10">
          <div className="flex items-center justify-between">
            <div>
              <h2 id="approval-drawer-title" className="text-lg font-semibold text-[var(--ff-text-primary)]">
                {approval.approval_type_name}
              </h2>
              <p className="text-sm text-[var(--ff-text-secondary)]">
                {approval.approval_type_category}
              </p>
            </div>
            <button
              type="button"
              onClick={onClose}
              aria-label="Close approval drawer"
              className="p-2 hover:bg-[var(--ff-bg-secondary)] rounded-lg transition-colors focus:outline-none focus:ring-2 focus:ring-[var(--ff-accent)]"
            >
              <X className="w-5 h-5 text-[var(--ff-text-secondary)]" aria-hidden="true" />
            </button>
          </div>

          {/* Status badges */}
          <div className="flex flex-wrap gap-2 mt-3">
            <span
              className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-sm font-medium ${statusConfig.bgColor} ${statusConfig.color}`}
            >
              {statusConfig.label}
            </span>
            {internalStatusConfig && (
              <span
                className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-sm font-medium ${internalStatusConfig.bgColor} ${internalStatusConfig.color}`}
              >
                {internalStatusConfig.label}
              </span>
            )}
            <button
              onClick={async (e) => {
                e.stopPropagation();
                setTogglingRequired(true);
                try {
                  const res = await fetch(`/api/pipeline/approvals/${approval.id}`, {
                    method: "PUT",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ is_required: !approval.is_required }),
                  });
                  if (res.ok) onUpdate();
                } finally {
                  setTogglingRequired(false);
                }
              }}
              disabled={togglingRequired}
              className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-sm font-medium cursor-pointer transition-colors ${
                approval.is_required
                  ? "bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-300 hover:bg-red-200 dark:hover:bg-red-900/50"
                  : "bg-secondary text-muted-foreground hover:bg-secondary/80"
              } disabled:opacity-50`}
              title={approval.is_required ? "Click to mark as optional" : "Click to mark as required"}
            >
              {togglingRequired ? "..." : approval.is_required ? "Required" : "Optional"}
            </button>
          </div>
        </div>

        {/* Content */}
        <div className="p-4 space-y-6">
          {error && (
            <div className="bg-red-50 border border-red-200 rounded-lg p-3">
              <p className="text-sm text-red-600">{error}</p>
            </div>
          )}

          {/* WORKFLOW ACTIONS - PROMINENT PLACEMENT (top, always visible) */}
          {hasActions && (
            <div className="bg-blue-50 dark:bg-blue-900/20 border-2 border-blue-300 dark:border-blue-700 rounded-lg p-4">
              {/* Internal Approval Workflow */}
              {(canPmApprove || canOpsApprove || canFullApprove) && !showRejectForm && (
                <div>
                  <h3 className="text-sm font-semibold text-blue-900 dark:text-blue-300 mb-3 flex items-center gap-2">
                    <AlertTriangle className="w-4 h-4" />
                    Internal Approval Required
                  </h3>
                  {canPmApprove && (
                    <div className="flex flex-col gap-2">
                      <div className="flex gap-2">
                        <button
                          onClick={() => handleInternalApprove('pm_approve')}
                          disabled={loading}
                          className="flex-1 flex items-center justify-center gap-2 px-4 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 disabled:opacity-50 font-medium"
                        >
                          <CheckCircle className="w-5 h-5" />
                          PM Approve
                        </button>
                        <button
                          onClick={() => setShowRejectForm(true)}
                          disabled={loading}
                          className="flex-1 flex items-center justify-center gap-2 px-4 py-3 bg-red-600 text-white rounded-lg hover:bg-red-700 disabled:opacity-50 font-medium"
                        >
                          <XCircle className="w-5 h-5" />
                          Reject
                        </button>
                      </div>
                      {canFullApprove && (
                        <button
                          onClick={() => handleInternalApprove('full_approve')}
                          disabled={loading}
                          className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-emerald-700 text-white rounded-lg hover:bg-emerald-800 disabled:opacity-50 font-medium"
                        >
                          <CheckCircle className="w-5 h-5" />
                          <CheckCircle className="w-5 h-5 -ml-3" />
                          Full Approve (PM + Ops)
                        </button>
                      )}
                    </div>
                  )}
                  {canOpsApprove && (
                    <div className="flex gap-2">
                      <button
                        onClick={() => handleInternalApprove('ops_approve')}
