## 4. **STORAGE ADAPTER** (`storageAdapter.ts`, lines 38-149)

The unified storage interface:

```typescript
export class StorageAdapter {
  static async uploadFile(
    file: File | Buffer,
    type: string,         // 'pipeline'
    category: string,     // 'approval-documents'
    fileName?: string
  ): Promise<StorageUploadResult> {
    if (USE_VF_STORAGE) {
      try {
        return await this.uploadToVFServer(file, type, category, fileName);
      } catch (error) {
        // Fallback to local storage
        return await this.uploadToLocal(file, type, category, fileName);
      }
    }
    return await this.uploadToLocal(file, type, category, fileName);
  }

  // VF Server upload (port 8091)
  private static async uploadToVFServer(...): Promise<StorageUploadResult> {
    const formData = new FormData();
    const blob = new Blob([file]);
    formData.append('file', blob, fileName);

    const response = await fetch(`${VF_STORAGE_URL}/upload/${type}/${category}`, {
      method: 'POST',
      body: formData,
    });

    const result = await response.json();
    const path = `${type}/${category}/${actualFileName}`;

    // Return public HTTPS URL (nginx routes /storage/ → port 8091)
    const url = `https://vf.fibreflow.app/storage/${path}`;

    return {
      success: true,
      url,
      path,
      fileName: actualFileName,
      source: 'vf-server',
    };
  }
}
```

