// Upload form state — shared metadata for all files in a batch
interface UploadedFile {
  id: string;
  document_name: string;
  file_name: string;
  file_url: string;
  file_size?: number;
  uploading: boolean;
  error?: string;
}

const [uploadMeta, setUploadMeta] = useState({
  document_type: 'supporting_doc' as ApprovalDocumentType,
  description: '',
  document_date: new Date().toISOString().split('T')[0],
  issue_date: '',
  expiry_date: '',
  reference_number: '',
  issuing_authority: '',
});

const [uploadedFiles, setUploadedFiles] = useState<UploadedFile[]>([]);
const [uploadingFiles, setUploadingFiles] = useState(false);
const fileInputRef = useRef<HTMLInputElement>(null);

function fileNameWithoutExt(name: string): string {
  return name.replace(/\.[^.]+$/, '');
}

async function handleFilesSelect(files: FileList) {
  setUploadingFiles(true);
  setError(null);

  const newFiles: UploadedFile[] = Array.from(files).map((f) => ({
    id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    document_name: fileNameWithoutExt(f.name),
    file_name: f.name,
    file_url: '',
    file_size: f.size,
    uploading: true,
  }));

  setUploadedFiles((prev) => [...prev, ...newFiles]);

  await Promise.all(
    Array.from(files).map(async (file, idx) => {
      const fileId = newFiles[idx].id;
      try {
        const formData = new FormData();
        formData.append('file', file);
        formData.append('type', 'pipeline');
        formData.append('category', 'approval-documents');
        const response = await fetch('/api/storage/upload', {
          method: 'POST',
          credentials: 'include',
          body: formData,
        });
        if (!response.ok) {
          const errData = await response.json().catch(() => null);
          throw new Error(errData?.error || 'Upload failed');
        }
        const data = await response.json();
        setUploadedFiles((prev) =>
          prev.map((f) =>
            f.id === fileId ? { ...f, file_url: data.url, uploading: false } : f
          )
        );
      } catch (err) {
        const msg = err instanceof Error ? err.message : 'Upload failed';
        setUploadedFiles((prev) =>
          prev.map((f) =>
            f.id === fileId ? { ...f, uploading: false, error: msg } : f
          )
        );
      }
    })
  );

  setUploadingFiles(false);
}

