        };

        const response = await fetch(`/api/pipeline/approvals/${approvalId}/documents`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(input),
        });

        if (!response.ok) throw new Error(`Failed to save ${file.document_name}`);
