const { neon } = require('@neondatabase/serverless');
const sql = neon(process.env.DATABASE_URL);

(async () => {
  // 1. Check recent documents linked to POs
  const docs = await sql\`
    SELECT pd.document_type, pd.document_name, pd.file_url,
           po.po_number, po.external_po_number,
           s.name as supplier_name
    FROM procurement_documents pd
    JOIN purchase_orders po ON po.id = pd.entity_id
    LEFT JOIN suppliers s ON s.id = po.supplier_id
    WHERE pd.notes LIKE 'smartsheet:%'
      AND pd.is_active = true
    ORDER BY pd.created_at DESC
    LIMIT 15
  \`;
  console.log('=== LATEST 15 SYNCED DOCUMENTS ===');
  docs.forEach(d => console.log(\`  \${d.po_number} | \${d.document_type.padEnd(15)} | \${d.document_name.substring(0,50)} | \${d.supplier_name}\`));

  // 2. Document count by type
  const byType = await sql\`
    SELECT pd.document_type, COUNT(*) as cnt
    FROM procurement_documents pd
    WHERE pd.notes LIKE 'smartsheet:%' AND pd.is_active = true
    GROUP BY pd.document_type ORDER BY cnt DESC
  \`;
  console.log('\n=== DOCUMENTS BY TYPE ===');
  byType.forEach(t => console.log(\`  \${t.document_type.padEnd(15)}: \${t.cnt}\`));

  // 3. Check a few file URLs are valid
  const sample = await sql\`
    SELECT pd.file_url, pd.document_name, po.po_number
    FROM procurement_documents pd
    JOIN purchase_orders po ON po.id = pd.entity_id
    WHERE pd.notes LIKE 'smartsheet:%' AND pd.is_active = true
    ORDER BY pd.created_at DESC LIMIT 3
  \`;
  console.log('\n=== SAMPLE FILE URLS ===');
  sample.forEach(s => console.log(\`  \${s.po_number}: \${s.file_url}\`));

  // 4. Total POs with documents vs without
  const coverage = await sql\`
    SELECT
      (SELECT COUNT(DISTINCT entity_id) FROM procurement_documents WHERE notes LIKE 'smartsheet:%' AND is_active = true) as pos_with_docs,
      (SELECT COUNT(*) FROM purchase_orders WHERE external_po_number IS NOT NULL) as total_smartsheet_pos
  \`;
  console.log('\n=== PO DOCUMENT COVERAGE ===');
  console.log(\`  POs with documents: \${coverage[0].pos_with_docs} / \${coverage[0].total_smartsheet_pos}\`);
})();
