// ============= Invoices Tab Component =============
// Display invoice status and list

import React from 'react';
import { FileCheck } from 'lucide-react';
import { GlassCard, StatusBadge } from '../../../../../components/ui';
import type { PurchaseOrder } from '../../../../../types/procurement/po.types';

interface InvoicesTabProps {
  po: PurchaseOrder;
}

export const InvoicesTab: React.FC<InvoicesTabProps> = ({ po }) => {
  return (
    <div className="space-y-6">
      <GlassCard className="p-6">
        <h3 className="text-lg font-semibold mb-4 flex items-center">
          <FileCheck className="h-5 w-5 mr-2" />
          Invoice Status
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <p>
              <span className="font-medium">Status:</span>{' '}
              <StatusBadge status={po.invoiceStatus} />
            </p>
          </div>
        </div>
      </GlassCard>

      <GlassCard className="p-6">
        <h4 className="font-semibold mb-4">Invoices</h4>
        <p className="text-center text-muted-foreground">No invoices submitted yet</p>
      </GlassCard>
    </div>
  );
};

// ============= History Tab Component =============
// Display activity history timeline

import React from 'react';
import { Clock } from 'lucide-react';
import { GlassCard } from '../../../../../components/ui';
import type { PurchaseOrder } from '../../../../../types/procurement/po.types';
import { formatterService } from '../../../../../services/core/formatting';

interface HistoryTabProps {
  po: PurchaseOrder;
}

export const HistoryTab: React.FC<HistoryTabProps> = ({ po }) => {
  const formatDate = (date: Date | undefined) =>
    date ? formatterService.date(date, { dateStyle: 'long' }) : '-';

  const activities = [
    { date: po.createdAt, action: 'Purchase Order created', user: po.createdBy },
    po.issuedAt && { date: po.issuedAt, action: 'Purchase Order issued', user: po.issuedBy },
    po.sentAt && { date: po.sentAt, action: 'Purchase Order sent to supplier', user: po.issuedBy },
    po.acknowledgedAt && {
      date: po.acknowledgedAt,
      action: 'Purchase Order acknowledged by supplier',
      user: 'Supplier'
    }
  ].filter(Boolean);

  return (
    <div className="space-y-4">
      <GlassCard className="p-6">
        <h3 className="text-lg font-semibold mb-4 flex items-center">
          <Clock className="h-5 w-5 mr-2" />
          Activity History
        </h3>

        <div className="space-y-4">
          {activities.map((entry: any, index) => (
            <div
              key={index}
              className="flex items-start space-x-4 border-l-2 border-blue-500 pl-4"
            >
              <div className="flex-1">
                <p className="font-medium text-foreground">{entry.action}</p>
                <p className="text-sm text-muted-foreground">by {entry.user}</p>
                <p className="text-xs text-muted-foreground">{formatDate(entry.date)}</p>
              </div>
            </div>
          ))}
        </div>
      </GlassCard>
    </div>
  );
};

// ============= Delivery Tab Component =============
// Display delivery status and notes

import React from 'react';
import { Truck } from 'lucide-react';
import { GlassCard, StatusBadge } from '../../../../../components/ui';
import type { PurchaseOrder } from '../../../../../types/procurement/po.types';
import { formatterService } from '../../../../../services/core/formatting';

interface DeliveryTabProps {
  po: PurchaseOrder;
}

export const DeliveryTab: React.FC<DeliveryTabProps> = ({ po }) => {
  const formatDate = (date: Date | undefined) =>
    date ? formatterService.date(date, { dateStyle: 'long' }) : '-';

  return (
    <div className="space-y-6">
      <GlassCard className="p-6">
        <h3 className="text-lg font-semibold mb-4 flex items-center">
          <Truck className="h-5 w-5 mr-2" />
          Delivery Status
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <p>
              <span className="font-medium">Status:</span>{' '}
              <StatusBadge status={po.deliveryStatus} />
            </p>
            <p className="mt-2">
              <span className="font-medium">Expected Date:</span> {formatDate(po.expectedDeliveryDate)}
            </p>
            {po.actualDeliveryDate && (
              <p className="mt-2">
                <span className="font-medium">Actual Date:</span> {formatDate(po.actualDeliveryDate)}
              </p>
            )}
          </div>
          <div>
            <p>
              <span className="font-medium">Partial Delivery:</span>{' '}
              {po.partialDeliveryAllowed ? 'Allowed' : 'Not Allowed'}
            </p>
          </div>
        </div>
      </GlassCard>

      <GlassCard className="p-6">
        <h4 className="font-semibold mb-4">Delivery Notes</h4>
        <p className="text-center text-muted-foreground">No delivery notes available</p>
      </GlassCard>
    </div>
  );
};

/**
 * Procurement & Accounting Document Types
 * For uploaded documents on POs, GRNs, Invoices, RFQs, Quotes, and accounting entities
 */

export interface ProcurementDocument {
  id: string;
  entityType: string;
  entityId: string;
  documentType: ProcurementDocumentType | AccountingDocumentType;
  documentName: string;
  fileUrl: string;
  filePath?: string;
  fileSize?: number;
  mimeType?: string;
  uploadedBy: string;
  uploadedByName?: string;
  uploadedAt: string;
  notes?: string;
  isActive: boolean;
}

/** Document with cross-module link information */
export interface LinkedDocument extends ProcurementDocument {
  source: 'direct' | 'linked';
  linkReason?: string;
}

export type ProcurementEntityType =
  | 'purchase_order'
  | 'goods_receipt_note'
  | 'vendor_invoice'
  | 'rfq_response'
  | 'supplier_quote';

export type AccountingEntityType =
  | 'supplier_invoice'
  | 'supplier_payment'
  | 'customer_invoice'
  | 'customer_payment'
  | 'credit_note';

export type DocumentEntityType = ProcurementEntityType | AccountingEntityType;

export type ProcurementDocumentType =
  | 'quote_pdf'
  | 'invoice'
  | 'delivery_note'
  | 'grv'
  | 'receipt'
  | 'contract'
  | 'image'
  | 'other';

export type AccountingDocumentType =
  | 'proof_of_payment'
  | 'bank_statement'
  | 'remittance_advice'
  | 'credit_note_doc'
  | 'invoice'
  | 'receipt'
  | 'other';

export const DOCUMENT_TYPE_LABELS: Record<ProcurementDocumentType, string> = {
  quote_pdf: 'Supplier Quote',
  invoice: 'Invoice',
  delivery_note: 'Delivery Note',
  grv: 'GRV (Goods Return)',
  receipt: 'Receipt',
  contract: 'Contract',
  image: 'Photo/Image',
  other: 'Other',
};

export const ACCOUNTING_DOCUMENT_TYPE_LABELS: Record<AccountingDocumentType, string> = {
  proof_of_payment: 'Proof of Payment',
  bank_statement: 'Bank Statement',
  remittance_advice: 'Remittance Advice',
  credit_note_doc: 'Credit Note',
  invoice: 'Invoice',
  receipt: 'Receipt',
  other: 'Other',
};

// ============= PO Detail Tabs Component =============
// Tab navigation for PO detail modal

import React from 'react';
import {
  FileText,
  Package,
  Truck,
  FileCheck,
  Clock,
  LucideIcon
} from 'lucide-react';

interface Tab {
  key: string;
  label: string;
  icon: LucideIcon;
}

const tabs: Tab[] = [
  { key: 'details', label: 'Details', icon: FileText },
  { key: 'items', label: 'Line Items', icon: Package },
  { key: 'delivery', label: 'Delivery', icon: Truck },
  { key: 'invoices', label: 'Invoices', icon: FileCheck },
  { key: 'history', label: 'History', icon: Clock }
];

interface PODetailTabsProps {
  activeTab: string;
  onTabChange: (tab: string) => void;
}

export const PODetailTabs: React.FC<PODetailTabsProps> = ({
  activeTab,
  onTabChange
}) => {
  return (
    <div className="border-b">
      <nav className="flex space-x-8 px-6">
        {tabs.map((tab) => (
          <button
            key={tab.key}
            onClick={() => onTabChange(tab.key)}
            className={`py-4 px-2 border-b-2 font-medium text-sm flex items-center space-x-2 ${
              activeTab === tab.key
                ? 'border-blue-500 text-blue-600'
                : 'border-transparent text-muted-foreground hover:text-muted-foreground hover:border-border'
            }`}
          >
            <tab.icon className="h-4 w-4" />
            <span>{tab.label}</span>
          </button>
        ))}
      </nav>
    </div>
  );
};

// ============= PO Detail Modal Component =============
// Main modal for viewing purchase order details

import React, { useState } from 'react';
import { usePOData, usePOActions } from '../hooks';
import { PODetailHeader } from './PODetailHeader';
import { PODetailTabs } from './PODetailTabs';
import { LoadingState, ErrorState } from './POModalStates';
import { PORejectModal } from './PORejectModal';
import {
  DetailsTab,
  ItemsTab,
  DeliveryTab,
  InvoicesTab,
  HistoryTab
} from './detail-modal-tabs';
import type { PurchaseOrder } from '../../../../types/procurement/po.types';

interface PODetailModalProps {
  poId: string;
  onClose: () => void;
  onUpdated: () => void;
}

export const PODetailModal: React.FC<PODetailModalProps> = ({
  poId,
  onClose,
  onUpdated
}) => {
  const [activeTab, setActiveTab] = useState('details');

  // Data fetching
  const { po, items, loading, error, reload } = usePOData(poId);

  // Actions
  const {
    actionLoading,
    error: actionError,
    showRejectModal,
    handleStatusChange,
    handleSubmitForApproval,
    handleApprove,
    handleReject,
    handleRejectWithReason,
    closeRejectModal
  } = usePOActions({ po, onUpdated, onReload: reload });

  // Show loading state
  if (loading) {
    return <LoadingState />;
  }

  // Show error state
  if (error || actionError) {
    return (
      <ErrorState
        error={error || actionError || 'An error occurred'}
        onClose={onClose}
        onRetry={reload}
      />
    );
  }

  // Guard against null PO
  if (!po) {
    return null;
  }

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
      <div className="bg-card rounded-lg shadow-2xl w-full max-w-6xl mx-4 max-h-[90vh] overflow-hidden">
        {/* Header */}
        <PODetailHeader
          po={po as PurchaseOrder & { version?: number; approvedBy?: string; approvedAt?: string }}
          actionLoading={actionLoading}
          onApprove={handleApprove}
          onReject={handleReject}
          onStatusChange={handleStatusChange}
          onSubmitForApproval={handleSubmitForApproval}
          onClose={onClose}
        />

        {/* Tabs */}
        <PODetailTabs activeTab={activeTab} onTabChange={setActiveTab} />

        {/* Content */}
        <div className="p-6 overflow-y-auto max-h-[calc(90vh-200px)]">
          {activeTab === 'details' && <DetailsTab po={po} />}
          {activeTab === 'items' && <ItemsTab items={items} currency={po.currency} />}
          {activeTab === 'delivery' && <DeliveryTab po={po} />}
          {activeTab === 'invoices' && <InvoicesTab po={po} />}
          {activeTab === 'history' && <HistoryTab po={po} />}
        </div>
      </div>

      {/* Reject Modal */}
      {showRejectModal && (
        <PORejectModal
          poNumber={po.poNumber}
          onConfirm={handleRejectWithReason}
          onCancel={closeRejectModal}
          loading={actionLoading === 'reject'}
        />
      )}
    </div>
  );
};

