  mss: 'Maintenance Service Schedule',
  contract: 'Contract',
  amendment: 'Amendment',
  wayleave: 'Wayleave Agreement',
  permit: 'Permit',
  other: 'Other Document',
};

/**
 * Confidence level thresholds for UI display
 */
export const CONFIDENCE_THRESHOLDS = {
  HIGH: 0.85,    // Green - high confidence
  MEDIUM: 0.60,  // Yellow - review suggested
  LOW: 0,        // Red - manual verification needed
} as const;

/**
 * Get confidence level for display
 */
export function getConfidenceLevel(confidence: number): 'high' | 'medium' | 'low' {
  if (confidence >= CONFIDENCE_THRESHOLDS.HIGH) return 'high';
  if (confidence >= CONFIDENCE_THRESHOLDS.MEDIUM) return 'medium';
  return 'low';
}

/**
 * Get confidence color class
 */
export function getConfidenceColorClass(confidence: number): string {
  const level = getConfidenceLevel(confidence);
  switch (level) {
    case 'high': return 'text-green-400 border-green-500/30 bg-green-500/10';
    case 'medium': return 'text-yellow-400 border-yellow-500/30 bg-yellow-500/10';
    case 'low': return 'text-red-400 border-red-500/30 bg-red-500/10';
  }
}

/**
 * Client PO PDF Extraction API
 * POST /api/projects/[projectId]/client-pos/extract-from-pdf
 *
 * Accepts PDF upload, converts to image, extracts data via VLM
 * Returns extracted data and document URL for pre-populating the create form
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import formidable from 'formidable';
import { promises as fs } from 'fs';
import path from 'path';
import { exec } from 'child_process';
import { promisify } from 'util';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { VFStorageService } from '@/services/vfStorageAdapter';
import { extractPOFromImage, extractPOFromMultipleImages } from '@/modules/projects/services/poExtractionService';
import type { POExtractionAPIResponse } from '@/modules/projects/types/po-extraction.types';

const execAsync = promisify(exec);

// Disable body parsing - we handle multipart form data
export const config = {
  api: {
    bodyParser: false,
  },
};

const MAX_FILE_SIZE = 20 * 1024 * 1024; // 20MB
const ALLOWED_TYPES = ['application/pdf'];

export default withAuth(withErrorHandler(async (
  req: NextApiRequest,
  res: NextApiResponse
) => {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  const userId = (req as AuthenticatedNextApiRequest).user.id;
  const projectId = req.query.projectId as string;

  if (!projectId) {
    return apiResponse.badRequest(res, 'Project ID is required');
  }

  const startTime = Date.now();

  try {
    // Parse multipart form data
    const form = formidable({
      maxFileSize: MAX_FILE_SIZE,
      keepExtensions: true,
    });

    const [, files] = await form.parse(req);
    const uploadedFile = Array.isArray(files.file) ? files.file[0] : files.file;

    if (!uploadedFile) {
      return apiResponse.badRequest(res, 'No file uploaded');
    }

    // Validate file type
    const mimeType = uploadedFile.mimetype || '';
    if (!ALLOWED_TYPES.includes(mimeType)) {
      return apiResponse.badRequest(res, `Invalid file type: ${mimeType}. Only PDF files are allowed.`);
    }

    const originalName = uploadedFile.originalFilename || 'document.pdf';
    log.info('[POExtraction] Processing PDF upload', {
      projectId,
      filename: originalName,
      size: uploadedFile.size,
    });

    // Convert PDF to images using pdftoppm
    const images = await convertPdfToImages(uploadedFile.filepath);

    if (images.length === 0) {
      return apiResponse.internalError(res, new Error('Failed to convert PDF to images'));
    }

    log.info('[POExtraction] PDF converted to images', {
      pageCount: images.length,
      filename: originalName,
    });

    // Extract data from images via VLM
    const firstImage = images[0];
    if (!firstImage) {
      return apiResponse.internalError(res, new Error('No images available for extraction'));
    }

    const extraction = images.length === 1
      ? await extractPOFromImage(firstImage, originalName)
      : await extractPOFromMultipleImages(images, originalName);

    // Upload original PDF to VF Storage regardless of extraction success
    const vfStorage = new VFStorageService();
    const timestamp = Date.now();
    const sanitizedName = originalName.replace(/[^a-zA-Z0-9.-]/g, '_');
    const storagePath = `${projectId}_${timestamp}_${sanitizedName}`;

    const pdfBuffer = await fs.readFile(uploadedFile.filepath);
    const uploadResult = await vfStorage.uploadFile(
      pdfBuffer,
      'procurement',
      'client-pos',
      storagePath
    );

    // Clean up temp files
    await cleanupTempFiles(uploadedFile.filepath);

    const response: POExtractionAPIResponse = {
      success: extraction.success,
      extraction: extraction.success ? {
        poNumber: extraction.poNumber,
        reference: extraction.reference,
        poDate: extraction.poDate,
        quantity: extraction.quantity,
        unitPrice: extraction.unitPrice,
        vatRate: extraction.vatRate,
        subtotal: extraction.subtotal,
        vatAmount: extraction.vatAmount,
        total: extraction.total,
        description: extraction.description,
        confidence: extraction.confidence,
      } : null,
      documentUrl: uploadResult.url,
      documentName: originalName,
      error: extraction.error,
      processingTimeMs: Date.now() - startTime,
    };

    log.info('[POExtraction] Extraction complete', {
      projectId,
      filename: originalName,
      success: extraction.success,
      confidence: extraction.confidence,
      processingTimeMs: response.processingTimeMs,
    });

    return apiResponse.success(res, response);
  } catch (error) {
    log.error('[POExtraction] Failed to process PDF', { projectId, error });
    return apiResponse.internalError(res, error instanceof Error ? error : new Error('Failed to process PDF'));
  }
}));

/**
 * Convert PDF to images using pdftoppm
 * Returns array of base64-encoded images
 */
async function convertPdfToImages(pdfPath: string): Promise<string[]> {
  const outputDir = path.dirname(pdfPath);
  const outputPrefix = path.join(outputDir, 'page');

  try {
    // Use pdftoppm to convert PDF to JPEG images
    // -jpeg: output JPEG format
    // -r 150: 150 DPI (good balance of quality and size)
    // -scale-to 1024: max dimension 1024px (VLM limit)
    await execAsync(`pdftoppm -jpeg -r 150 -scale-to 1024 "${pdfPath}" "${outputPrefix}"`);

    // Find all generated images
    const files = await fs.readdir(outputDir);
    const imageFiles = files
      .filter(f => f.startsWith('page') && f.endsWith('.jpg'))
      .sort((a, b) => {
        // Sort by page number
        const numA = parseInt(a.match(/page-?(\d+)/)?.[1] || '0');
        const numB = parseInt(b.match(/page-?(\d+)/)?.[1] || '0');
        return numA - numB;
      });

    if (imageFiles.length === 0) {
      log.warn('[POExtraction] No images generated from PDF');
      return [];
    }

    // Read images and convert to base64
    const images: string[] = [];
    for (const imageFile of imageFiles) {
      const imagePath = path.join(outputDir, imageFile);
      const imageBuffer = await fs.readFile(imagePath);
      const base64 = imageBuffer.toString('base64');
      images.push(`data:image/jpeg;base64,${base64}`);

      // Clean up image file
      await fs.unlink(imagePath).catch(() => { /* ignore */ });
    }

    return images;
  } catch (error) {
    log.error('[POExtraction] PDF conversion failed', {
      error: error instanceof Error ? error.message : 'Unknown',
    });
    return [];
  }
}

/**
 * Clean up temporary files
 */
async function cleanupTempFiles(filePath: string): Promise<void> {
  try {
    await fs.unlink(filePath);
  } catch {
    // Ignore cleanup errors
  }
}

/**
 * Project Documents API - List and Create
 * GET /api/projects/[projectId]/documents - List project documents
 * POST /api/projects/[projectId]/documents - Upload new document
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import formidable from 'formidable';
import { promises as fs } from 'fs';
import { withErrorHandler } from '@/lib/api-error-handler';
import { createLoggedSql } from '@/lib/db-logger';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { VFStorageService, normalizeStorageUrl } from '@/services/vfStorageAdapter';
import type { ProjectDocument, ProjectDocumentCreateInput, ProjectDocumentType } from '@/modules/projects/types/po-extraction.types';

const sql = createLoggedSql(process.env.DATABASE_URL!);

// Disable body parsing for POST (multipart form data)
export const config = {
  api: {
    bodyParser: false,
  },
};

const MAX_FILE_SIZE = 50 * 1024 * 1024; // 50MB for documents
const ALLOWED_TYPES = ['application/pdf', 'image/jpeg', 'image/png', 'image/webp'];
const VALID_DOC_TYPES: ProjectDocumentType[] = ['bss', 'mss', 'contract', 'amendment', 'wayleave', 'permit', 'other'];

export default withAuth(withErrorHandler(async (
  req: NextApiRequest,
  res: NextApiResponse
) => {
  const userId = (req as AuthenticatedNextApiRequest).user.id;
  const projectId = req.query.projectId as string;

  if (!projectId) {
    return apiResponse.badRequest(res, 'Project ID is required');
  }

  // GET - List documents
  if (req.method === 'GET') {
    return handleGet(req, res, projectId);
  }

  // POST - Upload document
  if (req.method === 'POST') {
    return handlePost(req, res, projectId, userId);
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}));

async function handleGet(
  req: NextApiRequest,
  res: NextApiResponse,
  projectId: string
) {
  try {
    const documentType = req.query.type as string | undefined;
    const clientPoId = req.query.clientPoId as string | undefined;
    const activeOnly = req.query.activeOnly !== 'false'; // Default to true

    // Build query based on filters - avoid empty sql fragments
    let documents;
    if (documentType && clientPoId) {
      documents = await sql`
        SELECT pd.*, cpo.po_number as client_po_number
        FROM project_documents pd
        LEFT JOIN client_purchase_orders cpo ON cpo.id = pd.client_po_id
        WHERE pd.project_id = ${projectId}
          AND (${!activeOnly} OR pd.is_active = true)
          AND pd.document_type = ${documentType}
          AND pd.client_po_id = ${clientPoId}
        ORDER BY pd.uploaded_at DESC
      `;
    } else if (documentType) {
      documents = await sql`
        SELECT pd.*, cpo.po_number as client_po_number
        FROM project_documents pd
        LEFT JOIN client_purchase_orders cpo ON cpo.id = pd.client_po_id
        WHERE pd.project_id = ${projectId}
          AND (${!activeOnly} OR pd.is_active = true)
          AND pd.document_type = ${documentType}
        ORDER BY pd.uploaded_at DESC
      `;
    } else if (clientPoId) {
      documents = await sql`
        SELECT pd.*, cpo.po_number as client_po_number
        FROM project_documents pd
        LEFT JOIN client_purchase_orders cpo ON cpo.id = pd.client_po_id
        WHERE pd.project_id = ${projectId}
          AND (${!activeOnly} OR pd.is_active = true)
          AND pd.client_po_id = ${clientPoId}
        ORDER BY pd.uploaded_at DESC
      `;
    } else {
      documents = await sql`
        SELECT pd.*, cpo.po_number as client_po_number
        FROM project_documents pd
        LEFT JOIN client_purchase_orders cpo ON cpo.id = pd.client_po_id
        WHERE pd.project_id = ${projectId}
          AND (${!activeOnly} OR pd.is_active = true)
        ORDER BY pd.uploaded_at DESC
      `;
    }

    return apiResponse.success(res, {
      documents: documents.map(transformDocument),
      count: documents.length,
    });
  } catch (error) {
    log.error('Failed to fetch project documents', { projectId, error });
    return apiResponse.databaseError(res, error, 'Failed to fetch documents');
  }
}

async function handlePost(
  req: NextApiRequest,
  res: NextApiResponse,
  projectId: string,
  userId: string
) {
  try {
    // Parse multipart form data
    const form = formidable({
      maxFileSize: MAX_FILE_SIZE,
      keepExtensions: true,
    });

    const [fields, files] = await form.parse(req);
    const uploadedFile = Array.isArray(files.file) ? files.file[0] : files.file;

    if (!uploadedFile) {
      return apiResponse.badRequest(res, 'No file uploaded');
    }

    // Validate file type
    const mimeType = uploadedFile.mimetype || '';
    if (!ALLOWED_TYPES.includes(mimeType)) {
      return apiResponse.badRequest(res, `Invalid file type: ${mimeType}`);
    }

    // Get form fields
    const documentType = getFieldValue(fields.documentType) as ProjectDocumentType;
    const description = getFieldValue(fields.description);
    const version = getFieldValue(fields.version);
    const effectiveDate = getFieldValue(fields.effectiveDate);
    const expiryDate = getFieldValue(fields.expiryDate);
    const clientPoId = getFieldValue(fields.clientPoId);

    // Validate document type
    if (!documentType || !VALID_DOC_TYPES.includes(documentType)) {
      return apiResponse.badRequest(res, `Invalid document type: ${documentType}`);
    }

    const originalName = uploadedFile.originalFilename || 'document.pdf';

    // For BSS/MSS, deactivate existing active documents of same type
    if (documentType === 'bss' || documentType === 'mss') {
      await sql`
        UPDATE project_documents
        SET is_active = false, updated_at = NOW()
        WHERE project_id = ${projectId}
          AND document_type = ${documentType}
          AND is_active = true
      `;
      log.info('[ProjectDocs] Deactivated previous document', {
        projectId,
        documentType,
      });
    }

    // Upload to VF Storage - use flat folder structure with projectId in filename
    const vfStorage = new VFStorageService();
    const timestamp = Date.now();
    const sanitizedName = originalName.replace(/[^a-zA-Z0-9.-]/g, '_');
    // Include projectId in filename for flat storage structure
    const storagePath = `${projectId}_${documentType}_${timestamp}_${sanitizedName}`;

    const fileBuffer = await fs.readFile(uploadedFile.filepath);
    const uploadResult = await vfStorage.uploadFile(
      fileBuffer,
      'procurement',
      'project-docs',
      storagePath
    );

    // Clean up temp file
    await fs.unlink(uploadedFile.filepath).catch(() => { /* ignore */ });

    // Insert document record
    const result = await sql`
      INSERT INTO project_documents (
        project_id,
        document_type,
        document_name,
        file_url,
        file_path,
        file_size,
        mime_type,
        description,
        version,
        effective_date,
        expiry_date,
        client_po_id,
        uploaded_by
      ) VALUES (
        ${projectId},
        ${documentType},
        ${originalName},
        ${uploadResult.url},
        ${uploadResult.path},
        ${uploadedFile.size},
        ${mimeType},
        ${description || null},
        ${version || null},
        ${effectiveDate || null},
        ${expiryDate || null},
        ${clientPoId || null},
        ${userId || 'system'}
      )
      RETURNING *
    `;

    const newDoc = result[0];
    if (!newDoc) {
      return apiResponse.internalError(res, new Error('Failed to create document record'));
    }

    log.info('[ProjectDocs] Document uploaded', {
      projectId,
      documentId: newDoc.id,
      documentType,
      filename: originalName,
      size: uploadedFile.size,
    });

    return apiResponse.created(res, {
      document: transformDocument(newDoc),
    });
  } catch (error) {
    log.error('Failed to upload project document', { projectId, error });
    return apiResponse.databaseError(res, error, 'Failed to upload document');
  }
}

function getFieldValue(field: string | string[] | undefined): string | null {
  if (!field) return null;
  return Array.isArray(field) ? (field[0] ?? null) : field;
}

function transformDocument(row: Record<string, unknown>): ProjectDocument {
  return {
    id: row.id as string,
    projectId: row.project_id as string,
    documentType: row.document_type as ProjectDocumentType,
    documentName: row.document_name as string,
    fileUrl: normalizeStorageUrl(row.file_url as string) || '',
    filePath: row.file_path as string | undefined,
    fileSize: row.file_size as number | undefined,
    mimeType: row.mime_type as string | undefined,
    description: row.description as string | undefined,
    version: row.version as string | undefined,
    effectiveDate: row.effective_date as string | undefined,
    expiryDate: row.expiry_date as string | undefined,
    clientPoId: row.client_po_id as string | undefined,
    uploadedBy: row.uploaded_by as string,
    uploadedAt: row.uploaded_at as string,
    isActive: row.is_active as boolean,
    createdAt: row.created_at as string,
    updatedAt: row.updated_at as string,
  };
}

-- Migration 151: Client PO Documents and PDF Import Support
-- Adds document storage for Client POs and project documents (BSS, MSS)

-- Add document fields to client_purchase_orders for PDF import tracking
ALTER TABLE client_purchase_orders ADD COLUMN IF NOT EXISTS source_document_url VARCHAR(500);
ALTER TABLE client_purchase_orders ADD COLUMN IF NOT EXISTS source_document_name VARCHAR(255);
ALTER TABLE client_purchase_orders ADD COLUMN IF NOT EXISTS vlm_extraction_data JSONB;
ALTER TABLE client_purchase_orders ADD COLUMN IF NOT EXISTS vlm_confidence_score DECIMAL(3,2);

-- New project_documents table for BSS, MSS, and other project docs
CREATE TABLE IF NOT EXISTS project_documents (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  document_type VARCHAR(50) NOT NULL CHECK (document_type IN (
    'bss', 'mss', 'contract', 'amendment', 'wayleave', 'permit', 'other'
  )),
  document_name VARCHAR(255) NOT NULL,
  file_url TEXT NOT NULL,
  file_path VARCHAR(500),
  file_size INTEGER,
  mime_type VARCHAR(100),
  description TEXT,
  version VARCHAR(50),
  effective_date DATE,
  expiry_date DATE,
  client_po_id UUID REFERENCES client_purchase_orders(id) ON DELETE SET NULL,
  uploaded_by VARCHAR(255) NOT NULL,
  uploaded_at TIMESTAMPTZ DEFAULT NOW(),
  is_active BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Indexes for project_documents
CREATE INDEX IF NOT EXISTS idx_project_docs_project ON project_documents(project_id);
CREATE INDEX IF NOT EXISTS idx_project_docs_type ON project_documents(document_type);
CREATE INDEX IF NOT EXISTS idx_project_docs_client_po ON project_documents(client_po_id);

-- One active BSS/MSS per project (constraint)
CREATE UNIQUE INDEX IF NOT EXISTS idx_project_docs_unique_active
  ON project_documents(project_id, document_type)
  WHERE document_type IN ('bss', 'mss') AND is_active = true;

-- Add updated_at trigger
CREATE OR REPLACE FUNCTION update_project_documents_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS project_documents_updated_at ON project_documents;
CREATE TRIGGER project_documents_updated_at
  BEFORE UPDATE ON project_documents
  FOR EACH ROW
  EXECUTE FUNCTION update_project_documents_updated_at();

-- Comment on table and columns
COMMENT ON TABLE project_documents IS 'Project documents including BSS, MSS, contracts, and other related files';
COMMENT ON COLUMN project_documents.document_type IS 'Type: bss (Build Service Schedule), mss (Maintenance Service Schedule), contract, amendment, wayleave, permit, other';
COMMENT ON COLUMN project_documents.client_po_id IS 'Optional link to a specific Client PO - BSS/MSS often tied to a PO';
COMMENT ON COLUMN project_documents.is_active IS 'Soft delete flag - only one active BSS/MSS per project';
COMMENT ON COLUMN client_purchase_orders.source_document_url IS 'URL to the uploaded PO PDF in VF Storage';
COMMENT ON COLUMN client_purchase_orders.vlm_extraction_data IS 'Raw JSON data extracted by VLM from the PO PDF';
COMMENT ON COLUMN client_purchase_orders.vlm_confidence_score IS 'VLM extraction confidence 0.00-1.00';

