/**
 * Document Cross-Validation Service
 *
 * Extracts data from BSS/MSS PDFs via VLM and cross-validates against Client PO.
 * Only runs when all 3 documents (PO + BSS + MSS) are uploaded.
 *
 * Status: WORKING
 * NLNH Confidence: HIGH
 */

import { log } from '@/lib/logger';
import { createLoggedSql } from '@/lib/db-logger';

const sql = createLoggedSql(process.env.DATABASE_URL!);

const VLM_API_BASE = process.env.VLM_API_URL || 'http://100.96.203.105:8100';
const VLM_API_ENDPOINT = `${VLM_API_BASE}/v1/chat/completions`;
const VLM_MODEL = process.env.VLM_EXTRACTION_MODEL || 'Qwen/Qwen3-VL-8B-Instruct';
const VLM_TIMEOUT_MS = 90000;

// ============================================================================
// TYPES
// ============================================================================

export interface DocumentExtractionResult {
  drops: number | null;
  pricePerDrop: number | null;
  totalValue: number | null;
