/**
 * Forgot Password API
 * POST /api/auth/forgot-password
 *
 * Initiates password reset flow by generating a token and sending email.
 * Always returns success to prevent email enumeration attacks.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { generateResetToken } from '@/lib/auth';
import logger from '@/lib/logger';
import { log } from '@/lib/logger';
import { resend } from '@/lib/email/resendClient';

const sql = neon(process.env.DATABASE_URL!);

// In-memory rate limiter for forgot password attempts (per IP)
const forgotPasswordAttempts = new Map<string, { count: number; resetAt: number }>();
const MAX_FORGOT_ATTEMPTS = 3;
const FORGOT_WINDOW_MS = 15 * 60 * 1000; // 15 minutes

function isRateLimited(ip: string): boolean {
  const now = Date.now();
  const entry = forgotPasswordAttempts.get(ip);
  if (!entry || now > entry.resetAt) {
    forgotPasswordAttempts.set(ip, { count: 1, resetAt: now + FORGOT_WINDOW_MS });
    return false;
  }
  entry.count++;
  return entry.count > MAX_FORGOT_ATTEMPTS;
}

// Clean up stale entries every 30 minutes
setInterval(() => {
  const now = Date.now();
  for (const [ip, entry] of forgotPasswordAttempts) {
    if (now > entry.resetAt) forgotPasswordAttempts.delete(ip);
  }
}, 30 * 60 * 1000).unref();

const FROM_ADDRESS = 'FibreFlow <notifications@fibreflow.app>';
const APP_URL = process.env.NEXT_PUBLIC_APP_URL || 'https://app.fibreflow.app';

interface ForgotPasswordRequest {
  email: string;
}

/**
 * Send password reset email via Resend
 */
async function sendResetEmail(
  email: string,
  resetLink: string,
  firstName: string
): Promise<boolean> {
  try {
    const result = await resend.emails.send({
      from: FROM_ADDRESS,
      to: email,
      subject: 'Reset Your FibreFlow Password',
      html: `
        <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
          <h2 style="color: #1a1a2e;">Reset Your Password</h2>
          <p>Hi ${firstName || 'there'},</p>
          <p>We received a request to reset your FibreFlow password. Click the button below to create a new password:</p>
          <p style="margin: 30px 0;">
            <a href="${resetLink}"
               style="background-color: #3b82f6; color: white; padding: 12px 24px;
                      text-decoration: none; border-radius: 6px; display: inline-block;">
              Reset Password
            </a>
          </p>
          <p style="color: #666; font-size: 14px;">
            This link will expire in 1 hour. If you didn't request this, you can safely ignore this email.
          </p>
          <hr style="border: none; border-top: 1px solid #eee; margin: 30px 0;">
          <p style="color: #999; font-size: 12px;">
            FibreFlow - Fiber Network Management
          </p>
        </div>
      `,
      text: `Reset Your Password\n\nHi ${firstName || 'there'},\n\nWe received a request to reset your FibreFlow password.\n\nClick here to reset: ${resetLink}\n\nThis link will expire in 1 hour.\n\nIf you didn't request this, you can safely ignore this email.`,
    });

    const resendId = result.data?.id || null;
    logger.info({ email, resendId }, 'Password reset email sent via Resend');
    return true;
  } catch (error) {
    logger.error({ error, email }, 'Failed to send password reset email via Resend');
    return false;
  }
}

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  if (req.method !== 'POST') {
    return res.status(405).json({
      success: false,
      error: { code: 'METHOD_NOT_ALLOWED', message: 'Only POST allowed' },
    });
  }

  // Rate limit by IP
  const clientIp = (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() || req.socket.remoteAddress || 'unknown';
  if (isRateLimited(clientIp)) {
    log.warn('forgot-password', { ip: clientIp, message: 'Rate limited' });
    return res.status(429).json({
      success: false,
      error: { code: 'RATE_LIMITED', message: 'Too many password reset attempts. Please try again later.' },
    });
  }

  try {
    const { email } = req.body as ForgotPasswordRequest;

    if (!email) {
      return res.status(400).json({
        success: false,
        error: { code: 'INVALID_INPUT', message: 'Email is required' },
      });
    }

    const normalizedEmail = email.toLowerCase().trim();

    // Always return success to prevent email enumeration
    // But only actually send email if user exists
    const successResponse = {
      success: true,
      message: 'If an account exists with this email, you will receive a password reset link.',
    };

    // Find user by email
    const users = await sql`
      SELECT id, first_name, email
      FROM users
      WHERE email = ${normalizedEmail}
      AND is_active = true
    `;

    if (users.length === 0) {
      // User doesn't exist, but don't reveal this
      logger.info({ email: normalizedEmail }, 'Password reset requested for non-existent email');
      return res.status(200).json(successResponse);
    }

    const user = users[0] as { id: string; first_name: string; email: string };

    // Generate reset token
    const { token, hashedToken, expiresAt } = generateResetToken();

    // Store hashed token in database
    await sql`
      UPDATE users
      SET
        reset_token = ${hashedToken},
        reset_token_expires = ${expiresAt.toISOString()}
      WHERE id = ${user.id}
    `;

    // Build reset link
    const resetLink = `${APP_URL}/auth/reset-password?token=${token}&email=${encodeURIComponent(normalizedEmail)}`;

    // Send email
    const emailSent = await sendResetEmail(normalizedEmail, resetLink, user.first_name || '');
    if (!emailSent) {
      logger.error({ email: normalizedEmail }, 'Password reset email failed to send — user will not receive link');
    }

    return res.status(200).json(successResponse);
  } catch (error) {
    logger.error({ error }, 'Forgot password error');
    return res.status(500).json({
      success: false,
      error: { code: 'SERVER_ERROR', message: 'An error occurred' },
    });
  }
}

/**
 * POST /api/communications/email-send
 * Compose and send an email via Resend, record in email_outbox
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth/middleware';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);
const FROM_ADDRESS = 'FibreFlow <notifications@fibreflow.app>';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method!, ['POST']);
  }

  const authReq = req as AuthenticatedNextApiRequest;
  const { to, toName, subject, bodyHtml, bodyText } = req.body;

  if (!to || !subject || !bodyHtml) {
    return apiResponse.badRequest(res, 'to, subject, and bodyHtml are required');
  }

  // Basic email validation
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to)) {
    return apiResponse.badRequest(res, 'Invalid email address');
  }

  let outboxId: string | null = null;

  try {
    // Insert into outbox as 'sending'
    const insertResult = await sql`
      INSERT INTO email_outbox (
        sender_id, recipient_email, recipient_name, subject,
        body_html, body_text, source_module, status
      ) VALUES (
        ${authReq.user.id}::uuid, ${to}, ${toName || null}, ${subject},
        ${bodyHtml}, ${bodyText || null}, 'manual', 'sending'
      )
      RETURNING id
    `;
    outboxId = insertResult[0].id;

    // Send via Resend
    const { resend } = await import('@/lib/email/resendClient');
    const sendResult = await resend.emails.send({
      from: FROM_ADDRESS,
      to,
      subject,
      html: bodyHtml,
      ...(bodyText ? { text: bodyText } : {}),
    });

    const resendId = sendResult.data?.id || null;

    // Update outbox with success
    await sql`
      UPDATE email_outbox
      SET status = 'sent', resend_id = ${resendId}, sent_at = NOW()
      WHERE id = ${outboxId}::uuid
    `;

    log.info('Email sent via compose', {
      to, subject, outboxId, resendId,
    }, 'EmailCompose');

    return apiResponse.success(res, { id: outboxId, status: 'sent', resendId });
  } catch (error) {
    const errorMsg = error instanceof Error ? error.message : String(error);
    log.error('Email compose send failed', { to, subject, error: errorMsg }, 'EmailCompose');

    // Update outbox with failure if we have an ID
    if (outboxId) {
      await sql`
        UPDATE email_outbox
        SET status = 'failed', error_message = ${errorMsg}
        WHERE id = ${outboxId}::uuid
      `.catch(() => {});
    }

    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

