/**
 * PATCH /api/construction-qa/photo-step
 * Update a photo's checklist_step and step_label on construction_qa_photos.
 * Used by drag-and-drop reassignment in the Photo Review phase.
 *
 * Records VLM corrections when a user reassigns a VLM-processed photo
 * to a different step (HITL feedback loop for learning).
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth, withPermission } from '@/lib/auth/middleware';
import { recordVlmCorrection } from '@/services/vlmLearningService';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'PATCH') {
    return apiResponse.methodNotAllowed(res, req.method || 'unknown', ['PATCH']);
  }

  const { photoId, step, stepLabel } = req.body;

  if (!photoId || typeof photoId !== 'string') {
    return apiResponse.badRequest(res, 'photoId is required');
  }

  // step must be a positive integer or null (null = unassigned)
  if (step !== null && (typeof step !== 'number' || step < 0 || !Number.isInteger(step))) {
    return apiResponse.badRequest(res, 'step must be a positive integer or null');
  }

  try {
    // Fetch current state before update (for VLM correction tracking)
    const [currentPhoto] = await sql`
      SELECT checklist_step, step_label, vlm_confidence, review_id
      FROM construction_qa_photos
      WHERE id = ${photoId}::uuid
    `;

    if (!currentPhoto) {
      return apiResponse.notFound(res, 'Photo', photoId);
    }

    const oldStep = currentPhoto.checklist_step;
    const oldLabel = currentPhoto.step_label;
    const newStep = step;
    const newLabel = stepLabel ?? null;

    const result = await sql`
      UPDATE construction_qa_photos
      SET checklist_step = ${newStep},
          step_label = ${newLabel},
          updated_at = NOW()
      WHERE id = ${photoId}::uuid
      RETURNING id
    `;

    if (result.length === 0) {
      return apiResponse.notFound(res, 'Photo', photoId);
    }

    // Record VLM correction if step actually changed and VLM had processed the photo
    if (oldStep !== newStep && currentPhoto.vlm_confidence != null) {
      // Fetch discipline from the review for context
      const [review] = await sql`
        SELECT discipline FROM construction_qa_reviews
        WHERE id = ${currentPhoto.review_id}::uuid
      `;

      recordVlmCorrection({
        module: 'construction_qa',
        analysisType: 'construction_photo_qa',
        sourceId: photoId,
        sourceTable: 'construction_qa_photos',
        vlmExtractedValue: `${String(oldStep ?? 'unassigned')}${oldLabel ? ` - ${oldLabel}` : ''}`,
        vlmConfidence: Number(currentPhoto.vlm_confidence),
        correctedValue: `${String(newStep ?? 'unassigned')}${newLabel ? ` - ${newLabel}` : ''}`,
        correctionReason: 'wrong_field',
        context: {
          discipline: review?.discipline || null,
          oldStep,
          newStep,
          oldLabel,
          newLabel,
        },
      }).catch((err) => {
        log.error('VLM correction recording failed (non-blocking)', {
          module: 'construction-qa',
          photoId,
          error: (err as Error).message,
        });
      });
    }

    return apiResponse.success(res, { photoId, step: newStep, stepLabel: newLabel });
  } catch (error) {
    log.error('Photo step update error', { module: 'construction-qa', error: (error as Error).message });
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(withPermission('construction-qa.qa-centre')(handler));

/**
 * POST /api/construction-qa/final-decision
 *
 * Phase 4: Record final QA decision (PASS / FAIL / REWORK_NEEDED)
 * Optionally triggers WhatsApp feedback in the same request.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth, withPermission, type AuthenticatedNextApiRequest } from '@/lib/auth/middleware';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'unknown', ['POST']);
  }

  // Authenticated user is the decision-maker — not caller-supplied
  const authReq = req as AuthenticatedNextApiRequest;
  const decidedBy = authReq.user?.name || authReq.user?.email || 'unknown';

  try {
    const {
      reviewId,
      decision,
      reasonCodes = [],
      notes = '',
      sendFeedback = false,
    } = req.body;

    if (!reviewId || !decision) {
      return apiResponse.badRequest(res, 'reviewId and decision are required');
    }

    const validDecisions = ['PASS', 'FAIL', 'REWORK_NEEDED'];
    if (!validDecisions.includes(decision)) {
      return apiResponse.badRequest(res, `decision must be one of: ${validDecisions.join(', ')}`);
    }

    // Map decision to workflow status
    const statusMap: Record<string, string> = {
      PASS: 'approved',
      FAIL: 'rejected',
      REWORK_NEEDED: 'rework_needed',
    };
    const newStatus = statusMap[decision];

    // Require notes for FAIL and REWORK_NEEDED
    if ((decision === 'FAIL' || decision === 'REWORK_NEEDED') && !notes.trim()) {
      return apiResponse.badRequest(res, 'Notes are required for FAIL and REWORK_NEEDED decisions');
    }

    // Build the snapshot for rework tracking
    const currentReview = await sql`
      SELECT workflow_status, photo_count, vlm_confidence, qa_decision, qa_notes
      FROM construction_qa_reviews WHERE id = ${reviewId}::uuid LIMIT 1
    `;

    if (currentReview.length === 0) {
      return apiResponse.notFound(res, 'Review', reviewId);
    }

    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    const row = currentReview[0]!;
    const snapshot = {
      captured_at: new Date().toISOString(),
      workflow_status: row.workflow_status,
      photo_count: Number(row.photo_count),
      vlm_confidence: row.vlm_confidence ? Number(row.vlm_confidence) : null,
      qa_decision: row.qa_decision,
      qa_notes: row.qa_notes,
      reason_codes: reasonCodes,
    };

    // Update the review
    await sql`
      UPDATE construction_qa_reviews
      SET workflow_status = ${newStatus},
          qa_decision = ${decision},
          qa_decision_at = NOW(),
          qa_decision_by = ${decidedBy},
          qa_reason_code = ${reasonCodes.length > 0 ? reasonCodes[0] : null},
          qa_notes = ${notes || null},
          rework_count = CASE WHEN ${decision} = 'REWORK_NEEDED' THEN rework_count + 1 ELSE rework_count END,
          resubmission_snapshots = COALESCE(resubmission_snapshots, '[]'::jsonb) || ${JSON.stringify(snapshot)}::jsonb,
          updated_at = NOW()
      WHERE id = ${reviewId}::uuid
    `;

    // Log activity
    await sql`
      INSERT INTO construction_qa_activity (review_id, event_type, actor, payload)
      VALUES (
        ${reviewId}::uuid,
        'decision_made',
        ${decidedBy},
        ${JSON.stringify({ decision, reason_codes: reasonCodes, notes })}::jsonb
      )
    `;

    // Send WhatsApp feedback if requested
    let waSent = false;
    let waError: string | undefined;

    if (sendFeedback && (decision === 'FAIL' || decision === 'REWORK_NEEDED')) {
      try {
        const reviewDetails = await sql`
          SELECT r.feature_id, r.discipline, r.wa_group_jid, r.wa_technician_phone,
                 p.project_name
          FROM construction_qa_reviews r
          JOIN projects p ON p.id = r.project_id
          WHERE r.id = ${reviewId}::uuid
        `;

        if (reviewDetails.length > 0) {
          // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
          const detail = reviewDetails[0]!;
          const message = buildFeedbackMessage(
            detail.project_name as string,
            detail.feature_id as string,
            detail.discipline as string,
            decision,
            reasonCodes,
            notes,
          );

          await sql`
            UPDATE construction_qa_reviews
            SET wa_feedback_sent_at = NOW(),
                wa_feedback_message = ${message}
            WHERE id = ${reviewId}::uuid
          `;

          waSent = true;
          log.info('WhatsApp feedback recorded', { module: 'construction-qa', reviewId });
        }
      } catch (waErr) {
        waError = (waErr as Error).message;
        log.error('WhatsApp feedback failed', { module: 'construction-qa', error: waError });
      }
    }

    return apiResponse.success(res, {
      reviewId,
      decision,
      waSent,
      waError,
    });
  } catch (error) {
    log.error('Final decision error', { module: 'construction-qa', error: (error as Error).message });
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(withPermission('construction-qa.qa-centre')(handler));

function buildFeedbackMessage(
  projectName: string,
  featureId: string,
  discipline: string,
  decision: string,
  reasonCodes: string[],
  notes: string,
): string {
  const emoji = decision === 'FAIL' ? '\u274c' : '\u26a0\ufe0f';
  const action = decision === 'FAIL' ? 'REJECTED' : 'REWORK NEEDED';

  let msg = `${emoji} *Construction QA — ${action}*\n\n`;
  msg += `*Project:* ${projectName}\n`;
  msg += `*Feature:* ${featureId}\n`;
  msg += `*Discipline:* ${discipline}\n\n`;

  if (reasonCodes.length > 0) {
    msg += `*Issues:*\n`;
    reasonCodes.forEach(code => {
      msg += `\u2022 ${code.replace(/_/g, ' ').toLowerCase()}\n`;
    });
    msg += '\n';
  }

  if (notes) {
    msg += `*Notes:* ${notes}\n\n`;
  }

  msg += `Please address the issues and resubmit photos.`;
  return msg;
}

/**
 * Construction QA Review API
 *
 * GET  /api/construction-qa/review?id={reviewId}
 *   - Returns full review detail with photos and activity
 *
 * POST /api/construction-qa/review
 *   - Updates review checklist steps and extracted data (Phase 2/3)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth, withPermission } from '@/lib/auth/middleware';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') return handleGet(req, res);
  if (req.method === 'POST') return handlePost(req, res);
  return apiResponse.methodNotAllowed(res, req.method || 'unknown', ['GET', 'POST']);
}

async function handleGet(req: NextApiRequest, res: NextApiResponse) {
  const { id } = req.query;

  if (!id || typeof id !== 'string') {
    return apiResponse.badRequest(res, 'Review id is required');
  }

  try {
    // Fetch review with project name
    const reviews = await sql`
      SELECT
        r.*,
        p.project_name
      FROM construction_qa_reviews r
      JOIN projects p ON p.id = r.project_id
      WHERE r.id = ${id}::uuid
      LIMIT 1
    `;

    if (reviews.length === 0) {
      return apiResponse.notFound(res, 'Review', id);
    }

    const review = reviews[0];

    // Fetch photos
    const photos = await sql`
      SELECT *
      FROM construction_qa_photos
      WHERE review_id = ${id}::uuid
      ORDER BY checklist_step ASC NULLS LAST, created_at ASC
    `;

    // Fetch recent activity (last 50 entries)
    const activity = await sql`
      SELECT *
      FROM construction_qa_activity
      WHERE review_id = ${id}::uuid
      ORDER BY created_at DESC
      LIMIT 50
    `;

    return apiResponse.success(res, {
      review,
      photos,
      activity,
    });
  } catch (error) {
    log.error('Review GET error', { module: 'construction-qa', error: (error as Error).message });

    if ((error as Error).message?.includes('does not exist')) {
      return apiResponse.success(res, { review: null, photos: [], activity: [] });
    }

    return apiResponse.internalError(res, error);
  }
}

async function handlePost(req: NextApiRequest, res: NextApiResponse) {
  try {
    const { reviewId, stepUpdates, extractedDataUpdates, notes, reviewedBy, featureIdUpdate } = req.body;

    if (!reviewId) {
      return apiResponse.badRequest(res, 'reviewId is required');
    }

    // Build SET clauses from step updates
    const setClauses: string[] = ['updated_at = NOW()'];
    const params: (string | number | boolean)[] = [reviewId];
    let paramIdx = 2;

    // Valid step column names (whitelist to prevent SQL injection)
    const validStepColumns = new Set([
      // Civil — Pole Install Capture Checklist (8 steps)
      'civil_step_01_before_photo', 'civil_step_02_during_photo', 'civil_step_03_depth_photo',
      'civil_step_04_end_plates', 'civil_step_05_compaction', 'civil_step_06_level_check',
      'civil_step_07_after_photo', 'civil_step_08_signature',
      // Optical — Cable Stringing (6 steps, unchanged)
      'optical_step_01_cable_route', 'optical_step_02_attachment', 'optical_step_03_slack_coil',
      'optical_step_04_cable_label', 'optical_step_05_no_backfeed', 'optical_step_06_sag_ok',
      // Splicing — Distribution Dome (8 steps)
      'splicing_step_01_dome_on_pole', 'splicing_step_02_dome_label',
      'splicing_step_03_open_dome', 'splicing_step_04_splice_protectors',
      'splicing_step_05_slack_management', 'splicing_step_06_strength_members',
      'splicing_step_07_seals_dustcaps', 'splicing_step_08_pole_id',
      // Splicing — Main Joint (6 steps, numbered 11-16)
      'splicing_step_11_cable_entries', 'splicing_step_12_strength_members',
      'splicing_step_13_tube_routing', 'splicing_step_14_tray_entries',
      'splicing_step_15_coiling_protectors', 'splicing_step_16_readable_labels',
    ]);

    const updatedFields: string[] = [];

    if (stepUpdates && typeof stepUpdates === 'object') {
      for (const [col, val] of Object.entries(stepUpdates)) {
        if (validStepColumns.has(col)) {
          setClauses.push(`${col} = $${paramIdx}`);
          params.push(Boolean(val));
          paramIdx++;
          updatedFields.push(col);
        }
      }
    }

    // Valid extracted data columns
    const validExtractedColumns = new Set([
      'extracted_pole_number', 'extracted_pole_height', 'extracted_cable_type',
      'extracted_joint_type', 'extracted_splice_count',
    ]);

    if (extractedDataUpdates && typeof extractedDataUpdates === 'object') {
      for (const [col, val] of Object.entries(extractedDataUpdates)) {
        if (validExtractedColumns.has(col)) {
          setClauses.push(`${col} = $${paramIdx}`);
          params.push(val as string | number);
          paramIdx++;
          updatedFields.push(col);
        }
      }
    }

    if (notes) {
      setClauses.push(`qa_notes = $${paramIdx}`);
      params.push(notes);
      paramIdx++;
      updatedFields.push('qa_notes');
    }

    // Feature ID rename/reassign
    if (featureIdUpdate && typeof featureIdUpdate === 'string') {
      setClauses.push(`feature_id = $${paramIdx}`);
      params.push(featureIdUpdate.trim());
      paramIdx++;
      updatedFields.push('feature_id');

      // If renaming to a valid pole pattern, try to backfill zone/PON and clear unidentified
      const validPolePattern = /^[A-Z]{3}\.P\./;
      if (validPolePattern.test(featureIdUpdate.trim())) {
        setClauses.push(`workflow_status = CASE WHEN workflow_status = 'unidentified' THEN 'pending' ELSE workflow_status END`);
      }
    }

    // Move to in_review if currently pending
    setClauses.push(`workflow_status = CASE WHEN workflow_status = 'pending' THEN 'in_review' ELSE workflow_status END`);

    // Execute update
    const updateQuery = `
      UPDATE construction_qa_reviews
      SET ${setClauses.join(', ')}
      WHERE id = $1::uuid
      RETURNING id
    `;

    const result = await sql.query(updateQuery, params);

    if (result.length === 0) {
      return apiResponse.notFound(res, 'Review', reviewId);
    }

    // Log activity
    if (updatedFields.length > 0) {
      const eventType = updatedFields.includes('feature_id') ? 'comment_added' : 'step_checked';
      const payload = updatedFields.includes('feature_id')
        ? { action: 'feature_id_renamed', new_feature_id: featureIdUpdate, updated_fields: updatedFields }
        : { updated_fields: updatedFields };

      await sql`
        INSERT INTO construction_qa_activity (review_id, event_type, actor, payload)
        VALUES (
          ${reviewId}::uuid,
          ${eventType},
          ${reviewedBy || 'unknown'},
          ${JSON.stringify(payload)}::jsonb
        )
      `;
    }

    return apiResponse.success(res, {
      reviewId,
      updatedFields,
    });
  } catch (error) {
    log.error('Review POST error', { module: 'construction-qa', error: (error as Error).message });
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(withPermission('construction-qa.qa-centre')(handler));

