/**
 * Pole Install Classifier Service
 *
 * Classifies pole installation photos using the VLM (Qwen3-VL-8B) and extracts
 * pole numbers from text messages. Designed for the field-ops WhatsApp photo
 * pipeline where technicians send sequential installation step photos.
 *
 * @module field-ops/services/poleInstallClassifier
 */

import { createLogger } from '@/lib/logger';

const logger = createLogger('poleInstallClassifier');
const VLM_URL = process.env.VLM_API_URL || process.env.VLM_SERVICE_URL || 'http://100.96.203.105:8100';
const VLM_MODEL = process.env.VLM_MODEL || 'Qwen/Qwen3-VL-8B-Instruct';
const VLM_TIMEOUT_MS = 30_000;

// ============================================================================
// Types
// ============================================================================

export type PoleInstallStep =
  | 'BEFORE'
  | 'DURING'
  | 'DEPTH'
  | 'ENDPLATE'
  | 'COMPACTION'
  | 'LEVEL'
  | 'STUMPING'
  | 'HOUSEKEEPING'
  | 'SIGNATURE'
  | 'UNKNOWN';

export interface PoleClassification {
  step: PoleInstallStep;
  pole_number: string | null;
  confidence: number;
  quality_ok: boolean;
  issues: string[];
  feedback: string;
}

/** Raw shape returned from VLM JSON response */
interface RawVlmResponse {
  step?: string;
  pole_number?: string | null;
  confidence?: number;
  quality_ok?: boolean;
  issues?: string[];
  feedback?: string;
}

// ============================================================================
// Constants
// ============================================================================

const VALID_STEPS: ReadonlySet<string> = new Set<PoleInstallStep>([
  'BEFORE',
  'DURING',
  'DEPTH',
  'ENDPLATE',
  'COMPACTION',
  'LEVEL',
  'STUMPING',
  'HOUSEKEEPING',
  'SIGNATURE',
  'UNKNOWN',
]);

const FALLBACK_CLASSIFICATION: PoleClassification = {
  step: 'UNKNOWN',
  pole_number: null,
  confidence: 0,
  quality_ok: false,
  issues: ['VLM unavailable — manual classification required'],
  feedback: 'AI classification unavailable',
};

// ============================================================================
// Prompt Builder
// ============================================================================

function buildClassificationPrompt(poleHint?: string): string {
  const poleLabel = poleHint || 'UNKNOWN';
  return `You are a construction QA inspector for fiber pole installations.
This photo was sent by a field team installing pole ${poleLabel}.

Classify this photo into EXACTLY ONE of these installation steps:
- BEFORE: Marked ground (circle/square/X) showing where hole will be dug. Open ground, paint marks.
- DURING: Staff digging hole or hole being prepared. Shovel/pick visible.
- DEPTH: Measuring tape or ruler placed IN the hole showing depth measurement.
- ENDPLATE: End plates visible on the bottom of the pole before planting.
- COMPACTION: Sand+cement backfill mix around pole base, being compacted. NOT a loose heap.
- LEVEL: Spirit level (bubble level) held against an upright pole.
- STUMPING: Pole being planted/erected into hole, or freshly planted pole from various angles. Pole in ground.
- HOUSEKEEPING: Clean site around a completed pole installation. Cleanup in progress or done.
- SIGNATURE: Sign-off sheet, contractor signature, or completion document on paper.

Also extract any visible pole number (chalk/spray paint on pole, written labels, stickers).

Respond with ONLY this JSON (no markdown, no explanation):
{"step":"STEP_NAME","pole_number":"extracted or null","confidence":0.85,"quality_ok":true,"issues":[],"feedback":"one sentence"}`;
}

// ============================================================================
// Response Parser
// ============================================================================

function parseClassificationResponse(text: string): PoleClassification {
  try {
    // Strip markdown code fences if present
    const stripped = text.replace(/^```(?:json)?\n?/i, '').replace(/\n?```$/i, '').trim();
    const jsonMatch = stripped.match(/\{[\s\S]*\}/);

    if (jsonMatch) {
      const raw = JSON.parse(jsonMatch[0]) as RawVlmResponse;
      const rawStep = typeof raw.step === 'string' ? raw.step.toUpperCase() : 'UNKNOWN';
      const step: PoleInstallStep = VALID_STEPS.has(rawStep)
        ? (rawStep as PoleInstallStep)
        : 'UNKNOWN';

      return {
        step,
        pole_number: raw.pole_number ? String(raw.pole_number) : null,
        confidence: Math.min(1, Math.max(0, Number(raw.confidence ?? 0))),
        quality_ok: Boolean(raw.quality_ok ?? false),
        issues: Array.isArray(raw.issues) ? raw.issues.map(String) : [],
        feedback: typeof raw.feedback === 'string' ? raw.feedback : '',
      };
    }
  } catch (parseError) {
    logger.warn('Failed to parse VLM JSON response', {
      error: parseError instanceof Error ? parseError.message : 'Unknown',
      responsePreview: text.slice(0, 200),
    });
  }

  // Fallback: extract step keyword from free-form text
  const upper = text.toUpperCase();
  const detectedStep = (
    ['BEFORE', 'DURING', 'DEPTH', 'ENDPLATE', 'COMPACTION', 'LEVEL', 'STUMPING', 'HOUSEKEEPING', 'SIGNATURE'] as PoleInstallStep[]
  ).find((s) => upper.includes(s));

  return {
    step: detectedStep ?? 'UNKNOWN',
    pole_number: null,
    confidence: detectedStep ? 0.3 : 0,
    quality_ok: false,
    issues: ['Could not parse structured AI response — manual review recommended'],
    feedback: text.slice(0, 300),
  };
}

// ============================================================================
// Public API
// ============================================================================

/**
 * Classify a pole installation photo using the VLM.
 *
 * @param photoBase64 - Raw base64-encoded JPEG/PNG image data (no data URI prefix)
 * @param poleHint - Optional pole number hint for the prompt (e.g. "LAW.P.A0042")
 * @returns Classification result including step, confidence, and extracted pole number
 */
export async function classifyPolePhoto(
  photoBase64: string,
  poleHint?: string
): Promise<PoleClassification> {
  const imageDataUrl = `data:image/jpeg;base64,${photoBase64}`;
  const prompt = buildClassificationPrompt(poleHint);
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), VLM_TIMEOUT_MS);

  try {
    const response = await fetch(`${VLM_URL}/v1/chat/completions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      signal: controller.signal,
      body: JSON.stringify({
        model: VLM_MODEL,
        messages: [
          {
            role: 'user',
            content: [
              { type: 'image_url', image_url: { url: imageDataUrl, detail: 'high' } },
              { type: 'text', text: prompt },
            ],
          },
        ],
        max_tokens: 512,
        temperature: 0.1,
      }),
    });

    if (!response.ok) {
      const body = await response.text();
      throw new Error(`VLM HTTP ${response.status}: ${body}`);
    }

    const data = (await response.json()) as { choices?: Array<{ message?: { content?: string } }> };
    const text = data.choices?.[0]?.message?.content ?? '';

    if (!text) {
      throw new Error('VLM returned empty content');
    }

    const result = parseClassificationResponse(text);

    logger.info('Pole photo classified', {
      step: result.step,
      confidence: result.confidence,
      poleHint,
      extractedPole: result.pole_number,
    });

    return result;
  } catch (error) {
    if (error instanceof Error && error.name === 'AbortError') {
      logger.error('VLM classification timed out', { poleHint, timeoutMs: VLM_TIMEOUT_MS });
      return {
        ...FALLBACK_CLASSIFICATION,
        issues: [`VLM request timed out after ${VLM_TIMEOUT_MS / 1000}s`],
        feedback: 'AI classification timed out — manual review required',
      };
    }

    logger.error('VLM classification failed', {
      error: error instanceof Error ? error.message : 'Unknown',
      poleHint,
    });

    return {
      ...FALLBACK_CLASSIFICATION,
      issues: [`VLM error: ${error instanceof Error ? error.message : 'Unknown'}`],
      feedback: 'AI classification failed — manual review required',
    };
  } finally {
    clearTimeout(timeoutId);
  }
}

/**
 * Extract a pole number from a WhatsApp text message using regex patterns.
 *
 * Handles formats like:
 * - "Starting pole: LAW.P.A0042"
 * - "LAW-P-A0042"
 * - "Pole A003"
 * - "Begin LAW.PA042"
 *
 * @param messageText - Raw WhatsApp message text
 * @returns Normalised pole number string, or null if not found
 */
export function extractPoleFromText(messageText: string): string | null {
  const patterns: RegExp[] = [
    // Explicit keyword prefix: "pole: LAW.P.A0042" or "starting LAW.P.A0042"
    /(?:pole|starting|begin|start)\s*:?\s*([A-Z]{2,4}\.?P\.?[A-Z]?\d{1,4})/i,
    // General pole number format: "LAW-P-A0042" or "LAW.P.A0042"
    /\b([A-Z]{2,4}[.-]P[.-][A-Z]\d{2,4})\b/i,
    // Bare short pole number: "A003"
    /\b([A-Z]\d{3})\b/,
  ];

  for (const pattern of patterns) {
    const match = messageText.match(pattern);
    if (match?.[1]) {
      return match[1].toUpperCase();
    }
  }

  return null;
}

/**
 * PATCH /api/construction-qa/photo-step
 * Update a photo's checklist_step and step_label on construction_qa_photos.
 * Used by drag-and-drop reassignment in the Photo Review phase.
 *
 * Records VLM corrections when a user reassigns a VLM-processed photo
 * to a different step (HITL feedback loop for learning).
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth, withPermission } from '@/lib/auth/middleware';
import { recordVlmCorrection } from '@/services/vlmLearningService';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'PATCH') {
    return apiResponse.methodNotAllowed(res, req.method || 'unknown', ['PATCH']);
  }

  const { photoId, step, stepLabel } = req.body;

  if (!photoId || typeof photoId !== 'string') {
    return apiResponse.badRequest(res, 'photoId is required');
  }

  // step must be a positive integer or null (null = unassigned)
  if (step !== null && (typeof step !== 'number' || step < 0 || !Number.isInteger(step))) {
    return apiResponse.badRequest(res, 'step must be a positive integer or null');
  }

  try {
    // Fetch current state before update (for VLM correction tracking)
    const [currentPhoto] = await sql`
      SELECT checklist_step, step_label, vlm_confidence, review_id
      FROM construction_qa_photos
      WHERE id = ${photoId}::uuid
    `;

    if (!currentPhoto) {
      return apiResponse.notFound(res, 'Photo', photoId);
    }

    const oldStep = currentPhoto.checklist_step;
    const oldLabel = currentPhoto.step_label;
    const newStep = step;
    const newLabel = stepLabel ?? null;

    const result = await sql`
      UPDATE construction_qa_photos
      SET checklist_step = ${newStep},
          step_label = ${newLabel},
          updated_at = NOW()
      WHERE id = ${photoId}::uuid
      RETURNING id
    `;

    if (result.length === 0) {
      return apiResponse.notFound(res, 'Photo', photoId);
    }

    // Record VLM correction if step actually changed and VLM had processed the photo
    if (oldStep !== newStep && currentPhoto.vlm_confidence != null) {
      // Fetch discipline from the review for context
      const [review] = await sql`
        SELECT discipline FROM construction_qa_reviews
        WHERE id = ${currentPhoto.review_id}::uuid
      `;

      recordVlmCorrection({
        module: 'construction_qa',
        analysisType: 'construction_photo_qa',
        sourceId: photoId,
        sourceTable: 'construction_qa_photos',
        vlmExtractedValue: `${String(oldStep ?? 'unassigned')}${oldLabel ? ` - ${oldLabel}` : ''}`,
        vlmConfidence: Number(currentPhoto.vlm_confidence),
        correctedValue: `${String(newStep ?? 'unassigned')}${newLabel ? ` - ${newLabel}` : ''}`,
        correctionReason: 'wrong_field',
        context: {
          discipline: review?.discipline || null,
          oldStep,
          newStep,
          oldLabel,
          newLabel,
        },
      }).catch((err) => {
        log.error('VLM correction recording failed (non-blocking)', {
          module: 'construction-qa',
          photoId,
          error: (err as Error).message,
        });
      });
    }

    return apiResponse.success(res, { photoId, step: newStep, stepLabel: newLabel });
  } catch (error) {
    log.error('Photo step update error', { module: 'construction-qa', error: (error as Error).message });
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(withPermission('construction-qa.qa-centre')(handler));

/**
 * VLM Construction Service
 *
 * AI-powered photo validation for construction QA using Qwen3-VL on Velocity:8100.
 * Evaluates photos per checklist step and returns structured results.
 *
 * Pattern: OpenAI-compatible chat/completions API with image_url messages.
 */

import { neon } from '@neondatabase/serverless';
import { log } from '@/lib/logger';
import { getChecklist } from '../types/construction.types';
import type { Discipline, VlmStepResult, VlmOverallResult } from '../types';
import { recordCorrectExtraction, getVlmFewShotExamples, buildVlmFewShotPrompt } from '@/services/vlmLearningService';

const sql = neon(process.env.DATABASE_URL!);
const MODULE = 'cqa-vlm';
const VLM_URL = process.env.VLM_SERVICE_URL || 'http://100.96.203.105:8100';
const VLM_MODEL = 'Qwen3-VL-8B-Instruct';
const MAX_IMAGE_DIM = 1024;

interface ValidateOptions {
  reviewId: string;
  discipline: Discipline;
  photoId?: string;
  forceRerun?: boolean;
}

interface ValidateResult {
  photosProcessed: number;
  overallConfidence: number | null;
  vlmStatus: string;
  stepResults: VlmStepResult[];
  error?: string;
}

/**
 * Run VLM validation on a review's photos.
 * Updates construction_qa_reviews and construction_qa_photos with results.
 */
export async function validateReviewPhotos(opts: ValidateOptions): Promise<ValidateResult> {
  const { reviewId, discipline, photoId, forceRerun = false } = opts;
  const result: ValidateResult = {
    photosProcessed: 0,
    overallConfidence: null,
    vlmStatus: 'processing',
    stepResults: [],
  };

  try {
    // Mark review as processing
    await sql`
      UPDATE construction_qa_reviews
      SET vlm_status = 'processing', updated_at = NOW()
      WHERE id = ${reviewId}::uuid
    `;

    // Log activity
    await sql`
      INSERT INTO construction_qa_activity (review_id, event_type, actor, payload)
      VALUES (${reviewId}::uuid, 'vlm_started', 'vlm', '{}'::jsonb)
    `;

    // Fetch photos to validate
    let photosQuery = `
      SELECT id, storage_key, source, checklist_step, filename
      FROM construction_qa_photos
      WHERE review_id = $1::uuid
    `;
    const params: (string | boolean)[] = [reviewId];

    if (photoId) {
      photosQuery += ` AND id = $2::uuid`;
      params.push(photoId);
    } else if (!forceRerun) {
      photosQuery += ` AND vlm_processed_at IS NULL`;
    }

    photosQuery += ` ORDER BY checklist_step ASC NULLS LAST`;

    const photos = await sql.query(photosQuery, params);

    if (photos.length === 0) {
      result.vlmStatus = 'completed';
      await sql`
        UPDATE construction_qa_reviews
        SET vlm_status = 'completed', updated_at = NOW()
        WHERE id = ${reviewId}::uuid
      `;
      return result;
    }

    const checklist = getChecklist(discipline);

    // Fetch few-shot correction examples for prompt enhancement (non-blocking on failure)
    let fewShotSection = '';
    try {
      const fewShotExamples = await getVlmFewShotExamples({
        module: 'construction_qa',
        analysisType: 'construction_photo_qa',
        context: { discipline },
        maxExamples: 3,
        prioritizeCanonical: true,
      });
      fewShotSection = buildVlmFewShotPrompt(fewShotExamples, 'markdown');
    } catch (fewShotErr) {
      log.warn('Few-shot retrieval failed, continuing without', {
        error: (fewShotErr as Error).message,
      }, MODULE);
    }

    // Process each photo
    for (const photo of photos) {
      try {
        const step = photo.checklist_step;
        const stepDef = step ? checklist.find(s => s.step === step) : null;

        // Build the prompt for this photo
        const prompt = buildPhotoPrompt(discipline, step, stepDef ?? null, fewShotSection);

        // Build the photo URL for VLM
        const photoUrl = buildPhotoUrl(photo.storage_key, photo.source);

        // Call VLM
        const vlmResult = await callVlm(photoUrl, prompt, step || 0, stepDef?.label || 'Uncategorized');

        // Update photo with results
        await sql`
          UPDATE construction_qa_photos
          SET vlm_valid = ${vlmResult.valid},
              vlm_confidence = ${vlmResult.confidence},
              vlm_issues = ${JSON.stringify(vlmResult.issues)}::jsonb,
              vlm_feedback = ${vlmResult.feedback},
              vlm_raw = ${JSON.stringify(vlmResult)}::jsonb,
              vlm_processed_at = NOW(),
              updated_at = NOW()
          WHERE id = ${photo.id}::uuid
        `;

        result.stepResults.push(vlmResult);
        result.photosProcessed++;

        // Record VLM learning metric (fire-and-forget)
        if (vlmResult.confidence >= 0.7) {
          recordCorrectExtraction('construction_qa', 'construction_photo_qa', vlmResult.confidence)
            .catch(() => {});
        }
      } catch (photoErr) {
        log.error('Photo VLM failed', { photoId: photo.id, error: (photoErr as Error).message }, MODULE);
      }
    }

    // Calculate overall confidence
    if (result.stepResults.length > 0) {
      const totalConf = result.stepResults.reduce((sum, r) => sum + r.confidence, 0);
      result.overallConfidence = Number((totalConf / result.stepResults.length).toFixed(3));
    }

    // Build overall result
    const overallResult: VlmOverallResult = {
      overall_valid: result.stepResults.every(r => r.valid),
      overall_confidence: result.overallConfidence || 0,
      steps: Object.fromEntries(result.stepResults.map(r => [String(r.step), r])),
      cross_step_issues: [],
      processed_at: new Date().toISOString(),
      model_version: VLM_MODEL,
    };

    // Build step scores
    const stepScores: Record<string, number> = {};
    for (const sr of result.stepResults) {
      stepScores[`step_${String(sr.step).padStart(2, '0')}`] = sr.confidence;
    }

    // Update review with aggregate results
    result.vlmStatus = 'completed';
    await sql`
      UPDATE construction_qa_reviews
      SET vlm_status = 'completed',
          vlm_confidence = ${result.overallConfidence},
          vlm_step_scores = ${JSON.stringify(stepScores)}::jsonb,
          vlm_issues = ${JSON.stringify(overallResult.cross_step_issues)}::jsonb,
          vlm_raw_response = ${JSON.stringify(overallResult)}::jsonb,
          vlm_processed_at = NOW(),
          vlm_model_version = ${VLM_MODEL},
          updated_at = NOW()
      WHERE id = ${reviewId}::uuid
    `;

    // Log completion
    await sql`
      INSERT INTO construction_qa_activity (review_id, event_type, actor, payload)
      VALUES (${reviewId}::uuid, 'vlm_completed', 'vlm',
        ${JSON.stringify({ photos_processed: result.photosProcessed, overall_confidence: result.overallConfidence })}::jsonb)
    `;

    return result;
  } catch (err) {
    result.vlmStatus = 'failed';
    result.error = (err as Error).message;

    // Mark as failed
    await sql`
      UPDATE construction_qa_reviews
      SET vlm_status = 'failed',
          vlm_retry_count = vlm_retry_count + 1,
          updated_at = NOW()
      WHERE id = ${reviewId}::uuid
    `.catch((e) => log.warn('DB operation failed (non-critical)', { error: e instanceof Error ? e.message : 'unknown' }, MODULE));

    await sql`
      INSERT INTO construction_qa_activity (review_id, event_type, actor, payload)
      VALUES (${reviewId}::uuid, 'vlm_failed', 'vlm',
        ${JSON.stringify({ error: result.error })}::jsonb)
    `.catch((e) => log.warn('DB operation failed (non-critical)', { error: e instanceof Error ? e.message : 'unknown' }, MODULE));

    log.error('VLM validation failed', { reviewId, error: result.error }, MODULE);
    return result;
  }
}

/**
 * Call the VLM API with a photo and prompt.
 */
async function callVlm(
  imageUrl: string,
  prompt: string,
  step: number,
  stepLabel: string,
): Promise<VlmStepResult> {
  try {
    const response = await fetch(`${VLM_URL}/v1/chat/completions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: VLM_MODEL,
        messages: [
          {
            role: 'user',
            content: [
              { type: 'image_url', image_url: { url: imageUrl, detail: 'high' } },
              { type: 'text', text: prompt },
            ],
          },
        ],
        max_tokens: 1024,
        temperature: 0.1,
      }),
    });

    if (!response.ok) {
      throw new Error(`VLM HTTP ${response.status}: ${await response.text()}`);
    }

    const data = await response.json();
    const text = data.choices?.[0]?.message?.content || '';

    // Parse structured JSON from VLM response
    return parseVlmResponse(text, step, stepLabel);
  } catch (err) {
    log.error('VLM call failed', { error: (err as Error).message }, MODULE);

    // Return a failure result
    return {
      valid: false,
      confidence: 0,
      step,
      step_label: stepLabel,
      issues: [`VLM error: ${(err as Error).message}`],
      feedback: 'AI validation unavailable — manual review required',
      extracted_data: {},
    };
  }
}

/**
 * Parse VLM text response into structured result.
 */
function parseVlmResponse(text: string, step: number, stepLabel: string): VlmStepResult {
  try {
    // Try to find JSON in the response
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      return {
        valid: Boolean(parsed.valid ?? parsed.pass ?? false),
        confidence: Number(parsed.confidence ?? parsed.score ?? 0) / (parsed.score != null && parsed.score > 1 ? 10 : 1),
        step,
        step_label: stepLabel,
        issues: Array.isArray(parsed.issues) ? parsed.issues : parsed.issue ? [parsed.issue] : [],
        feedback: parsed.feedback || parsed.comment || '',
        extracted_data: parsed.extracted_data || parsed.data || {},
      };
    }
  } catch {
    // JSON parse failed — fall through to text analysis
  }

  // Fallback: analyze text for pass/fail indicators
  const lower = text.toLowerCase();
  const valid = lower.includes('pass') || lower.includes('acceptable') || lower.includes('meets');
  const confidence = valid ? 0.7 : 0.3;

  return {
    valid,
    confidence,
    step,
    step_label: stepLabel,
    issues: valid ? [] : ['See VLM feedback for details'],
    feedback: text.slice(0, 500),
    extracted_data: {},
  };
}

/**
 * Build discipline-specific VLM prompt for a checklist step.
 */
function buildPhotoPrompt(
  discipline: Discipline,
  step: number | null,
  stepDef: { label: string; vlmCheck: string; notes?: string } | null,
  fewShotSection = '',
): string {
  const base = `You are a construction quality assurance AI inspector for fiber network installations.
Discipline: ${discipline}
${step ? `Checklist Step ${step}: ${stepDef?.label || 'Unknown'}` : 'General photo evaluation'}

${stepDef?.vlmCheck ? `Check: ${stepDef.vlmCheck}` : ''}
${stepDef?.notes ? `Notes: ${stepDef.notes}` : ''}
${fewShotSection ? `\n${fewShotSection}\n` : ''}
Evaluate this photo and respond with ONLY a JSON object:
{
  "valid": true/false,
  "confidence": 0.0-1.0,
  "issues": ["list of specific issues found"],
  "feedback": "one sentence of actionable feedback for the field technician",
  "extracted_data": { any relevant data extracted from the photo }
}

Be strict but fair. A photo must clearly show the required element to pass.`;

  return base;
}

/**
 * Build a URL for the VLM to access the photo.
 */
function buildPhotoUrl(storageKey: string, source: string): string {
  // VLM runs on Velocity, so we use the local API to proxy the photo
  const baseUrl = process.env.NEXT_PUBLIC_BASE_URL || 'http://localhost:3004';
  return `${baseUrl}/api/construction-qa/photo-proxy?key=${encodeURIComponent(storageKey)}&source=${source}`;
}

/**
