// sendDRAcknowledgment sends immediate acknowledgment reply to the user
func sendDRAcknowledgment(client *whatsmeow.Client, chatJID string, dropNumber string, project string, messageID string, senderJID string) {
	// Dedup at DR level - only send one ACK per DR per 5 minutes
	ackDedupKey := fmt.Sprintf("ack:%s:%s", chatJID, dropNumber)
	processedMsgsMu.Lock()
	if lastSent, exists := processedMsgs[ackDedupKey]; exists && time.Since(lastSent) < 5*time.Minute {
		processedMsgsMu.Unlock()
		fmt.Printf("⏭️  DEDUP: Skipping duplicate DR ACK for %s (sent %v ago)\n", dropNumber, time.Since(lastSent).Round(time.Second))
		return
	}
	processedMsgs[ackDedupKey] = time.Now()
	processedMsgsMu.Unlock()

	go func() {
		// Retry logic: 3 attempts with exponential backoff (2s, 4s, 8s)
		maxRetries := 3
		var ackResp DrAcknowledgmentResponse
		var lastErr string

		payload := fmt.Sprintf(`{"secret":"%s","dropNumber":"%s","project":"%s"}`, bridgeSecret, dropNumber, project)

		for attempt := 1; attempt <= maxRetries; attempt++ {
			resp, err := http.Post(FIBREFLOW_ACK_API_URL, "application/json", strings.NewReader(payload))
			if err != nil {
				lastErr = fmt.Sprintf("request failed: %v", err)
				if attempt < maxRetries {
					waitTime := time.Duration(math.Pow(2, float64(attempt))) * time.Second
					fmt.Printf("\033[33m[ACK RETRY] Attempt %d/%d failed for %s (%s), retrying in %v...\033[0m\n",
						attempt, maxRetries, dropNumber, lastErr, waitTime)
					time.Sleep(waitTime)
					continue
				}
				fmt.Printf("\033[31m[ACK FAILED] All %d attempts failed for %s: %s\033[0m\n", maxRetries, dropNumber, lastErr)
				return
			}

			body, _ := io.ReadAll(resp.Body)
			resp.Body.Close()

			if resp.StatusCode != 200 {
				lastErr = fmt.Sprintf("API returned %d: %s", resp.StatusCode, string(body))
				if attempt < maxRetries {
					waitTime := time.Duration(math.Pow(2, float64(attempt))) * time.Second
					fmt.Printf("\033[33m[ACK RETRY] Attempt %d/%d for %s (%s), retrying in %v...\033[0m\n",
						attempt, maxRetries, dropNumber, lastErr, waitTime)
					time.Sleep(waitTime)
					continue
				}
				fmt.Printf("\033[31m[ACK FAILED] All %d attempts failed for %s: %s\033[0m\n", maxRetries, dropNumber, lastErr)
				return
			}

			if err := json.Unmarshal(body, &ackResp); err != nil {
				fmt.Printf("\033[31m[ACK ERROR] Failed to parse acknowledgment response for %s: %v\033[0m\n", dropNumber, err)
				return
			}

			// Success - break out of retry loop
			break
		}

		if !ackResp.Success || ackResp.Data.Message == "" {
			fmt.Printf("\033[33m[ACK WARN] No acknowledgment message for %s\033[0m\n", dropNumber)
			return
		}

		// Send reply to the original message
		success, msg := sendViaSenderService(chatJID, senderJID, ackResp.Data.Message)
		if success {
			fmt.Printf("📱 Sent acknowledgment reply for %s (photos: %d, ONT: %v, UPS: %v)\n",
				dropNumber, ackResp.Data.PhotoCount, ackResp.Data.OntSerial != "", ackResp.Data.UpsSerial != "")
		} else {
			fmt.Printf("\033[31m[ACK ERROR] Failed to send acknowledgment reply: %s\033[0m\n", msg)
		}
	}()
}

