export $(grep DATABASE_URL .env.local | head -1 | xargs) && node -e '
const { neon } = require("@neondatabase/serverless");
const sql = neon(process.env.DATABASE_URL);
(async () => {
  // OneDrive PONs for POP 1
  const odPons = [137, ...Array.from({length:50}, (_,i) => 190+i), 243,244,245,246,247, 260,261, 264,265,266,267];

  // Get PONs with reviews in POP 1
  const dbPons = await sql`
    SELECT DISTINCT pon_no 
    FROM construction_qa_reviews 
    WHERE project_id = ${"7d8b94d6-8e5a-4dbb-9ede-69ce3884e004"} 
    AND pon_no IS NOT NULL
    ORDER BY pon_no
  `;
  const dbPonSet = new Set(dbPons.map(r => Number(r.pon_no)));

  // Get PONs that exist in poles table
  const allPons = await sql`
    SELECT DISTINCT pon_no 
    FROM poles 
    WHERE project_id = ${"7d8b94d6-8e5a-4dbb-9ede-69ce3884e004"} 
    AND pon_no IS NOT NULL
    ORDER BY pon_no
  `;
  const allPonSet = new Set(allPons.map(r => Number(r.pon_no)));

  console.log("=== Thembisa POP 1 - PON Coverage ===");
  console.log("OneDrive PONs:", odPons.length);
  console.log("DB PONs with reviews:", dbPonSet.size);
  console.log("DB PONs (all poles):", allPonSet.size);

  const newPons = odPons.filter(p => !dbPonSet.has(p));
  const existingPons = odPons.filter(p => dbPonSet.has(p));

  console.log("\nPONs with reviews already:", existingPons.length, existingPons.join(", "));
  console.log("\nPONs WITHOUT reviews (new data):", newPons.length);
  if (newPons.length > 0) {
    console.log("  ", newPons.join(", "));
  }

  // Check how many poles exist in these new PONs
  for (const pon of newPons.slice(0, 10)) {
    const poles = await sql`
      SELECT COUNT(*)::int as cnt FROM poles 
      WHERE project_id = ${"7d8b94d6-8e5a-4dbb-9ede-69ce3884e004"} AND pon_no = ${pon}
    `;
    if (poles[0].cnt > 0) process.stdout.write(pon + "(" + poles[0].cnt + " poles) ");
  }
  console.log("");
})();
'

export $(grep DATABASE_URL .env.local | head -1 | xargs) && node -e '
const { neon } = require("@neondatabase/serverless");
const sql = neon(process.env.DATABASE_URL);
(async () => {
  const odPons = [137, ...Array.from({length:50}, (_,i) => 190+i), 243,244,245,246,247, 260,261, 264,265,266,267];

  const dbPons = await sql`
    SELECT DISTINCT pon_no FROM construction_qa_reviews 
    WHERE project_id = ${"7d8b94d6-8e5a-4dbb-9ede-69ce3884e004"} AND pon_no IS NOT NULL
    ORDER BY pon_no
  `;
  const dbPonSet = new Set(dbPons.map(r => Number(r.pon_no)));

  console.log("=== Thembisa POP 1 - PON Coverage ===");
  console.log("OneDrive PONs:", odPons.length);
  console.log("DB PONs with reviews:", dbPonSet.size);

  const newPons = odPons.filter(p => dbPonSet.has(p) === false);
  const existingPons = odPons.filter(p => dbPonSet.has(p));

  console.log("\nAlready have reviews:", existingPons.length, "PONs");
  console.log("NEW (no reviews yet):", newPons.length, "PONs");
  if (newPons.length > 0) console.log("  ", newPons.join(", "));

  // Count poles in new PONs
  if (newPons.length > 0) {
    const counts = await sql`
      SELECT pon_no, COUNT(*)::int as cnt FROM poles 
      WHERE project_id = ${"7d8b94d6-8e5a-4dbb-9ede-69ce3884e004"} 
      AND pon_no = ANY(${newPons})
      GROUP BY pon_no ORDER BY pon_no
    `;
    console.log("\nPoles in new PONs:");
    let totalPoles = 0;
    counts.forEach(r => { 
      console.log("  Pon", r.pon_no, "→", r.cnt, "poles");
      totalPoles += r.cnt;
    });
    console.log("Total new poles:", totalPoles);
  }
})();
'

