async () => {
  // The OneDrive SPA uses service workers/webpack. Let me try to use the page's 
  // internal fetch mechanism by triggering a navigation and intercepting the XHR
  // Or better: use the XMLHttpRequest that the page uses

  const DRIVE_ID = '2b788f0a6d95f194';
  const BASE = 'https://my.microsoftpersonalcontent.com/_api/v2.0';
  const POP1_ID = '2B788F0A6D95F194!sd31d8ca533474ebf934ee849903e5720';

  return new Promise((resolve) => {
    const xhr = new XMLHttpRequest();
    const url = `${BASE}/drives/${DRIVE_ID}/items/${POP1_ID}/children?$top=200&orderby=folder,name%20asc&$select=name,id,folder,file,size&ump=1`;

    const boundary = '---boundary' + Date.now();
    xhr.open('POST', url, true);
    xhr.setRequestHeader('Content-Type', `multipart/form-data;boundary=${boundary}`);
    xhr.withCredentials = true;

    xhr.onload = function() {
      if (xhr.status === 200) {
        const data = JSON.parse(xhr.responseText);
        const items = (data.value || []).map(i => ({
          name: i.name,
          id: i.id,
          children: i.folder?.childCount || 0
        }));
        resolve({ total: items.length, first5: items.slice(0, 5), last5: items.slice(-5) });
      } else {
        resolve({ error: xhr.status, text: xhr.responseText.slice(0, 200) });
      }
    };
    xhr.onerror = function() { resolve({ error: 'network' }); };

    // Build multipart body with method override (same pattern as the page uses)
    const body = `--${boundary}\r\nContent-Disposition: form-data;name=data\r\nX-HTTP-Method-Override: GET\r\nContent-Type: application/json\r\n\r\n\r\n--${boundary}--`;
    xhr.send(body);
  });
}

