/**
 * GET /api/projects/[projectId]/boq-utilization
 *
 * Returns BOQ utilization data for a project:
 * - Per-line: boq_qty, ordered_qty, received_qty, outstanding_qty
 * - Summary: total value, ordered %, received %
 * - Non-BOQ items: ad-hoc PO items not linked to any BOQ line
 */
import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import type {
  BOQLineUtilization,
  BOQUtilizationResponse,
  BOQUtilizationSummary,
  NonBOQItem,
} from '@/types/procurement/boq-utilization.types';

// Re-export types for consumers that can import from this route
export type { BOQLineUtilization, NonBOQItem, BOQUtilizationSummary, BOQUtilizationResponse } from '@/types/procurement/boq-utilization.types';

const sql = neon(process.env.DATABASE_URL!);

export default withAuth(withErrorHandler(async (req: NextApiRequest, res: NextApiResponse) => {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const { projectId } = req.query;
  if (!projectId || typeof projectId !== 'string') {
    return apiResponse.validationError(res, { projectId: 'Project ID is required' });
  }

  // BOQ line utilization — pre-aggregate PO + GRN data to avoid JOIN multiplication
  // and filter out cancelled POs / unconfirmed GRNs
  const lines = await sql`
    SELECT
      bi.id,
      bi.boq_id,
      bi.line_number,
      bi.item_code,
      bi.description,
      COALESCE(bi.uom, 'units') AS uom,
      bi.quantity AS boq_qty,
      bi.unit_price,
      bi.total_price AS boq_value,
      COALESCE(po_agg.total_ordered, 0) AS ordered_qty,
      COALESCE(grn_agg.total_received, 0) AS received_qty,
      bi.quantity - COALESCE(po_agg.total_ordered, 0) AS outstanding_qty,
      COALESCE(po_agg.total_ordered_value, 0) AS ordered_value
    FROM boq_items bi
    JOIN boqs b ON bi.boq_id = b.id
    LEFT JOIN (
      SELECT
        poi.boq_item_id,
        SUM(poi.quantity_ordered) AS total_ordered,
        SUM(poi.quantity_ordered * poi.unit_price) AS total_ordered_value
      FROM purchase_order_items poi
      JOIN purchase_orders po ON po.id = poi.purchase_order_id
      WHERE poi.boq_item_id IS NOT NULL
        AND po.status NOT IN ('cancelled')
      GROUP BY poi.boq_item_id
    ) po_agg ON po_agg.boq_item_id = bi.id
    LEFT JOIN (
      SELECT
        poi.boq_item_id,
        SUM(gri.quantity_accepted) AS total_received
      FROM goods_receipt_items gri
      JOIN purchase_order_items poi ON gri.po_item_id = poi.id
      JOIN purchase_orders po ON po.id = poi.purchase_order_id
      JOIN goods_receipt_notes grn ON gri.grn_id = grn.id
      WHERE poi.boq_item_id IS NOT NULL
        AND po.status NOT IN ('cancelled')
        AND grn.status = 'completed'
      GROUP BY poi.boq_item_id
    ) grn_agg ON grn_agg.boq_item_id = bi.id
    WHERE b.project_id = ${projectId}
      AND b.status NOT IN ('superseded', 'archived', 'cancelled')
      AND (bi.item_code IS NULL OR bi.item_code != 'TOTAL')
    ORDER BY bi.line_number NULLS LAST, bi.description
  `;

  // Non-BOQ PO items for this project
  const nonBoqRows = await sql`
    SELECT
      poi.id,
      poi.item_code,
      poi.item_description,
      poi.quantity_ordered,
      poi.quantity_received,
      poi.unit_price,
      poi.total_price,
      po.po_number,
      po.id AS po_id
    FROM purchase_order_items poi
    JOIN purchase_orders po ON poi.purchase_order_id = po.id
    WHERE po.project_id = ${projectId}
      AND poi.boq_item_id IS NULL
      AND po.status NOT IN ('cancelled')
    ORDER BY po.order_date DESC, poi.item_description
  `;

  // Build typed response
  const typedLines: BOQLineUtilization[] = lines.map((r) => {
    const orderedQty = Number(r.ordered_qty);
    const receivedQty = Number(r.received_qty);
    const boqQty = Number(r.boq_qty);
    let status: BOQLineUtilization['status'] = 'not_ordered';
    if (receivedQty >= boqQty && boqQty > 0) status = 'received';
    else if (receivedQty > 0) status = 'partially_received';
    else if (orderedQty > boqQty) status = 'over_ordered';
    else if (orderedQty >= boqQty) status = 'fully_ordered';
    else if (orderedQty > 0) status = 'partial';

    return {
      id: r.id as string,
      boqId: r.boq_id as string,
      lineNumber: r.line_number as number | null,
      itemCode: r.item_code as string | null,
      description: r.description as string,
      uom: r.uom as string,
      boqQty,
      orderedQty,
      receivedQty: Number(r.received_qty),
      outstandingQty: Number(r.outstanding_qty),
      unitPrice: r.unit_price ? Number(r.unit_price) : null,
      boqValue: r.boq_value ? Number(r.boq_value) : null,
      orderedValue: Number(r.ordered_value),
      status,
    };
  });

  const typedNonBoq: NonBOQItem[] = nonBoqRows.map((r) => ({
    id: r.id as string,
    itemCode: r.item_code as string | null,
    itemDescription: r.item_description as string,
    quantityOrdered: Number(r.quantity_ordered),
    quantityReceived: Number(r.quantity_received),
    unitPrice: Number(r.unit_price),
    totalPrice: r.total_price ? Number(r.total_price) : null,
    poNumber: r.po_number as string,
    poId: r.po_id as string,
  }));

  const totalBoqValue = typedLines.reduce((s, l) => s + (l.boqValue ?? 0), 0);
  const totalOrderedValue = typedLines.reduce((s, l) => s + (l.orderedValue ?? 0), 0);
  const totalReceivedValue = typedLines.reduce((s, l) => s + l.receivedQty * (l.unitPrice ?? 0), 0);

  const summary: BOQUtilizationSummary = {
    totalBoqValue,
    totalOrderedValue,
    totalReceivedValue,
    orderedPercent: totalBoqValue > 0 ? Math.round((totalOrderedValue / totalBoqValue) * 100) : 0,
    receivedPercent: totalBoqValue > 0 ? Math.round((totalReceivedValue / totalBoqValue) * 100) : 0,
    boqLineCount: typedLines.length,
    orderedLineCount: typedLines.filter((l) => l.orderedQty > 0).length,
    nonBoqItemCount: typedNonBoq.length,
  };

  const result: BOQUtilizationResponse = {
    summary,
    lines: typedLines,
    nonBoqItems: typedNonBoq,
  };

  return apiResponse.success(res, result);
}));

/**
 * BOQUtilizationTable — BOQ financial utilization view.
 * Shows BOQ Value / Ordered Value / Remaining Value per line,
 * with KPI summary cards and a progress bar at the top.
 *
 * Used on the project detail page → BOQ/Materials tab.
 */

import { useEffect, useState } from 'react';
import { Loader2, TrendingUp, Package } from 'lucide-react';
import type { BOQUtilizationResponse, BOQLineUtilization, NonBOQItem } from '@/types/procurement/boq-utilization.types';
import { log } from '@/lib/logger';
import { ExportCSVButton } from '@/components/shared/ExportCSVButton';

interface BOQUtilizationTableProps {
  projectId: string;
}

function statusBadge(line: BOQLineUtilization) {
  switch (line.status) {
    case 'received':
      return <span className="inline-flex items-center gap-1 text-xs text-green-400 font-medium">● Received</span>;
    case 'partially_received':
      return <span className="inline-flex items-center gap-1 text-xs text-emerald-400 font-medium">◐ Part Recv</span>;
    case 'fully_ordered':
      return <span className="inline-flex items-center gap-1 text-xs text-purple-400 font-medium">● Ordered</span>;
    case 'over_ordered':
      return <span className="inline-flex items-center gap-1 text-xs text-orange-400 font-medium">▲ Over</span>;
    case 'partial':
      return <span className="inline-flex items-center gap-1 text-xs text-amber-400 font-medium">◑ Partial</span>;
    default:
      return <span className="inline-flex items-center gap-1 text-xs text-[var(--ff-text-tertiary)]">○ Not ordered</span>;
  }
}

function fmtQty(n: number, uom: string) {
  return `${n.toLocaleString('en-ZA', { maximumFractionDigits: 2 })} ${uom}`;
}

function fmtZAR(n: number) {
  return new Intl.NumberFormat('en-ZA', {
    style: 'currency',
    currency: 'ZAR',
    maximumFractionDigits: 0,
  }).format(n);
}

/** Stacked cell: value on top (primary), qty below (secondary) */
function ValueCell({
  value,
  qty,
  uom,
  valueClass = 'text-[var(--ff-text-primary)]',
  empty = false,
}: {
  value: number;
  qty: number;
  uom: string;
  valueClass?: string;
  empty?: boolean;
}) {
  if (empty || (value === 0 && qty === 0)) {
    return <span className="text-[var(--ff-text-tertiary)]">—</span>;
  }
  return (
    <div>
      <div className={`text-sm font-medium ${valueClass}`}>{fmtZAR(value)}</div>
      <div className="text-xs text-[var(--ff-text-tertiary)] mt-0.5">{fmtQty(qty, uom)}</div>
    </div>
  );
}

export function BOQUtilizationTable({ projectId }: BOQUtilizationTableProps) {
  const [data, setData] = useState<BOQUtilizationResponse | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [hideZero, setHideZero] = useState(true);

  useEffect(() => {
    const load = async () => {
      setIsLoading(true);
      setError(null);
      try {
        const res = await fetch(`/api/projects/${projectId}/boq-utilization`);
        const json = await res.json() as {
          success: boolean;
          data?: BOQUtilizationResponse;
          error?: { message: string };
        };
        if (json.success && json.data) {
          setData(json.data);
        } else {
          setError(json.error?.message ?? 'Failed to load BOQ utilization');
        }
      } catch (err) {
        log.error('Failed to load BOQ utilization', { err }, 'BOQUtilizationTable');
        setError('Failed to load BOQ utilization data');
      } finally {
        setIsLoading(false);
      }
    };
    load();
  }, [projectId]);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-40">
        <Loader2 className="h-6 w-6 animate-spin text-purple-500" />
        <span className="ml-2 text-sm text-[var(--ff-text-secondary)]">Loading utilization...</span>
      </div>
    );
  }

  if (error) {
    return <div className="p-4 bg-red-500/10 border border-red-500/30 rounded-lg text-sm text-red-400">{error}</div>;
  }

  if (!data || data.lines.length === 0) {
    return (
      <div className="text-center py-10 text-[var(--ff-text-tertiary)] text-sm">
        No BOQ lines found for this project.
      </div>
    );
  }

  const { summary, lines, nonBoqItems } = data;
  const remainingValue = summary.totalBoqValue - summary.totalOrderedValue;
  const remainingPercent = summary.totalBoqValue > 0
    ? Math.round((remainingValue / summary.totalBoqValue) * 100)
    : 0;

  const visibleLines = hideZero ? lines.filter((l) => l.boqQty > 0) : lines;
  const hiddenCount = lines.length - visibleLines.length;

  return (
    <div className="space-y-4">

      {/* ── Export Button ── */}
      <div className="flex justify-end">
        <ExportCSVButton
          endpoint={`/api/projects/${projectId}/boq-utilization-export`}
          filenamePrefix="boq-utilization"
        />
      </div>

      {/* ── KPI Summary Cards ── */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        {/* BOQ Value */}
        <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-4">
          <p className="text-xs text-[var(--ff-text-tertiary)] uppercase tracking-wide mb-1">Total BOQ Value</p>
          <p className="text-xl font-bold text-[var(--ff-text-primary)]">{fmtZAR(summary.totalBoqValue)}</p>
          <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">{summary.boqLineCount} lines</p>
        </div>

        {/* Ordered */}
        <div className="bg-[var(--ff-bg-secondary)] border border-purple-500/30 rounded-lg p-4">
          <p className="text-xs text-[var(--ff-text-tertiary)] uppercase tracking-wide mb-1">Ordered</p>
          <p className="text-xl font-bold text-purple-400">{fmtZAR(summary.totalOrderedValue)}</p>
          <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">
            {summary.orderedPercent}% of BOQ · {summary.orderedLineCount} of {summary.boqLineCount} lines
          </p>
        </div>

        {/* Remaining */}
        <div className="bg-[var(--ff-bg-secondary)] border border-amber-500/30 rounded-lg p-4">
          <p className="text-xs text-[var(--ff-text-tertiary)] uppercase tracking-wide mb-1">Remaining</p>
          <p className="text-xl font-bold text-amber-400">{fmtZAR(remainingValue)}</p>
          <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">{remainingPercent}% still to order</p>
        </div>

        {/* Received */}
        <div className="bg-[var(--ff-bg-secondary)] border border-green-500/30 rounded-lg p-4">
          <p className="text-xs text-[var(--ff-text-tertiary)] uppercase tracking-wide mb-1">Received</p>
          <p className="text-xl font-bold text-green-400">{fmtZAR(summary.totalReceivedValue)}</p>
          <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">{summary.receivedPercent}% of BOQ</p>
        </div>
      </div>

      {/* Progress bar */}
      <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg px-4 py-3">
        <div className="flex justify-between text-xs text-[var(--ff-text-tertiary)] mb-1.5">
          <span>Ordered {summary.orderedPercent}%</span>
          <span>Remaining {remainingPercent}%</span>
        </div>
        <div className="h-2.5 bg-[var(--ff-bg-tertiary)] rounded-full overflow-hidden flex">
          <div
            className="h-full bg-purple-500 transition-all"
            style={{ width: `${Math.min(summary.orderedPercent, 100)}%` }}
          />
          {summary.receivedPercent > 0 && (
            <div
              className="h-full bg-green-500 transition-all -ml-px"
              style={{ width: `${Math.min(summary.receivedPercent, summary.orderedPercent)}%` }}
            />
          )}
        </div>
        <p className="mt-1.5 text-xs text-[var(--ff-text-tertiary)]">
          {summary.orderedLineCount} of {summary.boqLineCount} lines ordered
          {nonBoqItems.length > 0 && ` · ${nonBoqItems.length} ad-hoc item${nonBoqItems.length > 1 ? 's' : ''} outside BOQ`}
        </p>
      </div>

      {/* ── Line-item table ── */}
      <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg overflow-hidden">
        <div className="flex items-center justify-between gap-2 px-4 py-3 border-b border-[var(--ff-border-light)]">
          <div className="flex items-center gap-2">
            <TrendingUp className="h-4 w-4 text-purple-400" />
            <h4 className="text-sm font-medium text-[var(--ff-text-primary)]">BOQ Line Detail</h4>
            <span className="text-xs text-[var(--ff-text-tertiary)]">
              {visibleLines.length} of {lines.length} lines
            </span>
          </div>
          <button
            type="button"
            onClick={() => setHideZero((v) => !v)}
            className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded text-xs transition-colors border ${
              hideZero
                ? 'bg-purple-600/20 border-purple-500/40 text-purple-400'
                : 'bg-[var(--ff-bg-tertiary)] border-[var(--ff-border-light)] text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-secondary)]'
            }`}
          >
            {hideZero ? `Hide zero qty (${hiddenCount})` : `Show all (${hiddenCount} zero)`}
          </button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                <th className="px-4 py-2.5 text-left text-xs font-medium text-[var(--ff-text-tertiary)] uppercase w-28">
                  Item Code
                </th>
                <th className="px-4 py-2.5 text-left text-xs font-medium text-[var(--ff-text-tertiary)] uppercase">
                  Description
                </th>
                <th className="px-4 py-2.5 text-right text-xs font-medium text-[var(--ff-text-tertiary)] uppercase w-36">
                  BOQ Value
                  <div className="text-[10px] font-normal normal-case text-[var(--ff-text-tertiary)]/70">qty</div>
                </th>
                <th className="px-4 py-2.5 text-right text-xs font-medium text-purple-400/80 uppercase w-36">
                  Ordered
                  <div className="text-[10px] font-normal normal-case text-[var(--ff-text-tertiary)]/70">qty</div>
                </th>
                <th className="px-4 py-2.5 text-right text-xs font-medium text-amber-400/80 uppercase w-36">
                  Remaining
                  <div className="text-[10px] font-normal normal-case text-[var(--ff-text-tertiary)]/70">qty</div>
                </th>
                <th className="px-4 py-2.5 text-right text-xs font-medium text-green-400/80 uppercase w-36">
                  Received
                  <div className="text-[10px] font-normal normal-case text-[var(--ff-text-tertiary)]/70">qty</div>
                </th>
                <th className="px-4 py-2.5 text-left text-xs font-medium text-[var(--ff-text-tertiary)] uppercase w-28">
                  Status
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[var(--ff-border-light)]">
              {visibleLines.map((line: BOQLineUtilization) => {
                const boqVal = line.boqValue ?? 0;
                const ordVal = line.orderedValue ?? 0;
                const remVal = boqVal - ordVal;
                const recVal = line.receivedQty * (line.unitPrice ?? 0);

                return (
                  <tr
                    key={line.id}
                    className={`hover:bg-[var(--ff-bg-hover)] transition-colors ${
                      line.status === 'fully_ordered' || line.status === 'over_ordered' ? 'opacity-60' : ''
                    }`}
                  >
                    <td className="px-4 py-3">
                      <span className="text-xs text-blue-400 font-mono">{line.itemCode ?? '—'}</span>
                    </td>
                    <td className="px-4 py-3 text-[var(--ff-text-primary)]">
                      <span className="line-clamp-2 text-sm leading-tight">{line.description}</span>
                    </td>

                    {/* BOQ Value + qty */}
                    <td className="px-4 py-3 text-right">
                      <ValueCell value={boqVal} qty={line.boqQty} uom={line.uom} empty={boqVal === 0 && line.unitPrice === null} />
                    </td>

                    {/* Ordered */}
                    <td className="px-4 py-3 text-right">
                      <ValueCell
                        value={ordVal}
                        qty={line.orderedQty}
                        uom={line.uom}
                        valueClass="text-purple-400"
                        empty={line.orderedQty === 0}
                      />
                    </td>

                    {/* Remaining */}
                    <td className="px-4 py-3 text-right">
                      <ValueCell
                        value={Math.max(0, remVal)}
                        qty={Math.max(0, line.outstandingQty)}
                        uom={line.uom}
                        valueClass={remVal <= 0 ? 'text-[var(--ff-text-tertiary)]' : 'text-amber-400'}
                        empty={false}
                      />
                    </td>

                    {/* Received */}
                    <td className="px-4 py-3 text-right">
                      <ValueCell
                        value={recVal}
                        qty={line.receivedQty}
                        uom={line.uom}
                        valueClass="text-green-400"
                        empty={line.receivedQty === 0}
                      />
                    </td>

                    <td className="px-4 py-3">{statusBadge(line)}</td>
                  </tr>
                );
              })}
            </tbody>

            {/* Footer totals */}
            <tfoot>
              <tr className="border-t-2 border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                <td colSpan={2} className="px-4 py-3 text-xs font-medium text-[var(--ff-text-tertiary)] uppercase">
                  Total ({visibleLines.length} lines)
                </td>
                <td className="px-4 py-3 text-right">
                  <span className="text-sm font-semibold text-[var(--ff-text-primary)]">
                    {fmtZAR(visibleLines.reduce((s, l) => s + (l.boqValue ?? 0), 0))}
                  </span>
                </td>
                <td className="px-4 py-3 text-right">
                  <span className="text-sm font-semibold text-purple-400">
                    {fmtZAR(visibleLines.reduce((s, l) => s + (l.orderedValue ?? 0), 0))}
                  </span>
                </td>
                <td className="px-4 py-3 text-right">
                  <span className="text-sm font-semibold text-amber-400">
                    {fmtZAR(visibleLines.reduce((s, l) => s + Math.max(0, (l.boqValue ?? 0) - (l.orderedValue ?? 0)), 0))}
                  </span>
                </td>
                <td className="px-4 py-3 text-right">
                  <span className="text-sm font-semibold text-green-400">
                    {fmtZAR(visibleLines.reduce((s, l) => s + l.receivedQty * (l.unitPrice ?? 0), 0))}
                  </span>
                </td>
                <td />
              </tr>
            </tfoot>
          </table>
        </div>
      </div>

      {/* ── Non-BOQ ad-hoc items ── */}
      {nonBoqItems.length > 0 && (
        <div className="bg-[var(--ff-bg-secondary)] border border-amber-500/20 rounded-lg overflow-hidden">
          <div className="flex items-center gap-2 px-4 py-3 border-b border-[var(--ff-border-light)]">
            <Package className="h-4 w-4 text-amber-400" />
            <h4 className="text-sm font-medium text-[var(--ff-text-primary)]">
              Ad-hoc Orders <span className="text-amber-400">({nonBoqItems.length})</span>
            </h4>
            <span className="text-xs text-[var(--ff-text-tertiary)]">not in BOQ</span>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                  <th className="px-4 py-2.5 text-left text-xs font-medium text-[var(--ff-text-tertiary)] uppercase">Item Code</th>
                  <th className="px-4 py-2.5 text-left text-xs font-medium text-[var(--ff-text-tertiary)] uppercase">Description</th>
                  <th className="px-4 py-2.5 text-right text-xs font-medium text-[var(--ff-text-tertiary)] uppercase">Value</th>
                  <th className="px-4 py-2.5 text-right text-xs font-medium text-[var(--ff-text-tertiary)] uppercase">Qty Ordered</th>
                  <th className="px-4 py-2.5 text-right text-xs font-medium text-[var(--ff-text-tertiary)] uppercase">Qty Received</th>
                  <th className="px-4 py-2.5 text-left text-xs font-medium text-[var(--ff-text-tertiary)] uppercase">PO</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[var(--ff-border-light)]">
                {nonBoqItems.map((item: NonBOQItem) => (
                  <tr key={item.id} className="hover:bg-[var(--ff-bg-hover)] transition-colors">
                    <td className="px-4 py-2.5">
                      <span className="text-xs text-amber-400 font-mono">{item.itemCode ?? '—'}</span>
                    </td>
                    <td className="px-4 py-2.5 text-[var(--ff-text-primary)]">{item.itemDescription}</td>
                    <td className="px-4 py-2.5 text-right text-[var(--ff-text-secondary)]">
                      {item.totalPrice ? fmtZAR(item.totalPrice) : '—'}
                    </td>
                    <td className="px-4 py-2.5 text-right text-[var(--ff-text-secondary)]">{item.quantityOrdered.toLocaleString()}</td>
                    <td className="px-4 py-2.5 text-right text-[var(--ff-text-secondary)]">{item.quantityReceived.toLocaleString()}</td>
                    <td className="px-4 py-2.5 text-blue-400 font-mono text-xs">{item.poNumber}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

/** Shared types for BOQ utilization API response. */

export interface BOQLineUtilization {
  id: string;
  boqId: string;
  lineNumber: number | null;
  itemCode: string | null;
  description: string;
  uom: string;
  boqQty: number;
  orderedQty: number;
  receivedQty: number;
  outstandingQty: number;
  unitPrice: number | null;
  boqValue: number | null;
  orderedValue: number | null;
  status: 'not_ordered' | 'partial' | 'fully_ordered' | 'over_ordered' | 'partially_received' | 'received';
}

export interface NonBOQItem {
  id: string;
  itemCode: string | null;
  itemDescription: string;
  quantityOrdered: number;
  quantityReceived: number;
  unitPrice: number;
  totalPrice: number | null;
  poNumber: string;
  poId: string;
}

export interface BOQUtilizationSummary {
  totalBoqValue: number;
  totalOrderedValue: number;
  totalReceivedValue: number;
  orderedPercent: number;
  receivedPercent: number;
  boqLineCount: number;
  orderedLineCount: number;
  nonBoqItemCount: number;
}

export interface BOQUtilizationResponse {
  summary: BOQUtilizationSummary;
  lines: BOQLineUtilization[];
  nonBoqItems: NonBOQItem[];
}

/**
 * Project Budget Page
 * PRD-057: Project Budget Tracking System
 *
 * Main budget management page for a project - displays budget overview,
 * category breakdown, alerts, and transaction history
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout';
import {
  BudgetOverviewCard,
  CategoryBreakdownTable,
  BudgetAlertsPanel,
  BudgetAdjustmentModal,
  BudgetItemsTable,
} from '@/components/budget';
import { ArrowLeft, Plus, RefreshCw, History, AlertCircle, Upload, Package, X, FileSpreadsheet, CheckCircle } from 'lucide-react';
import type { BudgetItemWithCategory, BOQImportResult } from '@/types/procurement/material-catalog.types';
import type {
  ProjectBudget,
  BudgetCategory,
  BudgetAlert,
  BudgetTransaction,
  BudgetHealth,
  BudgetStatus,
} from '@/types/budget';

interface BudgetPageData {
  budget: ProjectBudget | null;
  categories: BudgetCategory[];
  alerts: BudgetAlert[];
  transactions: BudgetTransaction[];
  budgetItems: BudgetItemWithCategory[];
  project: {
    id: string;
    name: string;
    projectNumber: string;
  } | null;
}

export default function ProjectBudgetPage() {
  const router = useRouter();
  const { id: projectId } = router.query;

  const [data, setData] = useState<BudgetPageData>({
    budget: null,
    categories: [],
    alerts: [],
    transactions: [],
    budgetItems: [],
    project: null,
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [adjustModalOpen, setAdjustModalOpen] = useState(false);
  const [createModalOpen, setCreateModalOpen] = useState(false);
  const [importModalOpen, setImportModalOpen] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'overview' | 'items' | 'transactions'>('overview');

  // Fetch budget data
  const fetchBudgetData = useCallback(async () => {
    if (!projectId || typeof projectId !== 'string') return;

    setLoading(true);
    setError(null);

    try {
      // Fetch budget, categories, alerts, items in parallel
      const [budgetRes, categoriesRes, alertsRes, transactionsRes, projectRes, itemsRes] = await Promise.all([
        fetch(`/api/projects/${projectId}/budget`),
        fetch(`/api/projects/${projectId}/budget/categories`),
        fetch(`/api/projects/${projectId}/budget/alerts`),
        fetch(`/api/projects/${projectId}/budget/transactions?limit=10`),
        fetch(`/api/projects/${projectId}`),
        fetch(`/api/projects/${projectId}/budget/items`),
      ]);

      const budgetData = await budgetRes.json();
      const categoriesData = await categoriesRes.json();
      const alertsData = await alertsRes.json();
      const transactionsData = await transactionsRes.json();
      const projectData = await projectRes.json();
      const itemsData = await itemsRes.json();

      // Budget API returns { exists: false } or { exists: true, budget, categories, summary }
      const budgetExists = budgetRes.ok && budgetData.data?.exists === true;

      setData({
        budget: budgetExists ? budgetData.data.budget : null,
        categories: budgetExists
          ? (budgetData.data.categories || [])
          : (categoriesRes.ok && Array.isArray(categoriesData.data) ? categoriesData.data : []),
        alerts: alertsRes.ok && alertsData.data?.alerts ? alertsData.data.alerts : [],
        transactions: transactionsRes.ok && transactionsData.data?.transactions ? transactionsData.data.transactions : [],
        budgetItems: itemsRes.ok && itemsData.data?.items ? itemsData.data.items : [],
        project: projectRes.ok ? projectData.data : null,
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load budget data');
    } finally {
      setLoading(false);
    }
  }, [projectId]);

  useEffect(() => {
    fetchBudgetData();
  }, [fetchBudgetData]);

  // Handle budget adjustment
  const handleAdjustment = async (adjustmentData: {
    adjustmentType: 'increase' | 'decrease' | 'reallocation';
    amount: number;
    reason: string;
  }) => {
    if (!projectId) return;

    setActionLoading(true);
    try {
      const res = await fetch(`/api/projects/${projectId}/budget/adjust`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(adjustmentData),
      });

      if (!res.ok) {
        const errorData = await res.json();
        throw new Error(errorData.error?.message || 'Failed to adjust budget');
      }

      // Refresh data
      await fetchBudgetData();
      setAdjustModalOpen(false);
    } catch (err) {
      throw err;
    } finally {
      setActionLoading(false);
    }
  };

  // Handle BOQ sync
  const handleSyncBoq = async () => {
    if (!projectId) return;

    setActionLoading(true);
    try {
      const res = await fetch(`/api/projects/${projectId}/budget/sync-boq`, {
        method: 'POST',
      });

      if (!res.ok) {
        const errorData = await res.json();
        throw new Error(errorData.error?.message || 'Failed to sync BOQ');
      }

      await fetchBudgetData();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to sync BOQ');
    } finally {
      setActionLoading(false);
    }
  };

  // Handle alert acknowledge
  const handleAcknowledge = async (alertId: string) => {
    if (!projectId) return;

    setActionLoading(true);
    try {
      const res = await fetch(`/api/projects/${projectId}/budget/alerts/${alertId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'acknowledge' }),
      });

      if (!res.ok) {
        throw new Error('Failed to acknowledge alert');
      }

      await fetchBudgetData();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to acknowledge alert');
    } finally {
      setActionLoading(false);
    }
  };

  // Handle alert resolve
  const handleResolve = async (alertId: string) => {
    if (!projectId) return;

    setActionLoading(true);
    try {
      const res = await fetch(`/api/projects/${projectId}/budget/alerts/${alertId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'resolve' }),
      });

      if (!res.ok) {
        throw new Error('Failed to resolve alert');
      }

      await fetchBudgetData();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to resolve alert');
    } finally {
      setActionLoading(false);
    }
  };

  // Handle create budget
  const handleCreateBudget = async (budgetData: {
    sourceType: 'manual' | 'boq';
    totalBudget?: number;
    boqId?: string;
  }) => {
    if (!projectId) return;

    setActionLoading(true);
    try {
      const res = await fetch(`/api/projects/${projectId}/budget`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(budgetData),
      });

      if (!res.ok) {
        const errorData = await res.json();
        throw new Error(errorData.error?.message || 'Failed to create budget');
      }

      await fetchBudgetData();
      setCreateModalOpen(false);
    } catch (err) {
      throw err;
    } finally {
      setActionLoading(false);
    }
  };

  // Calculate budget health from utilization
  const getBudgetHealth = (budget: ProjectBudget | null): BudgetHealth => {
    if (!budget) return 'healthy';
    const utilization = budget.totalBudget > 0
      ? (budget.committedAmount / budget.totalBudget) * 100
      : 0;
    if (utilization >= 100) return 'critical';
    if (utilization >= 80) return 'warning';
    return 'healthy';
  };

  // Format transaction for display
  const formatTransaction = (tx: BudgetTransaction) => {
    const typeLabels: Record<string, string> = {
      allocation: 'Allocation',
      adjustment: 'Adjustment',
      commitment: 'Commitment',
      commitment_reversal: 'Reversal',
      receipt: 'Receipt',
    };
    return {
      ...tx,
      typeLabel: typeLabels[tx.transactionType] || tx.transactionType,
    };
  };

  if (loading) {
    return (
      <AppLayout hideHeader>
        <div className="p-6">
          <div className="animate-pulse space-y-4">
            <div className="h-8 bg-gray-200 dark:bg-gray-700 rounded w-1/4"></div>
            <div className="h-64 bg-gray-200 dark:bg-gray-700 rounded"></div>
            <div className="h-48 bg-gray-200 dark:bg-gray-700 rounded"></div>
          </div>
        </div>
      </AppLayout>
    );
  }

  const noBudget = !data.budget;
  const budget = data.budget;
  const utilizationPercent = budget && budget.totalBudget > 0
    ? (budget.committedAmount / budget.totalBudget) * 100
    : 0;

  return (
    <AppLayout hideHeader>
      <div className="p-6 space-y-6" data-testid="budget-page">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button
              onClick={() => router.push(`/projects/${projectId}`)}
              className="p-2 text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg"
            >
              <ArrowLeft className="h-5 w-5" />
            </button>
            <div>
              <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Project Budget</h1>
              {data.project && (
                <p className="text-sm text-gray-500 dark:text-gray-400">
                  {data.project.projectNumber} - {data.project.name}
                </p>
              )}
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={fetchBudgetData}
              disabled={actionLoading}
              className="flex items-center gap-2 px-3 py-2 text-sm text-gray-600 dark:text-gray-300 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 disabled:opacity-50"
            >
              <RefreshCw className={`h-4 w-4 ${actionLoading ? 'animate-spin' : ''}`} />
              Refresh
            </button>
            {noBudget ? (
              <button
                onClick={() => setCreateModalOpen(true)}
                className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-lg hover:bg-blue-700"
                data-testid="create-budget-btn"
              >
                <Plus className="h-4 w-4" />
                Create Budget
              </button>
            ) : (
              <button
                onClick={() => setImportModalOpen(true)}
                className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-white bg-green-600 rounded-lg hover:bg-green-700"
              >
                <Upload className="h-4 w-4" />
                Import BOQ
              </button>
            )}
          </div>
        </div>

        {/* Error Display */}
        {error && (
          <div className="p-4 bg-red-50 dark:bg-red-900/30 border border-red-200 dark:border-red-800 rounded-lg flex items-center gap-3">
            <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0" />
            <p className="text-sm text-red-700 dark:text-red-400">{error}</p>
            <button
              onClick={() => setError(null)}
              className="ml-auto text-red-500 hover:text-red-700 dark:hover:text-red-400"
            >
              Dismiss
            </button>
          </div>
        )}

        {/* No Budget State */}
        {noBudget && (
          <div className="bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700 p-8 text-center">
            <div className="mx-auto w-12 h-12 bg-gray-100 dark:bg-gray-700 rounded-full flex items-center justify-center mb-4">
              <Plus className="h-6 w-6 text-gray-400 dark:text-gray-500" />
            </div>
            <h2 className="text-lg font-semibold text-gray-900 dark:text-white mb-2">No Budget Set</h2>
            <p className="text-gray-500 dark:text-gray-400 mb-4 max-w-md mx-auto">
              This project doesn&apos;t have a budget configured yet. Create a budget to track
              spending and enforce limits on purchase orders.
            </p>
            <button
              onClick={() => setCreateModalOpen(true)}
              className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-lg hover:bg-blue-700"
            >
              Create Budget
            </button>
          </div>
        )}

        {/* Budget Content */}
        {budget && (
          <>
            {/* Tab Navigation */}
            <div className="flex border-b border-gray-200 dark:border-gray-700">
              <button
                onClick={() => setActiveTab('overview')}
                className={`px-4 py-2 text-sm font-medium border-b-2 -mb-px ${
                  activeTab === 'overview'
                    ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                    : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
                }`}
              >
                Overview
              </button>
              <button
                onClick={() => setActiveTab('items')}
                className={`px-4 py-2 text-sm font-medium border-b-2 -mb-px flex items-center gap-2 ${
                  activeTab === 'items'
                    ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                    : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
                }`}
              >
                <Package className="h-4 w-4" />
                Budget Items
                {data.budgetItems.length > 0 && (
                  <span className="ml-1 px-1.5 py-0.5 text-xs bg-gray-100 dark:bg-gray-700 rounded-full">
                    {data.budgetItems.length}
                  </span>
                )}
              </button>
              <button
                onClick={() => setActiveTab('transactions')}
                className={`px-4 py-2 text-sm font-medium border-b-2 -mb-px flex items-center gap-2 ${
                  activeTab === 'transactions'
                    ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                    : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
                }`}
              >
                <History className="h-4 w-4" />
                Transactions
              </button>
            </div>

            {activeTab === 'overview' && (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Left Column - Overview & Categories */}
                <div className="lg:col-span-2 space-y-6">
                  <BudgetOverviewCard
                    totalBudget={budget.totalBudget}
                    committedAmount={budget.committedAmount}
                    actualAmount={budget.actualAmount}
                    availableBudget={budget.availableBudget}
                    utilizationPercent={utilizationPercent}
                    health={getBudgetHealth(budget)}
                    status={budget.status as BudgetStatus}
                    currency={budget.currency}
                    sourceType={budget.sourceType}
                    onSyncBoq={budget.sourceType !== 'manual' ? handleSyncBoq : undefined}
                    onAdjust={() => setAdjustModalOpen(true)}
                    canAdjust={true}
                  />

                  <CategoryBreakdownTable
                    categories={data.categories}
                    currency={budget.currency}
                    canEdit={true}
                  />
                </div>

                {/* Right Column - Alerts */}
                <div className="space-y-6">
                  <BudgetAlertsPanel
                    alerts={data.alerts}
                    onAcknowledge={handleAcknowledge}
                    onResolve={handleResolve}
                    loading={actionLoading}
                  />
                </div>
              </div>
            )}

            {activeTab === 'items' && (
              <BudgetItemsTable
                items={data.budgetItems}
                currency={budget.currency}
                loading={loading}
              />
            )}

            {activeTab === 'transactions' && (
              <div className="bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700 shadow-sm">
                <div className="p-4 border-b border-gray-100 dark:border-gray-700">
                  <h3 className="text-lg font-semibold text-gray-900 dark:text-white">Transaction History</h3>
                </div>
                {data.transactions.length === 0 ? (
                  <div className="p-8 text-center text-gray-500 dark:text-gray-400">
                    <History className="h-8 w-8 mx-auto mb-2 text-gray-400 dark:text-gray-500" />
                    <p>No transactions yet</p>
                  </div>
                ) : (
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead>
                        <tr className="border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900">
                          <th className="text-left py-3 px-4 font-medium text-gray-600 dark:text-gray-300">Date</th>
                          <th className="text-left py-3 px-4 font-medium text-gray-600 dark:text-gray-300">Type</th>
                          <th className="text-left py-3 px-4 font-medium text-gray-600 dark:text-gray-300">Description</th>
                          <th className="text-left py-3 px-4 font-medium text-gray-600 dark:text-gray-300">Reference</th>
                          <th className="text-right py-3 px-4 font-medium text-gray-600 dark:text-gray-300">Amount</th>
                        </tr>
                      </thead>
                      <tbody>
                        {data.transactions.map((tx) => {
                          const formatted = formatTransaction(tx);
                          const isDebit = ['commitment', 'receipt'].includes(tx.transactionType);
                          return (
                            <tr key={tx.id} className="border-b border-gray-200 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700/50">
                              <td className="py-3 px-4 text-gray-700 dark:text-gray-300">
                                {new Date(tx.createdAt).toLocaleDateString('en-ZA')}
                              </td>
                              <td className="py-3 px-4">
                                <span className={`px-2 py-0.5 text-xs font-medium rounded-full ${
                                  tx.transactionType === 'commitment' ? 'bg-blue-100 dark:bg-blue-900/50 text-blue-700 dark:text-blue-400' :
                                  tx.transactionType === 'receipt' ? 'bg-green-100 dark:bg-green-900/50 text-green-700 dark:text-green-400' :
                                  tx.transactionType === 'adjustment' ? 'bg-yellow-100 dark:bg-yellow-900/50 text-yellow-700 dark:text-yellow-400' :
                                  tx.transactionType === 'commitment_reversal' ? 'bg-red-100 dark:bg-red-900/50 text-red-700 dark:text-red-400' :
                                  'bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300'
                                }`}>
                                  {formatted.typeLabel}
                                </span>
                              </td>
                              <td className="py-3 px-4 text-gray-700 dark:text-gray-300">{tx.description || '-'}</td>
                              <td className="py-3 px-4 text-gray-500 dark:text-gray-400">{tx.sourceNumber || '-'}</td>
                              <td className={`py-3 px-4 text-right font-medium ${
                                isDebit ? 'text-red-600 dark:text-red-400' : 'text-green-600 dark:text-green-400'
                              }`}>
                                {isDebit ? '-' : '+'}
                                {new Intl.NumberFormat('en-ZA', {
                                  style: 'currency',
                                  currency: budget.currency || 'ZAR',
                                  minimumFractionDigits: 0,
                                }).format(Math.abs(tx.amount))}
                              </td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            )}
          </>
        )}

        {/* Budget Adjustment Modal */}
        <BudgetAdjustmentModal
          open={adjustModalOpen}
          onClose={() => setAdjustModalOpen(false)}
          onSubmit={handleAdjustment}
          currentBudget={budget?.totalBudget || 0}
          currency={budget?.currency}
        />

        {/* Budget Create Modal */}
        {createModalOpen && (
          <BudgetCreateModal
            open={createModalOpen}
            onClose={() => setCreateModalOpen(false)}
            onSubmit={handleCreateBudget}
            projectId={projectId as string}
          />
        )}

        {/* BOQ Import Modal */}
        {importModalOpen && (
          <BOQImportModal
            open={importModalOpen}
            onClose={() => setImportModalOpen(false)}
            onComplete={() => {
              setImportModalOpen(false);
              fetchBudgetData();
            }}
            projectId={projectId as string}
          />
        )}
      </div>
    </AppLayout>
  );
}

// Budget Create Modal Component
interface BudgetCreateModalProps {
  open: boolean;
  onClose: () => void;
  onSubmit: (data: { sourceType: 'manual' | 'boq'; totalBudget?: number; boqId?: string }) => Promise<void>;
  projectId: string;
}

function BudgetCreateModal({ open, onClose, onSubmit, projectId }: BudgetCreateModalProps) {
  const [sourceType, setSourceType] = useState<'manual' | 'boq'>('manual');
  const [totalBudget, setTotalBudget] = useState('');
  const [boqId, setBoqId] = useState('');
  const [boqs, setBoqs] = useState<Array<{ id: string; name: string; total: number }>>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Fetch available BOQs
  useEffect(() => {
    if (open && sourceType === 'boq') {
      fetch(`/api/projects/${projectId}/boq`)
        .then((res) => res.json())
        .then((data) => {
          if (data.data) setBoqs(data.data);
        })
        .catch(() => setBoqs([]));
    }
  }, [open, sourceType, projectId]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (sourceType === 'manual') {
      const amount = parseFloat(totalBudget);
      if (isNaN(amount) || amount <= 0) {
        setError('Please enter a valid budget amount');
        return;
      }
    } else if (!boqId) {
      setError('Please select a BOQ');
      return;
    }

    setLoading(true);
    try {
      await onSubmit({
        sourceType,
        totalBudget: sourceType === 'manual' ? parseFloat(totalBudget) : undefined,
        boqId: sourceType === 'boq' ? boqId : undefined,
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create budget');
    } finally {
      setLoading(false);
    }
  };

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/50" onClick={onClose} />
      <div className="relative bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-md mx-4" role="dialog" aria-modal="true">
        <div className="p-4 border-b border-gray-200 dark:border-gray-700">
          <h2 className="text-lg font-semibold text-gray-900 dark:text-white">Create Project Budget</h2>
          <p className="text-sm text-gray-500 dark:text-gray-400">Set up budget tracking for this project</p>
        </div>

        <form onSubmit={handleSubmit}>
          <div className="p-4 space-y-4">
            {/* Source Type */}
            <div className="space-y-2">
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Budget Source</label>
              <div className="flex gap-4">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="sourceType"
                    value="manual"
                    checked={sourceType === 'manual'}
                    onChange={() => setSourceType('manual')}
                    className="w-4 h-4 text-blue-600"
                  />
                  <span className="text-sm text-gray-700 dark:text-gray-300">Manual Entry</span>
                </label>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="sourceType"
                    value="boq"
                    checked={sourceType === 'boq'}
                    onChange={() => setSourceType('boq')}
                    className="w-4 h-4 text-blue-600"
                  />
                  <span className="text-sm text-gray-700 dark:text-gray-300">Sync from BOQ</span>
                </label>
              </div>
            </div>

            {/* Manual Budget Input */}
            {sourceType === 'manual' && (
              <div className="space-y-2">
                <label htmlFor="totalBudget" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                  Total Budget (ZAR)
                </label>
                <input
                  id="totalBudget"
                  type="number"
                  min="0"
                  step="0.01"
                  value={totalBudget}
                  onChange={(e) => setTotalBudget(e.target.value)}
                  placeholder="Enter budget amount"
                  required
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-gray-500 focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                />
              </div>
            )}

            {/* BOQ Selection */}
            {sourceType === 'boq' && (
              <div className="space-y-2">
                <label htmlFor="boqSelect" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                  Select BOQ
                </label>
                <select
                  id="boqSelect"
                  value={boqId}
                  onChange={(e) => setBoqId(e.target.value)}
                  required
                  className="w-full px-3 py-2 border border-gray-600 rounded-md bg-[#1a1d23] text-white focus:ring-1 focus:ring-blue-500 hover:border-gray-500"
                >
                  <option value="">Select a BOQ...</option>
                  {boqs.map((boq) => (
                    <option key={boq.id} value={boq.id}>
                      {boq.name} - R{boq.total.toLocaleString()}
                    </option>
                  ))}
                </select>
                {boqs.length === 0 && (
                  <p className="text-xs text-gray-500 dark:text-gray-400">No approved BOQs available for this project</p>
                )}
              </div>
            )}

            {/* Error Display */}
            {error && (
              <div className="p-3 bg-red-50 dark:bg-red-900/30 border border-red-200 dark:border-red-800 rounded-lg flex items-center gap-2">
                <AlertCircle className="h-4 w-4 text-red-500 flex-shrink-0" />
                <p className="text-sm text-red-600 dark:text-red-400">{error}</p>
              </div>
            )}
          </div>

          <div className="flex justify-end gap-2 p-4 border-t border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800 rounded-b-lg">
            <button
              type="button"
              onClick={onClose}
              disabled={loading}
              className="px-4 py-2 text-sm font-medium text-gray-700 dark:text-gray-300 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md hover:bg-gray-50 dark:hover:bg-gray-600 disabled:opacity-50"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={loading}
              className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-md hover:bg-blue-700 disabled:opacity-50"
            >
              {loading ? 'Creating...' : 'Create Budget'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

// BOQ Import Modal Component
interface BOQImportModalProps {
  open: boolean;
  onClose: () => void;
  onComplete: () => void;
  projectId: string;
}

function BOQImportModal({ open, onClose, onComplete, projectId }: BOQImportModalProps) {
  const [file, setFile] = useState<File | null>(null);
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState<string>('');
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<BOQImportResult | null>(null);
  const [options, setOptions] = useState({
    createBudgetItems: true,
    createMaterials: true,
  });

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      // Validate file type
      const validTypes = ['.xlsx', '.xls', '.csv'];
      const ext = selectedFile.name.toLowerCase().slice(selectedFile.name.lastIndexOf('.'));
      if (!validTypes.includes(ext)) {
        setError('Please select an Excel file (.xlsx, .xls) or CSV file');
        return;
      }
      setFile(selectedFile);
      setError(null);
      setResult(null);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const droppedFile = e.dataTransfer.files[0];
    if (droppedFile) {
      const ext = droppedFile.name.toLowerCase().slice(droppedFile.name.lastIndexOf('.'));
      if (!['.xlsx', '.xls', '.csv'].includes(ext)) {
        setError('Please select an Excel file (.xlsx, .xls) or CSV file');
        return;
      }
      setFile(droppedFile);
      setError(null);
      setResult(null);
    }
  };

  const handleImport = async () => {
    if (!file) return;

    setLoading(true);
    setProgress('Uploading file...');
    setError(null);

    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('projectId', projectId);
      formData.append('createBudgetItems', String(options.createBudgetItems));
      formData.append('createMaterials', String(options.createMaterials));

      const response = await fetch('/api/procurement/boq/import-enhanced', {
        method: 'POST',
        body: formData,
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error?.message || 'Import failed');
      }

      setResult(data.data);
      setProgress('');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Import failed');
      setProgress('');
    } finally {
      setLoading(false);
    }
  };

  const handleClose = () => {
    if (result) {
      onComplete();
    } else {
      onClose();
    }
  };

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/50" onClick={handleClose} />
      <div className="relative bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-2xl mx-4 max-h-[90vh] overflow-y-auto" role="dialog" aria-modal="true">
        <div className="p-4 border-b border-gray-200 dark:border-gray-700 flex items-center justify-between">
          <div>
            <h2 className="text-lg font-semibold text-gray-900 dark:text-white">Import BOQ</h2>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              Upload an Excel file to import materials and budget items
            </p>
          </div>
          <button
            onClick={handleClose}
            className="p-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 rounded-lg"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        <div className="p-4 space-y-4">
          {/* Result Display */}
          {result && (
            <div className="p-4 bg-green-50 dark:bg-green-900/30 border border-green-200 dark:border-green-800 rounded-lg">
              <div className="flex items-center gap-2 mb-3">
                <CheckCircle className="h-5 w-5 text-green-500" />
                <span className="font-medium text-green-700 dark:text-green-400">Import Complete!</span>
              </div>
              <div className="grid grid-cols-2 gap-3 text-sm">
                <div className="text-gray-700 dark:text-gray-300">
                  <span className="font-medium">Items Processed:</span> {result.itemsProcessed}
                </div>
                <div className="text-gray-700 dark:text-gray-300">
                  <span className="font-medium">Materials Matched:</span> {result.materialsMatched}
                </div>
                <div className="text-gray-700 dark:text-gray-300">
                  <span className="font-medium">Materials Created:</span> {result.materialsCreated}
                </div>
                <div className="text-gray-700 dark:text-gray-300">
                  <span className="font-medium">Budget Items Created:</span> {result.budgetItemsCreated}
                </div>
                <div className="col-span-2 text-gray-700 dark:text-gray-300">
                  <span className="font-medium">Total Budget Amount:</span>{' '}
                  {new Intl.NumberFormat('en-ZA', {
                    style: 'currency',
                    currency: 'ZAR',
                    minimumFractionDigits: 0,
                  }).format(result.totalBudgetAmount)}
                </div>
              </div>

              {result.categoryBreakdown && result.categoryBreakdown.length > 0 && (
                <div className="mt-3 pt-3 border-t border-green-200 dark:border-green-700">
                  <p className="text-xs font-medium text-gray-600 dark:text-gray-400 mb-2">By Category:</p>
                  <div className="grid grid-cols-2 gap-1 text-xs">
                    {result.categoryBreakdown.slice(0, 6).map((cat) => (
                      <div key={cat.code} className="flex justify-between text-gray-600 dark:text-gray-400">
                        <span>{cat.name}</span>
                        <span className="text-gray-800 dark:text-gray-300">
                          R{cat.totalAmount.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}
