          )}

          {/* File Upload Area */}
          {!result && (
            <>
              <div
                onDrop={handleDrop}
                onDragOver={(e) => e.preventDefault()}
                className={`border-2 border-dashed rounded-lg p-8 text-center transition-colors ${
                  file
                    ? 'border-green-300 dark:border-green-700 bg-green-50 dark:bg-green-900/20'
