  variancePercent: number;

  // Settings
  status: BudgetStatus;
  enforceBudget: boolean;
  allowOverride: boolean;
  alertThresholdWarning: number;
  alertThresholdCritical: number;

  // Currency
  currency: string;

  // Approval
  approvedBy?: string;
  approvedAt?: string;

  // Audit
  createdBy: string;
  createdAt: string;
  updatedAt: string;
}

/**
 * Budget Category - Category breakdown within a budget
 */
export interface BudgetCategory {
  id: string;
  projectBudgetId: string;
  categoryCode: string;
  categoryName: string;

  // Amounts
  allocatedAmount: number;
  committedAmount: number;
  actualAmount: number;
  availableAmount: number;

  // Flags
  isCustom: boolean;

  // Display order
  sortOrder?: number;

  // Audit
  createdBy?: string;
  createdAt: string;
  updatedAt: string;
}

/**
 * Budget Transaction - Financial ledger entry for audit trail
 */
export interface BudgetTransaction {
  id: string;
  projectBudgetId: string;
  categoryId?: string;

  // Transaction details
  transactionType: TransactionType;
  sourceType?: string;
  sourceId?: string;
  sourceNumber?: string;

  // Amounts
  amount: number;
  taxAmount?: number;

  // Description
  description?: string;

  // Audit
  createdBy: string;
  createdAt: string;
}

/**
 * Budget Alert - Threshold notification
 */
export interface BudgetAlert {
  id: string;
  projectBudgetId: string;
  alertType: AlertType;
  severity: AlertSeverity;

  // Threshold details
  thresholdPercent?: number;
  currentPercent?: number;
  amountInvolved?: number;

  // Display
  title: string;
  message?: string;

  // Status
  status: AlertStatus;
  acknowledgedBy?: string;
  acknowledgedAt?: string;
  resolvedBy?: string;
  resolvedAt?: string;

  // Audit
  createdAt: string;
}

/**
 * Budget Adjustment - Manual adjustment history for audit
 */
export interface BudgetAdjustment {
  id: string;
  projectBudgetId: string;
  adjustmentType: AdjustmentType;

  // Amounts
  previousAmount: number;
  newAmount: number;
  difference: number;

  // Required reason
  reason: string;

  // Approval
  approvedBy?: string;

  // Audit
  createdBy: string;
  createdAt: string;
}

// ============================================================================
// API Request/Response Types
// ============================================================================

/**
 * Result from budget availability check
 */
export interface BudgetCheckResult {
  allowed: boolean;
  reason?: 'ok' | 'over_budget' | 'category_over_budget' | 'no_budget';
  available: number;
  requested: number;
  shortfall?: number;
  allowOverride: boolean;
  utilizationBefore: number;
  utilizationAfter: number;
  warning: boolean;
  warningMessage?: string;
}

/**
 * Result from category allocation validation
 */
export interface CategoryAllocationResult {
  valid: boolean;
  totalAllocated: number;
  totalBudget: number;
  difference: number;
  over: boolean;
}

/**
 * Result from alert trigger check
 */
export interface AlertTriggerResult {
  trigger: boolean;
  type?: 'warning' | 'critical';
  reason?: 'alert_exists' | 'below_threshold';
}

/**
 * Request to create a new budget
 */
export interface CreateBudgetRequest {
  sourceType: BudgetSourceType;
  totalBudget?: number;
  boqId?: string;
  enforceBudget?: boolean;
  allowOverride?: boolean;
  alertThresholdWarning?: number;
  alertThresholdCritical?: number;
}

/**
 * Request to adjust a budget
 */
export interface AdjustBudgetRequest {
  adjustmentType: AdjustmentType;
  amount: number;
  reason: string;
}

/**
 * Request to check budget availability
 */
export interface CheckBudgetRequest {
  projectId: string;
  amount: number;
  categoryId?: string;
}

/**
 * Budget summary for dashboard widget
 */
export interface BudgetSummary {
  projectId: string;
  totalBudget: number;
  committedAmount: number;
  actualAmount: number;
  availableBudget: number;
  utilizationPercent: number;
  health: BudgetHealth;
  status: BudgetStatus;
  activeAlerts: number;
}

// ============================================================================
// Default Budget Categories (seeded)
// ============================================================================

export const DEFAULT_BUDGET_CATEGORIES = [
  { code: 'MATERIALS', name: 'Materials & Consumables', sortOrder: 1 },
  { code: 'EQUIPMENT', name: 'Equipment & Tools', sortOrder: 2 },
  { code: 'LABOR', name: 'Labor Costs', sortOrder: 3 },
  { code: 'SUBCONTRACT', name: 'Subcontractor Work', sortOrder: 4 },
  { code: 'TRANSPORT', name: 'Transport & Logistics', sortOrder: 5 },
  { code: 'OVERHEAD', name: 'Overhead & Admin', sortOrder: 6 },
  { code: 'CONTINGENCY', name: 'Contingency Reserve', sortOrder: 7 },
] as const;

// Alias for backward compatibility
export const DEFAULT_CATEGORIES = DEFAULT_BUDGET_CATEGORIES;

export type DefaultCategoryCode = (typeof DEFAULT_BUDGET_CATEGORIES)[number]['code'];

// ============= BOQ (Bill of Quantities) Types =============
// Updated to match Drizzle database schema

// BOQ Status enumeration matching database schema
export enum BOQStatus {
  DRAFT = 'draft',
  MAPPING_REVIEW = 'mapping_review',
  APPROVED = 'approved',
  ARCHIVED = 'archived',
  SUPERSEDED = 'superseded'
}

export type BOQStatusType = 'draft' | 'mapping_review' | 'approved' | 'archived' | 'superseded';

// Mapping Status enumeration
export enum MappingStatus {
  PENDING = 'pending',
  IN_PROGRESS = 'in_progress',
  COMPLETED = 'completed',
  FAILED = 'failed'
}

export type MappingStatusType = 'pending' | 'in_progress' | 'completed' | 'failed';

// BOQ Item Mapping Status
export enum BOQItemMappingStatus {
  PENDING = 'pending',
  MAPPED = 'mapped',
  MANUAL = 'manual',
  EXCEPTION = 'exception'
}

export type BOQItemMappingStatusType = 'pending' | 'mapped' | 'manual' | 'exception';

// BOQ Item Procurement Status
export enum ProcurementStatus {
  PENDING = 'pending',
  RFQ_CREATED = 'rfq_created',
  QUOTED = 'quoted',
  AWARDED = 'awarded',
  ORDERED = 'ordered'
}

export type ProcurementStatusType = 'pending' | 'rfq_created' | 'quoted' | 'awarded' | 'ordered';

// Main BOQ interface matching database schema exactly
export interface BOQ {
  id: string;
  projectId: string; // Firebase project ID

  // BOQ Details
  name: string; // Required name field
  version: string;
  title?: string;
  description?: string;

  // Status and Workflow
  status: BOQStatusType;
  mappingStatus?: MappingStatusType;
  mappingConfidence?: number; // 0-100

  // Upload Information
  uploadedBy: string;
  uploadedAt: Date;
  fileName?: string;
  fileUrl?: string;
  fileSize?: number; // bytes

  // Approval Workflow
  approvedBy?: string;
  approvedAt?: Date;
  rejectedBy?: string;
  rejectedAt?: Date;
  rejectionReason?: string;

  // Metadata
  itemCount: number;
  mappedItems: number;
  unmappedItems: number;
  exceptionsCount: number;

  // Totals
  totalEstimatedValue?: number;
  totalValue?: number; // Add this for compatibility
  currency: string; // Default 'ZAR'

  // Joined fields (optional, populated by list queries)
  projectName?: string;

  // Timestamps
  createdAt: Date;
  updatedAt: Date;
}

// BOQ Item interface matching database schema
export interface BOQItem {
  id: string;
  boqId: string;
  projectId: string; // Denormalized for performance

  // Line Item Details
  lineNumber: number;
  itemCode?: string;
  description: string;
  category?: string;
  subcategory?: string;

  // Quantities and Units
  quantity: number;
  uom: string; // unit of measure
  unitPrice?: number;
  totalPrice?: number;

  // Project Structure
  phase?: string;
  task?: string;
  site?: string;
  location?: string;

  // Catalog Mapping
  catalogItemId?: string;
  catalogItemCode?: string;
  catalogItemName?: string;
  mappingConfidence?: number; // 0-100
  mappingStatus: BOQItemMappingStatusType;

  // Technical Specifications
  specifications?: Record<string, any>;
  technicalNotes?: string;
  alternativeItems?: any[]; // Array of alternative catalog items

  // Procurement Status
  procurementStatus: ProcurementStatusType;

  // Timestamps
  createdAt: Date;
  updatedAt: Date;
}

// BOQ Exception interface for mapping issues
export interface BOQException {
  id: string;
  boqId: string;
  boqItemId: string;
  projectId: string;

  // Exception Details
  exceptionType: 'no_match' | 'multiple_matches' | 'data_issue' | 'manual_review';
  severity: 'low' | 'medium' | 'high' | 'critical';

  // Issue Description
  issueDescription: string;
  suggestedAction?: string;
  systemSuggestions?: any[]; // Array of suggested mappings

  // Resolution
  status: 'open' | 'in_review' | 'resolved' | 'ignored';
  resolvedBy?: string;
  resolvedAt?: Date;
  resolutionNotes?: string;
  resolutionAction?: 'manual_mapping' | 'catalog_update' | 'item_split' | 'item_ignore';

  // Assignment
  assignedTo?: string;
  assignedAt?: Date;
  priority: 'low' | 'medium' | 'high' | 'urgent';

  // Timestamps
  createdAt: Date;
  updatedAt: Date;
}

// Alternative catalog item suggestion
export interface AlternativeItem {
  catalogItemId: string;
  catalogItemCode: string;
  catalogItemName: string;
  matchingScore: number; // 0-100
  priceVariance?: number;
  specifications?: Record<string, any>;
}

// Mapping suggestion for automated catalog matching
export interface MappingSuggestion {
  catalogItemId: string;
  catalogItemCode: string;
  catalogItemName: string;
  confidence: number; // 0-100
  matchingCriteria: {
    descriptionMatch?: number;
    codeMatch?: number;
    specificationMatch?: number;
    categoryMatch?: number;
  };
  priceEstimate?: number;
  leadTimeEstimate?: number;
}

// BOQ Import data structure (for Excel/CSV uploads)
export interface BOQImportData {
  fileName: string;
  fileSize: number;
  projectId: string;
  version: string;
  title?: string;
  description?: string;
  uploadedBy: string;
  rows: BOQImportRow[];
}

export interface BOQImportRow {
  lineNumber: number;
  itemCode?: string;
  description: string;
  category?: string;
  subcategory?: string;
  quantity: number;
  uom: string;
  unitPrice?: number;
  totalPrice?: number;
  phase?: string;
  task?: string;
  site?: string;
  location?: string;
  specifications?: string;
  technicalNotes?: string;
}

// Form data for creating/updating BOQ
export interface BOQFormData {
  version: string;
  title?: string;
  description?: string;
  projectId: string;
  currency?: string;
}

// BOQ with populated items (for display)
export interface BOQWithItems extends BOQ {
  items: BOQItem[];
  exceptions: BOQException[];
}

// BOQ statistics for dashboard
export interface BOQStats {
  totalBOQs: number;
  activeBOQs: number;
  approvedBOQs: number;
  pendingApproval: number;
  totalItems: number;
  mappedItems: number;
  unmappedItems: number;
  exceptionsCount: number;
  totalValue: number;
  averageValue: number;
}

// ============= BOQ Column Detection Types =============

/** Target fields that can be mapped from BOQ columns */
export type BOQTargetField =
  | 'itemNo'
  | 'uom'
  | 'itemCategory'
  | 'description'
  | 'quantity'
  | 'itemCode'
  | 'itemRate'
  | 'photonicsRef'
  | 'supplier'
  | 'leadTime'
  | 'totalCost';

/** A single column mapping: source header → target field */
export interface ColumnMapping {
  sourceIndex: number;
  sourceHeader: string;
  targetField: BOQTargetField | null;
  confidence: number; // 0-1
  detectionMethod: 'keyword' | 'pattern' | 'template' | 'manual';
}

/** Result from column detection */
export interface ColumnDetectionResult {
  mapping: ColumnMapping[];
  overallConfidence: number;
  sheetName: string;
  headerRow: number;
  headers: string[];
  sampleRows: unknown[][];
  templateMatch?: {
    id: string;
    name: string;
    supplierName?: string;
  };
}

/** Saved column mapping template */
export interface BOQColumnTemplate {
  id: string;
  name: string;
  supplierName?: string;
  headers: string[];
  columnMapping: Record<string, BOQTargetField>;
  sheetName?: string;
  headerRow: number;
  skipRows: number[];
  usageCount: number;
  lastUsedAt?: string;
  createdBy?: string;
  createdAt: string;
  updatedAt: string;
}

/** Options for import with dynamic mapping */
export interface MappedImportOptions {
  projectId: string;
  boqId?: string;
  userId?: string;
  createBudgetItems?: boolean;
  createMaterials?: boolean;
  dryRun?: boolean;
  columnMapping: ColumnMapping[];
  sheetName: string;
  headerRow: number;
  saveAsTemplate?: {
    name: string;
    supplierName?: string;
  };
}

/** Stock item match result */
export interface StockItemMatch {
  stockItemId: string;
  itemCode: string;
  name: string;
  category: string;
  qtyAvailable: number;
  matchType: 'exact_code' | 'fuzzy_name';
  confidence: number;
}

// Type exports that match Drizzle inferred types
export type { BOQ as DrizzleBOQ, NewBOQ as NewDrizzleBOQ } from '../../lib/neon/schema';
export type { BOQItem as DrizzleBOQItem, NewBOQItem as NewDrizzleBOQItem } from '../../lib/neon/schema';
export type { BOQException as DrizzleBOQException, NewBOQException as NewDrizzleBOQException } from '../../lib/neon/schema';

/**
 * Budget Overview Card Component
 * PRD-057: Project Budget Tracking System
 *
 * Displays summary budget information including total, committed, and available amounts
 */

import React from 'react';
import { AlertTriangle, CheckCircle2, XCircle } from 'lucide-react';
import type { BudgetHealth, BudgetStatus } from '@/types/budget';

interface BudgetOverviewCardProps {
  totalBudget: number;
  committedAmount: number;
  actualAmount: number;
  availableBudget: number;
  utilizationPercent: number;
  health: BudgetHealth;
  status: BudgetStatus;
  currency?: string;
  sourceType?: 'manual' | 'boq' | 'hybrid';
  onSyncBoq?: () => void;
  onAdjust?: () => void;
  canAdjust?: boolean;
}

const formatCurrency = (amount: number, currency = 'ZAR'): string => {
  return new Intl.NumberFormat('en-ZA', {
    style: 'currency',
    currency,
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(amount);
};

const getHealthIcon = (health: BudgetHealth) => {
  switch (health) {
    case 'healthy':
      return <CheckCircle2 className="h-5 w-5 text-green-500" />;
    case 'warning':
      return <AlertTriangle className="h-5 w-5 text-yellow-500" />;
    case 'critical':
      return <XCircle className="h-5 w-5 text-red-500" />;
    default:
      return null;
  }
};

const getHealthColor = (health: BudgetHealth): string => {
  switch (health) {
    case 'healthy':
      return 'bg-green-500';
    case 'warning':
      return 'bg-yellow-500';
    case 'critical':
      return 'bg-red-500';
    default:
      return 'bg-gray-500';
  }
};

const getStatusBadgeClass = (status: BudgetStatus): string => {
  switch (status) {
    case 'approved':
      return 'bg-green-100 text-green-800';
    case 'locked':
      return 'bg-secondary text-foreground';
    case 'closed':
      return 'bg-red-100 text-red-800';
    default:
      return 'bg-blue-100 text-blue-800';
  }
};

export function BudgetOverviewCard({
  totalBudget,
  committedAmount,
  actualAmount,
  availableBudget,
  utilizationPercent,
  health,
  status,
  currency = 'ZAR',
  sourceType = 'manual',
  onSyncBoq,
  onAdjust,
  canAdjust = false,
}: BudgetOverviewCardProps) {
  return (
    <div
      className="bg-card rounded-lg border border-border shadow-sm"
      data-testid="budget-overview"
    >
      <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <h3 className="text-lg font-semibold text-foreground">Budget Overview</h3>
          <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${getStatusBadgeClass(status)}`}>
            {status}
          </span>
        </div>
        <div className="flex items-center gap-2" data-testid="budget-health">
          {getHealthIcon(health)}
          <span className="text-sm capitalize">{health}</span>
        </div>
      </div>

      <div className="p-4 space-y-6">
        {/* Total Budget */}
        <div className="space-y-1">
          <div className="flex items-center justify-between">
            <span className="text-sm text-muted-foreground">Total Budget</span>
            <span className="text-sm text-muted-foreground capitalize">
              Source: {sourceType}
            </span>
          </div>
          <p className="text-2xl font-bold text-foreground">{formatCurrency(totalBudget, currency)}</p>
        </div>

        {/* Utilization Progress */}
        <div className="space-y-2">
          <div className="flex items-center justify-between text-sm">
            <span className="text-muted-foreground">Utilization</span>
            <span className="font-medium text-foreground">{utilizationPercent.toFixed(1)}%</span>
          </div>
          <div className="w-full h-2 bg-secondary rounded-full overflow-hidden">
            <div
              className={`h-full transition-all ${getHealthColor(health)}`}
              style={{ width: `${Math.min(utilizationPercent, 100)}%` }}
              role="progressbar"
              aria-valuenow={utilizationPercent}
              aria-valuemin={0}
              aria-valuemax={100}
            />
          </div>
        </div>

        {/* Budget Breakdown */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 pt-2">
          <div className="space-y-1">
            <p className="text-xs text-muted-foreground">Committed</p>
            <p className="text-sm font-semibold text-foreground">{formatCurrency(committedAmount, currency)}</p>
          </div>
          <div className="space-y-1">
            <p className="text-xs text-muted-foreground">Actual</p>
            <p className="text-sm font-semibold text-foreground">{formatCurrency(actualAmount, currency)}</p>
          </div>
          <div className="space-y-1">
            <p className="text-xs text-muted-foreground">Available</p>
            <p className="text-sm font-semibold text-green-600 dark:text-green-400">
              {formatCurrency(availableBudget, currency)}
            </p>
          </div>
        </div>

        {/* Actions */}
        {(onSyncBoq || (canAdjust && onAdjust)) && (
          <div className="flex gap-2 pt-2">
            {onSyncBoq && sourceType !== 'manual' && (
              <button
                onClick={onSyncBoq}
                className="px-3 py-1.5 text-sm bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-md hover:bg-blue-100 dark:hover:bg-blue-900/50"
              >
                Sync from BOQ
              </button>
            )}
            {canAdjust && onAdjust && (
              <button
                onClick={onAdjust}
                className="px-3 py-1.5 text-sm bg-secondary text-muted-foreground rounded-md hover:bg-gray-100 dark:hover:bg-gray-600"
              >
                Adjust Budget
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default BudgetOverviewCard;

