    WHERE po.status NOT IN ('cancelled')
    GROUP BY p.project_name
    ORDER BY po_total DESC NULLS LAST
  \`;
  console.log('\\n=== POs WITH COMPLETED GRNs (BY PROJECT) ===');
  posWithGrn.forEach(r => {
    console.log(\`  \${(r.project_name || 'NO PROJECT').padEnd(25)} | \${String(r.po_count).padStart(3)} POs | \${String(r.grn_count).padStart(3)} GRNs | R \${Number(r.po_total||0).toLocaleString('en-ZA',{minimumFractionDigits:2}).padStart(18)} | \${r.line_items} items\`);
  });

  // Check PO statuses that have GRNs
  const poStatWithGrn = await sql\`
    SELECT po.status, COUNT(DISTINCT po.id) AS cnt
    FROM purchase_orders po
    JOIN goods_receipt_notes grn ON grn.purchase_order_id = po.id AND grn.status = 'completed'
    GROUP BY po.status ORDER BY cnt DESC
  \`;
  console.log('\\n=== PO STATUS (those with completed GRNs) ===');
  poStatWithGrn.forEach(r => console.log(\`  \${(r.status||'null').padEnd(20)} \${r.cnt}\`));
})();
"

