import { useState, useRef } from 'react';
import {
  FileText,
  Image as ImageIcon,
  File,
  Upload,
  Trash2,
  Download,
  Loader2,
  AlertCircle,
  X,
} from 'lucide-react';
import { useProcurementDocuments } from '../hooks/useProcurementDocuments';
import {
  DOCUMENT_TYPE_LABELS,
  type ProcurementDocumentType,
  type ProcurementEntityType,
} from '@/types/procurement/document.types';
import { formatDisplayDate } from '@/utils/dateFormat';

interface DocumentTypeOption {
  value: ProcurementDocumentType;
  label: string;
}

interface ProcurementDocumentPanelProps {
  entityType: ProcurementEntityType;
  entityId: string;
  allowedTypes?: DocumentTypeOption[];
  readOnly?: boolean;
}

const DEFAULT_ALLOWED_TYPES: DocumentTypeOption[] = Object.entries(DOCUMENT_TYPE_LABELS).map(
  ([value, label]) => ({ value: value as ProcurementDocumentType, label })
);

function getFileIcon(mimeType?: string) {
  if (!mimeType) return File;
  if (mimeType === 'application/pdf') return FileText;
  if (mimeType.startsWith('image/')) return ImageIcon;
  return File;
}

function formatFileSize(bytes?: number): string {
  if (!bytes) return '';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}


export function ProcurementDocumentPanel({
  entityType,
  entityId,
  allowedTypes = DEFAULT_ALLOWED_TYPES,
  readOnly = false,
}: ProcurementDocumentPanelProps) {
  const { documents, loading, error, uploadDocument, deleteDocument, uploading } =
    useProcurementDocuments(entityType, entityId);

  const [showUpload, setShowUpload] = useState(false);
  const [selectedType, setSelectedType] = useState<ProcurementDocumentType>(
    allowedTypes[0]?.value || 'other'
  );
  const [notes, setNotes] = useState('');
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) setSelectedFile(file);
  };

  const handleUpload = async () => {
    if (!selectedFile) return;

    try {
      await uploadDocument(selectedFile, selectedType, notes || undefined);
      setShowUpload(false);
      setSelectedFile(null);
      setNotes('');
      if (fileInputRef.current) fileInputRef.current.value = '';
    } catch {
      // Error is handled by the hook
    }
  };

  const handleDelete = async (docId: string, docName: string) => {
    if (!confirm(`Delete "${docName}"? This cannot be undone.`)) return;
    await deleteDocument(docId);
  };

  return (
    <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg">
      {/* Header */}
      <div className="flex items-center justify-between px-5 py-4 border-b border-[var(--ff-border-light)]">
        <div className="flex items-center gap-2">
          <FileText className="h-5 w-5 text-blue-400" />
          <h3 className="font-semibold text-[var(--ff-text-primary)]">
            Documents {documents.length > 0 && `(${documents.length})`}
          </h3>
        </div>
        {!readOnly && (
          <button
            onClick={() => setShowUpload(!showUpload)}
            className="inline-flex items-center gap-1.5 px-3 py-1.5 text-sm bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            <Upload className="h-4 w-4" />
            Upload
          </button>
        )}
      </div>

      {/* Upload Form */}
      {showUpload && (
        <div className="px-5 py-4 border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
          <div className="space-y-3">
            {/* File Input */}
            <div>
              <label className="block text-sm text-[var(--ff-text-secondary)] mb-1">File</label>
              <input
                ref={fileInputRef}
                type="file"
                accept=".pdf,.jpg,.jpeg,.png,.docx,.xlsx"
                onChange={handleFileSelect}
                className="block w-full text-sm text-[var(--ff-text-secondary)] file:mr-3 file:py-1.5 file:px-3 file:rounded-lg file:border-0 file:text-sm file:bg-blue-600 file:text-white hover:file:bg-blue-700 file:cursor-pointer"
              />
              <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">
                PDF, JPEG, PNG, DOCX, XLSX — max 20MB
              </p>
            </div>

            {/* Document Type */}
            <div>
              <label className="block text-sm text-[var(--ff-text-secondary)] mb-1">Document Type</label>
              <select
                value={selectedType}
                onChange={(e) => setSelectedType(e.target.value as ProcurementDocumentType)}
                className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm"
              >
                {allowedTypes.map((opt) => (
                  <option key={opt.value} value={opt.value}>
                    {opt.label}
                  </option>
                ))}
              </select>
            </div>

            {/* Notes */}
            <div>
              <label className="block text-sm text-[var(--ff-text-secondary)] mb-1">
                Notes <span className="text-[var(--ff-text-tertiary)]">(optional)</span>
              </label>
              <input
                type="text"
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                placeholder="e.g. Original supplier quote"
                className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm placeholder:text-[var(--ff-text-tertiary)]"
              />
            </div>

            {/* Actions */}
            <div className="flex items-center gap-2 pt-1">
              <button
                onClick={handleUpload}
                disabled={!selectedFile || uploading}
                className="inline-flex items-center gap-1.5 px-4 py-2 text-sm bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {uploading ? (
                  <>
                    <Loader2 className="h-4 w-4 animate-spin" />
                    Uploading...
                  </>
                ) : (
                  <>
                    <Upload className="h-4 w-4" />
                    Upload Document
                  </>
                )}
              </button>
              <button
                onClick={() => {
                  setShowUpload(false);
                  setSelectedFile(null);
                  setNotes('');
                }}
                className="inline-flex items-center gap-1.5 px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
              >
                <X className="h-4 w-4" />
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Error */}
      {error && (
        <div className="px-5 py-3 bg-red-500/10 border-b border-red-500/30 flex items-center gap-2">
          <AlertCircle className="h-4 w-4 text-red-400 shrink-0" />
          <p className="text-sm text-red-400">{error}</p>
        </div>
      )}

      {/* Document List */}
      <div className="divide-y divide-[var(--ff-border-light)]">
        {loading ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="h-5 w-5 animate-spin text-blue-400" />
          </div>
        ) : documents.length === 0 ? (
          <div className="text-center py-8">
            <FileText className="h-10 w-10 text-[var(--ff-text-tertiary)] mx-auto mb-2" />
            <p className="text-sm text-[var(--ff-text-secondary)]">No documents uploaded yet</p>
          </div>
        ) : (
          documents.map((doc) => {
            const Icon = getFileIcon(doc.mimeType);
            const typeLabel = DOCUMENT_TYPE_LABELS[doc.documentType] || doc.documentType;

            return (
              <div
                key={doc.id}
                className="flex items-center gap-3 px-5 py-3 hover:bg-[var(--ff-bg-hover)] transition-colors"
              >
                <div className="p-2 rounded-lg bg-blue-500/10 shrink-0">
                  <Icon className="h-5 w-5 text-blue-400" />
                </div>

                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-[var(--ff-text-primary)] truncate">
                    {doc.documentName}
                  </p>
                  <div className="flex items-center gap-2 text-xs text-[var(--ff-text-tertiary)]">
                    <span className="px-1.5 py-0.5 rounded bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-secondary)]">
                      {typeLabel}
                    </span>
                    {doc.fileSize && <span>{formatFileSize(doc.fileSize)}</span>}
                    <span>{formatDisplayDate(doc.uploadedAt)}</span>
                    {doc.uploadedByName && <span>by {doc.uploadedByName}</span>}
                  </div>
                  {doc.notes && (
                    <p className="text-xs text-[var(--ff-text-tertiary)] mt-0.5 truncate">
                      {doc.notes}
                    </p>
                  )}
                </div>

                <div className="flex items-center gap-1 shrink-0">
                  <a
                    href={doc.fileUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="p-1.5 hover:bg-[var(--ff-bg-tertiary)] rounded-lg transition-colors"
                    title="Download"
                  >
                    <Download className="h-4 w-4 text-[var(--ff-text-secondary)]" />
                  </a>
                  {!readOnly && (
                    <button
                      onClick={() => handleDelete(doc.id, doc.documentName)}
                      className="p-1.5 hover:bg-red-500/10 rounded-lg transition-colors"
                      title="Delete"
                    >
                      <Trash2 className="h-4 w-4 text-red-400" />
                    </button>
                  )}
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import type { ProcurementDocument, ProcurementDocumentType } from '@/types/procurement/document.types';
import { log } from '@/lib/logger';

interface UseProcurementDocumentsReturn {
  documents: ProcurementDocument[];
  loading: boolean;
  error: string | null;
  uploadDocument: (file: File, documentType: ProcurementDocumentType, notes?: string) => Promise<void>;
  deleteDocument: (documentId: string) => Promise<void>;
  refreshDocuments: () => Promise<void>;
  uploading: boolean;
}

export function useProcurementDocuments(
  entityType: string,
  entityId: string | undefined
): UseProcurementDocumentsReturn {
  const [documents, setDocuments] = useState<ProcurementDocument[]>([]);
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchDocuments = useCallback(async () => {
    if (!entityId) return;

    setLoading(true);
    setError(null);
    try {
      const res = await fetch(
        `/api/procurement/documents?entity_type=${entityType}&entity_id=${entityId}`
      );
      const data = await res.json();
      if (data.success) {
        setDocuments(data.data);
      } else {
        setError(data.error?.message || 'Failed to fetch documents');
      }
    } catch (err) {
      log.error('Failed to fetch procurement documents', { error: err });
      setError('Failed to load documents');
    } finally {
      setLoading(false);
    }
  }, [entityType, entityId]);

  useEffect(() => {
    fetchDocuments();
  }, [fetchDocuments]);

  const uploadDocument = useCallback(
    async (file: File, documentType: ProcurementDocumentType, notes?: string) => {
      if (!entityId) return;

      setUploading(true);
      setError(null);
      try {
        const formData = new FormData();
        formData.append('file', file);
        formData.append('entity_type', entityType);
        formData.append('entity_id', entityId);
        formData.append('document_type', documentType);
        if (notes) formData.append('notes', notes);

        const res = await fetch('/api/procurement/documents', {
          method: 'POST',
          body: formData,
        });
        const data = await res.json();

        if (data.success) {
          setDocuments((prev) => [data.data, ...prev]);
        } else {
          setError(data.error?.message || 'Failed to upload document');
          throw new Error(data.error?.message || 'Upload failed');
        }
      } catch (err) {
        const msg = err instanceof Error ? err.message : 'Upload failed';
        log.error('Failed to upload procurement document', { error: err });
        setError(msg);
        throw err;
      } finally {
        setUploading(false);
      }
    },
    [entityType, entityId]
  );

  const deleteDocument = useCallback(async (documentId: string) => {
    setError(null);
    try {
      const res = await fetch(`/api/procurement/documents?id=${documentId}`, {
        method: 'DELETE',
      });
      const data = await res.json();

      if (data.success) {
        setDocuments((prev) => prev.filter((d) => d.id !== documentId));
      } else {
        setError(data.error?.message || 'Failed to delete document');
      }
    } catch (err) {
      log.error('Failed to delete procurement document', { error: err });
      setError('Failed to delete document');
    }
  }, []);

  return {
    documents,
    loading,
    error,
    uploadDocument,
    deleteDocument,
    refreshDocuments: fetchDocuments,
    uploading,
  };
}

/**
 * Procurement Documents API
 * GET  /api/procurement/documents?entity_type=...&entity_id=...  — List documents
 * POST /api/procurement/documents  (multipart form-data)          — Upload document
 * DELETE /api/procurement/documents?id=...                        — Soft-delete document
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import formidable from 'formidable';
import fs from 'fs';
import { vfStorage } from '@/services/vfStorageAdapter';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import type { ProcurementDocument, ProcurementDocumentType, ProcurementEntityType } from '@/types/procurement/document.types';

const sql = neon(process.env.DATABASE_URL!);

export const config = {
  api: {
    bodyParser: false,
  },
};

const VALID_ENTITY_TYPES: ProcurementEntityType[] = [
  'purchase_order',
  'goods_receipt_note',
  'vendor_invoice',
  'rfq_response',
  'supplier_quote',
];

const VALID_DOCUMENT_TYPES: ProcurementDocumentType[] = [
  'quote_pdf',
  'invoice',
  'delivery_note',
  'grv',
  'receipt',
  'contract',
  'image',
  'other',
];

const ALLOWED_MIME_TYPES = [
  'application/pdf',
  'image/jpeg',
  'image/png',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
];

const MAX_FILE_SIZE = 20 * 1024 * 1024; // 20MB

/** Magic byte validation */
function validateMagicBytes(buffer: Buffer): boolean {
  if (buffer.length < 4) return false;
  const hex = buffer.subarray(0, 8).toString('hex').toUpperCase();
  if (hex.startsWith('FFD8FF')) return true;   // JPEG
  if (hex.startsWith('89504E47')) return true;  // PNG
  if (hex.startsWith('25504446')) return true;  // PDF
  if (hex.startsWith('504B0304')) return true;  // ZIP (docx/xlsx)
  return false;
}

/** Parse multipart form data */
function parseForm(req: NextApiRequest): Promise<{ fields: formidable.Fields; files: formidable.Files }> {
  return new Promise((resolve, reject) => {
    const form = formidable({
      maxFileSize: MAX_FILE_SIZE,
      keepExtensions: true,
    });
    form.parse(req, (err, fields, files) => {
      if (err) reject(err);
      else resolve({ fields, files });
    });
  });
}

/** Map DB row to ProcurementDocument */
function mapRow(row: Record<string, unknown>): ProcurementDocument {
  return {
    id: row.id as string,
    entityType: row.entity_type as string,
    entityId: row.entity_id as string,
    documentType: row.document_type as ProcurementDocumentType,
    documentName: row.document_name as string,
    fileUrl: row.file_url as string,
    filePath: (row.file_path as string) || undefined,
    fileSize: (row.file_size as number) || undefined,
    mimeType: (row.mime_type as string) || undefined,
    uploadedBy: row.uploaded_by as string,
    uploadedByName: (row.uploaded_by_name as string) || undefined,
    uploadedAt: new Date(row.uploaded_at as string).toISOString(),
    notes: (row.notes as string) || undefined,
    isActive: row.is_active as boolean,
  };
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const user = (req as NextApiRequest & { user: { id: string; name: string; email: string } }).user;

  if (req.method === 'GET') {
    return handleGet(req, res);
  }
  if (req.method === 'POST') {
    return handlePost(req, res, user);
  }
  if (req.method === 'DELETE') {
    return handleDelete(req, res);
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'DELETE']);
}

/** GET — List documents for an entity */
async function handleGet(req: NextApiRequest, res: NextApiResponse) {
  const entityType = req.query.entity_type as string;
  const entityId = req.query.entity_id as string;

  if (!entityType || !entityId) {
    return apiResponse.badRequest(res, 'Missing required query params: entity_type, entity_id');
  }

  if (!VALID_ENTITY_TYPES.includes(entityType as ProcurementEntityType)) {
    return apiResponse.badRequest(res, `Invalid entity_type. Allowed: ${VALID_ENTITY_TYPES.join(', ')}`);
  }

  const rows = await sql`
    SELECT * FROM procurement_documents
    WHERE entity_type = ${entityType}
      AND entity_id = ${entityId}::uuid
      AND is_active = true
    ORDER BY uploaded_at DESC
  `;

  return apiResponse.success(res, rows.map(r => mapRow(r as Record<string, unknown>)));
}

/** POST — Upload a document */
async function handlePost(
  req: NextApiRequest,
  res: NextApiResponse,
  user: { id: string; name: string; email: string }
) {
  let tempFilePath: string | null = null;

  try {
    const { fields, files } = await parseForm(req);

    const entityType = (Array.isArray(fields.entity_type) ? fields.entity_type[0] : fields.entity_type) as string;
    const entityId = (Array.isArray(fields.entity_id) ? fields.entity_id[0] : fields.entity_id) as string;
    const documentType = ((Array.isArray(fields.document_type) ? fields.document_type[0] : fields.document_type) || 'other') as string;
    const notes = (Array.isArray(fields.notes) ? fields.notes[0] : fields.notes) as string | undefined;

    if (!entityType || !entityId) {
      return apiResponse.badRequest(res, 'Missing required fields: entity_type, entity_id');
    }

    if (!VALID_ENTITY_TYPES.includes(entityType as ProcurementEntityType)) {
      return apiResponse.badRequest(res, `Invalid entity_type. Allowed: ${VALID_ENTITY_TYPES.join(', ')}`);
    }

    if (!VALID_DOCUMENT_TYPES.includes(documentType as ProcurementDocumentType)) {
      return apiResponse.badRequest(res, `Invalid document_type. Allowed: ${VALID_DOCUMENT_TYPES.join(', ')}`);
    }

    const fileField = files.file;
    const file = Array.isArray(fileField) ? fileField[0] : fileField;

    if (!file) {
      return apiResponse.badRequest(res, 'No file uploaded');
    }

    tempFilePath = file.filepath;

    if (!ALLOWED_MIME_TYPES.includes(file.mimetype || '')) {
      return apiResponse.badRequest(res, `File type not allowed: ${file.mimetype}. Allowed: PDF, JPEG, PNG, DOCX, XLSX`);
    }

    if (file.size > MAX_FILE_SIZE) {
      return apiResponse.badRequest(res, 'File too large. Maximum size: 20MB');
    }

    const buffer = await fs.promises.readFile(file.filepath);

    if (!validateMagicBytes(buffer)) {
      return apiResponse.badRequest(res, 'File content does not match declared type');
    }

    // Upload to VF Storage: procurement/{entity_type}/{entityId}_{filename}
    // VF Storage supports 2-level paths (/upload/:type/:category), so entityId goes in filename
    const fileName = file.originalFilename || `document_${Date.now()}`;
    const storageName = `${entityId}_${fileName}`;
    const result = await vfStorage.uploadFile(
      buffer,
      'procurement',
      entityType,
      storageName
    );

    // Insert DB record
    const [row] = await sql`
      INSERT INTO procurement_documents (
        entity_type, entity_id, document_type, document_name,
        file_url, file_path, file_size, mime_type,
        uploaded_by, uploaded_by_name, notes
      ) VALUES (
        ${entityType}, ${entityId}::uuid, ${documentType}, ${fileName},
        ${result.url}, ${result.path}, ${file.size}, ${file.mimetype || ''},
        ${user.email}, ${user.name}, ${notes || null}
      )
      RETURNING *
    `;

    log.info('Procurement document uploaded', {
      data: { entityType, entityId, documentType, fileName },
    }, 'procurement-docs');

    return apiResponse.created(res, mapRow(row as Record<string, unknown>));
  } catch (error) {
    const errMsg = error instanceof Error ? error.message : String(error);
    log.error('Procurement document upload error', { error }, 'procurement-docs');
    return apiResponse.internalError(res, error, `Failed to upload document: ${errMsg}`);
  } finally {
    if (tempFilePath) {
      await fs.promises.unlink(tempFilePath).catch((e) => log.debug('Temp file cleanup failed', { error: e instanceof Error ? e.message : 'unknown' }, 'procurement'));
    }
  }
}

/** DELETE — Soft-delete a document */
async function handleDelete(req: NextApiRequest, res: NextApiResponse) {
  const id = req.query.id as string;

  if (!id) {
    return apiResponse.badRequest(res, 'Missing required query param: id');
  }

  const [row] = await sql`
    UPDATE procurement_documents
    SET is_active = false
    WHERE id = ${id}::uuid AND is_active = true
    RETURNING id
  `;

  if (!row) {
    return apiResponse.notFound(res, 'Document', id);
  }

  log.info('Procurement document soft-deleted', { data: { id } }, 'procurement-docs');

  return apiResponse.success(res, { id: row.id, deleted: true });
}

export default withAuth(handler);

/**
 * Procurement & Accounting Document Types
