import { useState, useRef } from 'react';
import {
  FileText,
  Image as ImageIcon,
  File,
  Upload,
  Trash2,
  Download,
  Loader2,
  AlertCircle,
  X,
} from 'lucide-react';
import { useProcurementDocuments } from '../hooks/useProcurementDocuments';
import {
  DOCUMENT_TYPE_LABELS,
  type ProcurementDocumentType,
  type ProcurementEntityType,
} from '@/types/procurement/document.types';
import { formatDisplayDate } from '@/utils/dateFormat';

interface DocumentTypeOption {
  value: ProcurementDocumentType;
  label: string;
}

interface ProcurementDocumentPanelProps {
  entityType: ProcurementEntityType;
  entityId: string;
  allowedTypes?: DocumentTypeOption[];
  readOnly?: boolean;
}

const DEFAULT_ALLOWED_TYPES: DocumentTypeOption[] = Object.entries(DOCUMENT_TYPE_LABELS).map(
  ([value, label]) => ({ value: value as ProcurementDocumentType, label })
);

function getFileIcon(mimeType?: string) {
  if (!mimeType) return File;
  if (mimeType === 'application/pdf') return FileText;
  if (mimeType.startsWith('image/')) return ImageIcon;
  return File;
}

function formatFileSize(bytes?: number): string {
  if (!bytes) return '';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}


export function ProcurementDocumentPanel({
  entityType,
  entityId,
  allowedTypes = DEFAULT_ALLOWED_TYPES,
  readOnly = false,
}: ProcurementDocumentPanelProps) {
  const { documents, loading, error, uploadDocument, deleteDocument, uploading } =
    useProcurementDocuments(entityType, entityId);

  const [showUpload, setShowUpload] = useState(false);
  const [selectedType, setSelectedType] = useState<ProcurementDocumentType>(
    allowedTypes[0]?.value || 'other'
  );
  const [notes, setNotes] = useState('');
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) setSelectedFile(file);
  };

  const handleUpload = async () => {
    if (!selectedFile) return;

    try {
      await uploadDocument(selectedFile, selectedType, notes || undefined);
      setShowUpload(false);
      setSelectedFile(null);
      setNotes('');
      if (fileInputRef.current) fileInputRef.current.value = '';
    } catch {
      // Error is handled by the hook
    }
  };

  const handleDelete = async (docId: string, docName: string) => {
    if (!confirm(`Delete "${docName}"? This cannot be undone.`)) return;
    await deleteDocument(docId);
  };

  return (
    <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg">
      {/* Header */}
      <div className="flex items-center justify-between px-5 py-4 border-b border-[var(--ff-border-light)]">
        <div className="flex items-center gap-2">
          <FileText className="h-5 w-5 text-blue-400" />
          <h3 className="font-semibold text-[var(--ff-text-primary)]">
            Documents {documents.length > 0 && `(${documents.length})`}
          </h3>
        </div>
        {!readOnly && (
          <button
            onClick={() => setShowUpload(!showUpload)}
            className="inline-flex items-center gap-1.5 px-3 py-1.5 text-sm bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            <Upload className="h-4 w-4" />
            Upload
          </button>
        )}
      </div>

      {/* Upload Form */}
      {showUpload && (
        <div className="px-5 py-4 border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
          <div className="space-y-3">
            {/* File Input */}
            <div>
              <label className="block text-sm text-[var(--ff-text-secondary)] mb-1">File</label>
              <input
                ref={fileInputRef}
                type="file"
                accept=".pdf,.jpg,.jpeg,.png,.docx,.xlsx"
                onChange={handleFileSelect}
                className="block w-full text-sm text-[var(--ff-text-secondary)] file:mr-3 file:py-1.5 file:px-3 file:rounded-lg file:border-0 file:text-sm file:bg-blue-600 file:text-white hover:file:bg-blue-700 file:cursor-pointer"
              />
              <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">
                PDF, JPEG, PNG, DOCX, XLSX — max 20MB
              </p>
            </div>

            {/* Document Type */}
            <div>
              <label className="block text-sm text-[var(--ff-text-secondary)] mb-1">Document Type</label>
              <select
                value={selectedType}
                onChange={(e) => setSelectedType(e.target.value as ProcurementDocumentType)}
                className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm"
              >
                {allowedTypes.map((opt) => (
                  <option key={opt.value} value={opt.value}>
                    {opt.label}
                  </option>
                ))}
              </select>
            </div>

            {/* Notes */}
            <div>
              <label className="block text-sm text-[var(--ff-text-secondary)] mb-1">
                Notes <span className="text-[var(--ff-text-tertiary)]">(optional)</span>
              </label>
              <input
                type="text"
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                placeholder="e.g. Original supplier quote"
                className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm placeholder:text-[var(--ff-text-tertiary)]"
              />
            </div>

            {/* Actions */}
            <div className="flex items-center gap-2 pt-1">
              <button
                onClick={handleUpload}
                disabled={!selectedFile || uploading}
                className="inline-flex items-center gap-1.5 px-4 py-2 text-sm bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {uploading ? (
                  <>
                    <Loader2 className="h-4 w-4 animate-spin" />
                    Uploading...
                  </>
                ) : (
                  <>
                    <Upload className="h-4 w-4" />
                    Upload Document
                  </>
                )}
              </button>
              <button
                onClick={() => {
                  setShowUpload(false);
                  setSelectedFile(null);
                  setNotes('');
                }}
                className="inline-flex items-center gap-1.5 px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
              >
                <X className="h-4 w-4" />
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Error */}
      {error && (
        <div className="px-5 py-3 bg-red-500/10 border-b border-red-500/30 flex items-center gap-2">
          <AlertCircle className="h-4 w-4 text-red-400 shrink-0" />
          <p className="text-sm text-red-400">{error}</p>
        </div>
      )}

      {/* Document List */}
      <div className="divide-y divide-[var(--ff-border-light)]">
        {loading ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="h-5 w-5 animate-spin text-blue-400" />
          </div>
        ) : documents.length === 0 ? (
          <div className="text-center py-8">
            <FileText className="h-10 w-10 text-[var(--ff-text-tertiary)] mx-auto mb-2" />
            <p className="text-sm text-[var(--ff-text-secondary)]">No documents uploaded yet</p>
          </div>
        ) : (
          documents.map((doc) => {
            const Icon = getFileIcon(doc.mimeType);
            const typeLabel = DOCUMENT_TYPE_LABELS[doc.documentType] || doc.documentType;

            return (
              <div
                key={doc.id}
                className="flex items-center gap-3 px-5 py-3 hover:bg-[var(--ff-bg-hover)] transition-colors"
              >
                <div className="p-2 rounded-lg bg-blue-500/10 shrink-0">
                  <Icon className="h-5 w-5 text-blue-400" />
                </div>

                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-[var(--ff-text-primary)] truncate">
                    {doc.documentName}
                  </p>
                  <div className="flex items-center gap-2 text-xs text-[var(--ff-text-tertiary)]">
                    <span className="px-1.5 py-0.5 rounded bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-secondary)]">
                      {typeLabel}
                    </span>
                    {doc.fileSize && <span>{formatFileSize(doc.fileSize)}</span>}
                    <span>{formatDisplayDate(doc.uploadedAt)}</span>
                    {doc.uploadedByName && <span>by {doc.uploadedByName}</span>}
                  </div>
                  {doc.notes && (
                    <p className="text-xs text-[var(--ff-text-tertiary)] mt-0.5 truncate">
                      {doc.notes}
                    </p>
                  )}
                </div>

                <div className="flex items-center gap-1 shrink-0">
                  <a
                    href={doc.fileUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="p-1.5 hover:bg-[var(--ff-bg-tertiary)] rounded-lg transition-colors"
                    title="Download"
                  >
                    <Download className="h-4 w-4 text-[var(--ff-text-secondary)]" />
                  </a>
                  {!readOnly && (
                    <button
                      onClick={() => handleDelete(doc.id, doc.documentName)}
                      className="p-1.5 hover:bg-red-500/10 rounded-lg transition-colors"
                      title="Delete"
                    >
                      <Trash2 className="h-4 w-4 text-red-400" />
                    </button>
                  )}
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

/**
 * Step9Complete — Procurement Journey Summary
 * Shows full journey checklist, all document references, and action buttons.
 */

import React from 'react';
import { useRouter } from 'next/router';
import {
  CheckCircle,
  FileText,
  Package,
  Truck,
  CreditCard,
  ShieldCheck,
  ExternalLink,
  RotateCcw,
  LayoutDashboard,
} from 'lucide-react';
import type { WorkflowState } from '../useWorkflowState';

// 🟢 WORKING: full type coverage
interface Step9CompleteProps {
  state: WorkflowState;
  onReset: () => void;
}

const formatCurrency = (value: number | undefined): string => {
  if (value === undefined) return '-';
  return new Intl.NumberFormat('en-ZA', {
    style: 'currency',
    currency: 'ZAR',
    minimumFractionDigits: 0,
  }).format(value);
};

const STEP_LABELS: [number, string, React.FC<{ style?: React.CSSProperties }>][] = [
  [1, 'Create Requisition', FileText],
  [2, 'Add Line Items', FileText],
  [3, 'Set Strategy', Package],
  [4, 'Requisition Approval', ShieldCheck],
  [5, 'Create Order', Package],
  [6, 'Receive Goods', Truck],
  [7, 'Submit Invoice', CreditCard],
  [8, 'Payment Approval', ShieldCheck],
  [9, 'Complete', CheckCircle],
];

export const Step9Complete: React.FC<Step9CompleteProps> = ({ state, onReset }) => {
  const router = useRouter();

  const totalAmount = state.invoiceAmount ?? state.estimatedTotal;
  const isRfq = state.strategy === 'rfq';
  const paymentApproved = state.paymentApprovalStatus === 'approved';

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 28 }}>
      {/* Congratulations header */}
      <div style={{ textAlign: 'center', padding: '24px 0 8px' }}>
        <CheckCircle style={{ width: 56, height: 56, color: '#16a34a', margin: '0 auto 14px' }} />
        <h2 style={{ fontWeight: 800, fontSize: 22, color: 'var(--ff-text-primary)', margin: '0 0 6px' }}>
          Procurement Complete
        </h2>
        <p style={{ fontSize: 15, color: 'var(--ff-text-secondary)', margin: 0 }}>
          Your procurement journey has been successfully completed.
        </p>
      </div>

      {/* Summary badges */}
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 10, justifyContent: 'center' }}>
        <Badge label={isRfq ? 'Strategy: RFQ' : 'Strategy: Direct PO'} color={isRfq ? '#d97706' : '#2563eb'} />
        {totalAmount !== undefined && (
          <Badge label={`Total: ${formatCurrency(totalAmount)}`} color="#059669" />
        )}
        <Badge
          label={paymentApproved ? 'Payment: Approved' : 'Payment: Pending'}
          color={paymentApproved ? '#16a34a' : '#d97706'}
        />
      </div>

      {/* Document references */}
      <div>
        <p style={{ fontSize: 14, fontWeight: 700, color: 'var(--ff-text-primary)', marginBottom: 12 }}>
          Document References
        </p>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
          {state.requisitionId && (
            <DocLink
              icon={FileText}
              label="Requisition"
              ref={state.requisitionNumber}
              href={`/procurement/requisitions/${state.requisitionId}`}
              onClick={() => void router.push(`/procurement/requisitions/${state.requisitionId}`)}
            />
          )}
          {state.rfqId && (
            <DocLink
              icon={Package}
              label="RFQ"
              ref={state.rfqNumber}
              href={`/procurement/rfq/${state.rfqId}`}
              onClick={() => void router.push(`/procurement/rfq/${state.rfqId}`)}
            />
          )}
          {state.poId && (
            <DocLink
              icon={Package}
              label="Purchase Order"
              ref={state.poNumber}
              href={`/procurement/purchase-orders/${state.poId}`}
              onClick={() => void router.push(`/procurement/purchase-orders/${state.poId}`)}
            />
          )}
          {state.grnId && (
            <DocLink
              icon={Truck}
              label="Goods Receipt"
              href={`/procurement/grn/${state.grnId}`}
              onClick={() => void router.push(`/procurement/grn/${state.grnId}`)}
            />
          )}
          {state.paymentApprovalRequestId && (
            <DocLink
              icon={ShieldCheck}
              label="Payment Request"
              href="/procurement/approvals"
              onClick={() => void router.push('/procurement/approvals')}
            />
          )}
        </div>
      </div>

      {/* Journey timeline */}
      <div>
        <p style={{ fontSize: 14, fontWeight: 700, color: 'var(--ff-text-primary)', marginBottom: 12 }}>
          Journey Timeline
        </p>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 0 }}>
          {STEP_LABELS.map(([num, label, Icon], i) => {
            const isLast = i === STEP_LABELS.length - 1;
            return (
              <div key={num} style={{ display: 'flex', alignItems: 'flex-start', gap: 12 }}>
                {/* Connector column */}
                <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', width: 28, flexShrink: 0 }}>
                  <div style={{ width: 24, height: 24, borderRadius: '50%', background: 'rgba(22,163,74,0.15)', border: '2px solid #16a34a', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                    <Icon style={{ width: 12, height: 12, color: '#16a34a' }} />
                  </div>
                  {!isLast && (
                    <div style={{ width: 2, flexGrow: 1, minHeight: 20, background: 'rgba(22,163,74,0.2)', margin: '2px 0' }} />
                  )}
                </div>
                <div style={{ paddingBottom: isLast ? 0 : 12, paddingTop: 3 }}>
                  <span style={{ fontSize: 13, color: 'var(--ff-text-primary)', fontWeight: 500 }}>
                    Step {num}: {label}
                  </span>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Action buttons */}
      <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', justifyContent: 'center', paddingTop: 8 }}>
        <button
          onClick={onReset}
          style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '12px 20px', border: '1px solid var(--ff-border-light)', borderRadius: 10, cursor: 'pointer', background: 'transparent', color: 'var(--ff-text-primary)', fontSize: 14, fontWeight: 600 }}
        >
          <RotateCcw style={{ width: 16, height: 16 }} />
          Start New Procurement
        </button>
        <button
          onClick={() => void router.push('/procurement')}
          style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '12px 20px', background: '#059669', border: 'none', borderRadius: 10, cursor: 'pointer', color: '#fff', fontSize: 14, fontWeight: 600 }}
        >
          <LayoutDashboard style={{ width: 16, height: 16 }} />
          View All Procurement
        </button>
      </div>
    </div>
  );
};

// ---- Internal components ----

const Badge: React.FC<{ label: string; color: string }> = ({ label, color }) => (
  <span style={{ display: 'inline-flex', alignItems: 'center', padding: '4px 14px', borderRadius: 20, fontSize: 13, fontWeight: 600, background: `${color}18`, border: `1px solid ${color}40`, color }}>
    {label}
  </span>
);

interface DocLinkProps {
  icon: React.FC<{ style?: React.CSSProperties }>;
  label: string;
  ref?: string;
  href: string;
