  id: string;
  entityType: string;
  entityId: string;
  documentType: ProcurementDocumentType | AccountingDocumentType;
  documentName: string;
  fileUrl: string;
  filePath?: string;
  fileSize?: number;
  mimeType?: string;
  uploadedBy: string;
  uploadedByName?: string;
  uploadedAt: string;
  notes?: string;
  isActive: boolean;
}

