  try {
    const objectPath = storageKey.startsWith('/') ? storageKey.slice(1) : storageKey;
    const mcPath = `local/${MINIO_BUCKET}/${objectPath}`;
    const escapedPath = mcPath.replace(/'/g, "'\\''");
