const { neon } = require('@neondatabase/serverless');
require('dotenv').config({ path: '.env.local' });
const sql = neon(process.env.DATABASE_URL);

(async () => {
  // POs with invoices but no quote — could the filename inference be wrong?
  const misclassified = await sql\`
    SELECT pd.document_type, pd.document_name, pd.notes,
           po.external_po_number
    FROM procurement_documents pd
    JOIN purchase_orders po ON po.id = pd.entity_id
    WHERE pd.entity_type = 'purchase_order' 
      AND pd.is_active = true
      AND pd.document_type = 'other'
    LIMIT 10
  \`;
  console.log('=== Documents classified as other ===');
  misclassified.forEach(r => console.log(\`  \${r.external_po_number}: \${r.document_name} (type: \${r.document_type})\`));

  // Check delivery_note docs — some might actually be GRVs or invoices
  const dnSample = await sql\`
    SELECT pd.document_name, po.external_po_number
    FROM procurement_documents pd
    JOIN purchase_orders po ON po.id = pd.entity_id
    WHERE pd.entity_type = 'purchase_order'
      AND pd.is_active = true
      AND pd.document_type = 'delivery_note'
    ORDER BY random()
    LIMIT 15
  \`;
  console.log('\\n=== Sample delivery_note docs ===');
  dnSample.forEach(r => console.log(\`  \${r.external_po_number}: \${r.document_name}\`));

  // Check invoice docs
  const invSample = await sql\`
    SELECT pd.document_name, po.external_po_number
    FROM procurement_documents pd
    JOIN purchase_orders po ON po.id = pd.entity_id
    WHERE pd.entity_type = 'purchase_order'
      AND pd.is_active = true
      AND pd.document_type = 'invoice'
    ORDER BY random()
    LIMIT 15
  \`;
  console.log('\\n=== Sample invoice docs ===');
  invSample.forEach(r => console.log(\`  \${r.external_po_number}: \${r.document_name}\`));

  // How many POs have docs but 0/3 checklist items?
  const zeroCoverage = await sql\`
    SELECT po.external_po_number, COUNT(*) as doc_count,
      STRING_AGG(DISTINCT pd.document_type, ', ') as types
    FROM purchase_orders po
    JOIN procurement_documents pd ON pd.entity_id = po.id AND pd.entity_type = 'purchase_order' AND pd.is_active = true
    WHERE NOT EXISTS (SELECT 1 FROM procurement_documents q WHERE q.entity_id = po.id AND q.document_type = 'quote_pdf' AND q.is_active = true)
      AND NOT EXISTS (SELECT 1 FROM procurement_documents g WHERE g.entity_id = po.id AND g.document_type IN ('delivery_note', 'grv') AND g.is_active = true)
      AND NOT EXISTS (SELECT 1 FROM procurement_documents i WHERE i.entity_id = po.id AND i.document_type = 'invoice' AND i.is_active = true)
    GROUP BY po.external_po_number
    LIMIT 10
  \`;
  console.log('\\n=== POs with docs but 0/3 checklist ===');
  zeroCoverage.forEach(r => console.log(\`  \${r.external_po_number}: \${r.doc_count} docs, types: \${r.types}\`));
})();
