const { neon } = require('@neondatabase/serverless');
require('dotenv').config({ path: '.env.local' });
const sql = neon(process.env.DATABASE_URL);

(async () => {
  // Find docs that should be reclassified as purchase_order
  const poCandidate = await sql\`
    SELECT id, document_name, document_type, entity_id
    FROM procurement_documents
    WHERE is_active = true
      AND entity_type = 'purchase_order'
      AND (
        LOWER(document_name) LIKE '%purchase_order%'
        OR LOWER(document_name) LIKE '%purchase order%'
        OR (LOWER(document_name) LIKE '%_po_%' AND LOWER(document_name) NOT LIKE '%inv%')
        OR LOWER(document_name) LIKE 'po %'
        OR LOWER(document_name) LIKE 'po-%'
        OR LOWER(document_name) LIKE '%supplier_purchase%'
      )
    ORDER BY document_name
  \`;
  console.log('=== Docs that look like PO documents ===');
  poCandidate.forEach(r => console.log(\`  [\${r.document_type}] \${r.document_name} (id: \${r.id})\`));

  // Also check for quote docs misclassified
  const quoteCandidates = await sql\`
    SELECT id, document_name, document_type
    FROM procurement_documents
    WHERE is_active = true
      AND entity_type = 'purchase_order'
      AND document_type NOT IN ('quote_pdf')
      AND (
        LOWER(document_name) LIKE '%quote%'
        OR LOWER(document_name) LIKE '%quotation%'
        OR LOWER(document_name) LIKE '%rfq%'
      )
    ORDER BY document_name
    LIMIT 20
  \`;
  console.log('\\n=== Misclassified quotes ===');
  quoteCandidates.forEach(r => console.log(\`  [\${r.document_type}] \${r.document_name}\`));

  // Check delivery notes that might actually be invoices (doc name contains INV)
  const dnAsInvoice = await sql\`
    SELECT COUNT(*) as cnt
    FROM procurement_documents
    WHERE is_active = true
      AND document_type = 'delivery_note'
      AND (LOWER(document_name) LIKE '%inv%' OR LOWER(document_name) LIKE '%invoice%')
  \`;
  console.log(\`\\nDelivery notes with INV in name: \${dnAsInvoice[0].cnt}\`);
})();
