const { neon } = require('@neondatabase/serverless');
require('dotenv').config({ path: '.env.local' });
const sql = neon(process.env.DATABASE_URL);

(async () => {
  // 1. Reclassify delivery_notes with INV in name → invoice
  const r1 = await sql\`
    UPDATE procurement_documents
    SET document_type = 'invoice'
    WHERE is_active = true
      AND document_type = 'delivery_note'
      AND (LOWER(document_name) LIKE '%inv%' OR LOWER(document_name) LIKE '%invoice%')
    RETURNING id
  \`;
  console.log(\`Reclassified \${r1.length} delivery_notes → invoice\`);

  // 2. Reclassify the PO document
  const r2 = await sql\`
    UPDATE procurement_documents
    SET document_type = 'purchase_order'
    WHERE id = 'd38a048f-c50f-494d-a631-7ff8164c57ce'
    RETURNING id, document_name
  \`;
  console.log(\`Reclassified \${r2.length} other → purchase_order: \${r2[0]?.document_name}\`);

  // 3. Updated coverage report
  const coverage = await sql\`
    SELECT
      COALESCE(p.project_name, '(no project)') as project,
      COUNT(DISTINCT po.id) as total_pos,
      COUNT(DISTINCT CASE WHEN q.id IS NOT NULL THEN po.id END) as has_quote,
      COUNT(DISTINCT CASE WHEN pd.id IS NOT NULL THEN po.id END) as has_po_doc,
      COUNT(DISTINCT CASE WHEN g.id IS NOT NULL THEN po.id END) as has_grv,
      COUNT(DISTINCT CASE WHEN i.id IS NOT NULL THEN po.id END) as has_invoice,
      COUNT(DISTINCT CASE WHEN q.id IS NOT NULL AND g.id IS NOT NULL AND i.id IS NOT NULL THEN po.id END) as complete_3
    FROM purchase_orders po
    LEFT JOIN projects p ON p.id = po.project_id
    LEFT JOIN procurement_documents q ON q.entity_id = po.id AND q.entity_type = 'purchase_order' AND q.document_type = 'quote_pdf' AND q.is_active = true
    LEFT JOIN procurement_documents pd ON pd.entity_id = po.id AND pd.entity_type = 'purchase_order' AND pd.document_type = 'purchase_order' AND pd.is_active = true
    LEFT JOIN procurement_documents g ON g.entity_id = po.id AND g.entity_type = 'purchase_order' AND g.document_type IN ('delivery_note', 'grv') AND g.is_active = true
    LEFT JOIN procurement_documents i ON i.entity_id = po.id AND i.entity_type = 'purchase_order' AND i.document_type = 'invoice' AND i.is_active = true
    GROUP BY p.project_name
    ORDER BY total_pos DESC
  \`;
  console.log('\\nProject               | POs | Quote | PO Doc | GRV | Invoice | 3/3');
  console.log('-'.repeat(80));
  for (const r of coverage) {
    console.log(
      r.project.padEnd(22) + '| ' +
      String(r.total_pos).padStart(3) + ' | ' +
      String(r.has_quote).padStart(5) + ' | ' +
      String(r.has_po_doc).padStart(6) + ' | ' +
      String(r.has_grv).padStart(3) + ' | ' +
      String(r.has_invoice).padStart(7) + ' | ' +
      String(r.complete_3).padStart(3)
    );
  }

  // Overall
  const o = await sql\`
    SELECT
      COUNT(DISTINCT po.id) as total,
      COUNT(DISTINCT po.id) FILTER (WHERE q.cnt > 0 AND g.cnt > 0 AND i.cnt > 0) as three_of_four,
      COUNT(DISTINCT po.id) FILTER (WHERE q.cnt > 0 AND p2.cnt > 0 AND g.cnt > 0 AND i.cnt > 0) as four_of_four
    FROM purchase_orders po
    LEFT JOIN LATERAL (SELECT COUNT(*) as cnt FROM procurement_documents d WHERE d.entity_id = po.id AND d.document_type = 'quote_pdf' AND d.is_active = true) q ON true
    LEFT JOIN LATERAL (SELECT COUNT(*) as cnt FROM procurement_documents d WHERE d.entity_id = po.id AND d.document_type = 'purchase_order' AND d.is_active = true) p2 ON true
    LEFT JOIN LATERAL (SELECT COUNT(*) as cnt FROM procurement_documents d WHERE d.entity_id = po.id AND d.document_type IN ('delivery_note', 'grv') AND d.is_active = true) g ON true
    LEFT JOIN LATERAL (SELECT COUNT(*) as cnt FROM procurement_documents d WHERE d.entity_id = po.id AND d.document_type = 'invoice' AND d.is_active = true) i ON true
  \`;
  console.log(\`\\nOverall: \${o[0].total} POs | 3/4 complete: \${o[0].three_of_four} | 4/4 complete: \${o[0].four_of_four}\`);
})();
" 2>&1

