const { neon } = require('@neondatabase/serverless');
require('dotenv').config({ path: '.env.local' });
const sql = neon(process.env.DATABASE_URL);

(async () => {
  // Check: do many POs have BOTH delivery_note and invoice with same doc_name?
  const dupes = await sql\`
    SELECT po.external_po_number, dn.document_name as dn_name, inv.document_name as inv_name
    FROM purchase_orders po
    JOIN procurement_documents dn ON dn.entity_id = po.id AND dn.document_type = 'delivery_note' AND dn.is_active = true
    JOIN procurement_documents inv ON inv.entity_id = po.id AND inv.document_type = 'invoice' AND inv.is_active = true
