  // Reclassify Item Receipts sheet delivery_notes → invoice
  // These are from the supplier context pattern in the notes field
  const r1 = await sql\`
    UPDATE procurement_documents
    SET document_type = 'invoice'
    WHERE document_type = 'delivery_note'
      AND is_active = true
      AND entity_type = 'purchase_order'
      AND notes LIKE 'smartsheet:%'
