/**
 * QField Sync Module Type Definitions
 * Handles synchronization between QFieldCloud and FibreFlow
 */

// Sync Status Types
export type SyncStatus = 'idle' | 'syncing' | 'completed' | 'error';
export type SyncDirection = 'qfield_to_fibreflow' | 'fibreflow_to_qfield' | 'bidirectional';
export type SyncMode = 'manual' | 'automatic' | 'scheduled';

// QFieldCloud Data Types
export interface QFieldProject {
  id: string;
  name: string;
  description: string;
  owner: string;
  isPublic: boolean;
  lastModified: string;
  layers: QFieldLayer[];
  status: 'active' | 'inactive' | 'error';
}

export interface QFieldLayer {
  id: string;
  name: string;
  type: 'point' | 'line' | 'polygon';
  featureCount: number;
  fields: QFieldField[];
  lastSync?: string;
}

export interface QFieldField {
  name: string;
  type: 'string' | 'number' | 'date' | 'boolean' | 'geometry';
  alias?: string;
  required: boolean;
}

// Fiber Cable Data from QFieldCloud
export interface QFieldFiberCable {
  featureId: string;
  cableId: string;
  cableType: string;
  cableSize: number;
  fiberCount: number;
  startPole: string;
  endPole: string;
  geometry: GeoJSONLineString;
  length: number; // Calculated from geometry
  installationStatus: 'planned' | 'in_progress' | 'completed';
  installedBy?: string;
  installationDate?: string;
  splicingComplete: boolean;
  testingComplete: boolean;
  notes?: string;
  photos?: string[];
  lastModified: string;
}

// GeoJSON Types

/**
 * Bank Reconciliations API
 * GET  /api/accounting/bank-reconciliations - List reconciliation sessions
 * POST /api/accounting/bank-reconciliations - Start new reconciliation
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getReconciliations,
  getReconciliationById,
  startReconciliation,
} from '@/modules/accounting/services/bankReconciliationService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const { bank_account_id, id } = req.query;

      if (id) {
        const recon = await getReconciliationById(String(id));
        if (!recon) return apiResponse.notFound(res, 'Reconciliation', String(id));
        return apiResponse.success(res, recon);
      }

      const result = await getReconciliations(
        bank_account_id ? String(bank_account_id) : undefined
      );
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get reconciliations', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get reconciliations');
    }
  }

  if (req.method === 'POST') {
    try {
      const { bankAccountId, statementDate, statementBalance } = req.body;
      const userId = (req as unknown as { user?: { id: string } }).user?.id;
      if (!userId) return apiResponse.unauthorized(res, 'Unauthorized');

      if (!bankAccountId || !statementDate || statementBalance === undefined) {
        return apiResponse.badRequest(res, 'bankAccountId, statementDate, and statementBalance are required');
      }
      if (!userId) return apiResponse.unauthorized(res, 'Unauthorized');

      const recon = await startReconciliation(
        String(bankAccountId), String(statementDate),
        Number(statementBalance), userId
      );
      return apiResponse.created(res, recon);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to start reconciliation';
      log.error('Failed to start reconciliation', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAuth(withErrorHandler(handler));

/**
 * Credit Notes API
 * GET  /api/accounting/credit-notes - List credit notes (with filters)
 * POST /api/accounting/credit-notes - Create draft credit note
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getCreditNotes,
  getCreditNoteById,
  createCreditNote,
} from '@/modules/accounting/services/creditNoteService';
import type { CreditNoteStatus } from '@/modules/accounting/types/ar.types';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const { id, type, status, limit, offset } = req.query;
      if (id) {
        const note = await getCreditNoteById(id as string);
        if (!note) return apiResponse.notFound(res, 'Credit Note', id as string);
        return apiResponse.success(res, note);
      }
      const result = await getCreditNotes({
        type: type as 'customer' | 'supplier' | undefined,
        status: status as CreditNoteStatus | undefined,
        limit: limit ? Number(limit) : undefined,
        offset: offset ? Number(offset) : undefined,
      });
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get credit notes', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get credit notes');
    }
  }

  if (req.method === 'POST') {
    try {
      const { type, clientId, customerInvoiceId, supplierId, supplierInvoiceId,
        creditDate, reason, subtotal, taxRate, projectId } = req.body;

      if (!type || !creditDate || subtotal === undefined) {
        return apiResponse.badRequest(res, 'type, creditDate, and subtotal are required');
      }

      const userId = (req as unknown as { user?: { id: string } }).user?.id;
      if (!userId) return apiResponse.unauthorized(res, 'Unauthorized');

      const creditNote = await createCreditNote({
        type,
        clientId: clientId || undefined,
        customerInvoiceId: customerInvoiceId || undefined,
        supplierId: supplierId || undefined,
        supplierInvoiceId: supplierInvoiceId || undefined,
        creditDate,
        reason: reason || undefined,
        subtotal: Number(subtotal),
        taxRate: taxRate !== undefined ? Number(taxRate) : undefined,
        projectId: projectId || undefined,
      }, userId);

      return apiResponse.created(res, creditNote);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create credit note';
      log.error('Failed to create credit note', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAuth(withErrorHandler(handler));

/**
 * Customer Payments API
 * GET  /api/accounting/customer-payments - List payments (with filters)
 * POST /api/accounting/customer-payments - Create payment with allocations
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getCustomerPayments,
  getCustomerPaymentById,
  createCustomerPayment,
} from '@/modules/accounting/services/customerPaymentService';
import type { CustomerPaymentStatus } from '@/modules/accounting/types/ar.types';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const { id, status, client_id, limit, offset } = req.query;

      // Single payment by ID
      if (id) {
        const payment = await getCustomerPaymentById(String(id));
        if (!payment) return apiResponse.notFound(res, 'Payment', String(id));
        return apiResponse.success(res, payment);
      }

      const result = await getCustomerPayments({
        status: status as CustomerPaymentStatus | undefined,
        clientId: client_id ? String(client_id) : undefined,
        limit: limit ? Number(limit) : undefined,
        offset: offset ? Number(offset) : undefined,
      });
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get customer payments', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get customer payments');
    }
  }

  if (req.method === 'POST') {
    try {
      const { clientId, paymentDate, totalAmount, paymentMethod, bankReference,
        bankAccountId, description, projectId, allocations } = req.body;

      if (!clientId || !paymentDate || !totalAmount || !allocations || !Array.isArray(allocations)) {
        return apiResponse.badRequest(res, 'clientId, paymentDate, totalAmount, and allocations are required');
      }

      const userId = (req as unknown as { user?: { id: string } }).user?.id;
      if (!userId) return apiResponse.unauthorized(res, 'Unauthorized');

      const payment = await createCustomerPayment({
        clientId: String(clientId),
        paymentDate,
        totalAmount: Number(totalAmount),
        paymentMethod: paymentMethod || 'eft',
        bankReference: bankReference || undefined,
        bankAccountId: bankAccountId || undefined,
        description: description || undefined,
        projectId: projectId || undefined,
        allocations: allocations.map((a: { invoiceId: string; amount: number }) => ({
          invoiceId: String(a.invoiceId),
          amount: Number(a.amount),
        })),
      }, userId);

      return apiResponse.created(res, payment);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create customer payment';
      log.error('Failed to create customer payment', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAuth(withErrorHandler(handler));

/**
 * Journal Entries API
 * GET  /api/accounting/journal-entries - List entries (with filters)
 * POST /api/accounting/journal-entries - Create draft entry with lines
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getJournalEntries,
  createJournalEntry,
} from '@/modules/accounting/services/journalEntryService';
import type { GLEntryStatus, GLEntrySource } from '@/modules/accounting/types/gl.types';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const { status, source, fiscal_period_id, limit, offset } = req.query;
      const result = await getJournalEntries({
        status: status as GLEntryStatus | undefined,
        source: source as GLEntrySource | undefined,
        fiscalPeriodId: fiscal_period_id as string | undefined,
        limit: limit ? Number(limit) : undefined,
        offset: offset ? Number(offset) : undefined,
      });
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get journal entries', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get journal entries');
    }
  }

  if (req.method === 'POST') {
    try {
      const { entryDate, description, source, sourceDocumentId, fiscalPeriodId, lines } = req.body;

      if (!entryDate || !lines || !Array.isArray(lines) || lines.length === 0) {
        return apiResponse.badRequest(res, 'entryDate and lines (non-empty array) are required');
      }

      // userId from auth context or body
      const userId = (req as unknown as { user?: { id: string } }).user?.id;
      if (!userId) {
        return apiResponse.badRequest(res, 'userId is required');
      }

      const entry = await createJournalEntry({
        entryDate,
        description,
        source,
        sourceDocumentId,
        fiscalPeriodId,
        lines,
      }, userId);

      return apiResponse.success(res, entry);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create journal entry';
      log.error('Failed to create journal entry', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  res.setHeader('Allow', ['GET', 'POST']);
  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAuth(withErrorHandler(handler));

/**
 * Supplier Invoices API
 * GET  /api/accounting/supplier-invoices - List invoices (with filters)
 * POST /api/accounting/supplier-invoices - Create draft invoice
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getSupplierInvoices,
  createSupplierInvoice,
} from '@/modules/accounting/services/supplierInvoiceService';
import type { SupplierInvoiceStatus } from '@/modules/accounting/types/ap.types';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const { status, supplier_id, match_status, limit, offset } = req.query;
      const result = await getSupplierInvoices({
        status: status as SupplierInvoiceStatus | undefined,
        supplierId: supplier_id ? Number(supplier_id) : undefined,
        matchStatus: match_status as 'unmatched' | 'po_matched' | 'grn_matched' | 'fully_matched' | undefined,
        limit: limit ? Number(limit) : undefined,
        offset: offset ? Number(offset) : undefined,
      });
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get supplier invoices', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get supplier invoices');
    }
  }

  if (req.method === 'POST') {
    try {
      const { invoiceNumber, supplierId, purchaseOrderId, grnId, invoiceDate,
        dueDate, taxRate, paymentTerms, reference, projectId, costCenterId,
        notes, items } = req.body;

      if (!invoiceNumber || !supplierId || !invoiceDate || !items || !Array.isArray(items) || items.length === 0) {
        return apiResponse.badRequest(res, 'invoiceNumber, supplierId, invoiceDate, and items are required');
      }

      const userId = (req as unknown as { user?: { id: string } }).user?.id;
      if (!userId) return apiResponse.unauthorized(res, 'Unauthorized');

      const invoice = await createSupplierInvoice({
        invoiceNumber, supplierId: String(supplierId), purchaseOrderId, grnId,
        invoiceDate, dueDate, taxRate: taxRate ? Number(taxRate) : undefined,
        paymentTerms, reference, projectId, costCenterId, notes, items,
      }, userId);

      return apiResponse.created(res, invoice);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create supplier invoice';
      log.error('Failed to create supplier invoice', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAuth(withErrorHandler(handler));

/**
 * Supplier Payments API
 * GET  /api/accounting/supplier-payments - List payments
 * POST /api/accounting/supplier-payments - Create payment with allocations
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getSupplierPayments,
  getSupplierPaymentById,
  createSupplierPayment,
} from '@/modules/accounting/services/supplierPaymentService';
import type { PaymentStatus } from '@/modules/accounting/types/ap.types';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const { id, status, supplier_id, limit, offset } = req.query;

      // Single payment by ID
      if (id) {
        const payment = await getSupplierPaymentById(id as string);
        if (!payment) return apiResponse.notFound(res, 'Payment', id as string);
        return apiResponse.success(res, payment);
      }

      const result = await getSupplierPayments({
        status: status as PaymentStatus | undefined,
        supplierId: supplier_id ? Number(supplier_id) : undefined,
        limit: limit ? Number(limit) : undefined,
        offset: offset ? Number(offset) : undefined,
      });
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get supplier payments', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get supplier payments');
    }
  }

  if (req.method === 'POST') {
    try {
      const { supplierId, paymentDate, totalAmount, paymentMethod,
        bankAccountId, reference, description, allocations } = req.body;

      if (!supplierId || !paymentDate || !totalAmount || !allocations || !Array.isArray(allocations)) {
        return apiResponse.badRequest(res, 'supplierId, paymentDate, totalAmount, and allocations are required');
