const { neon } = require('@neondatabase/serverless');
require('dotenv').config({ path: '.env.local' });
const sql = neon(process.env.DATABASE_URL);

(async () => {
  // Check BOQ utilization — what's the current spend-vs-BOQ picture?
  const projects = await sql\`
    SELECT 
      p.project_name,
      b.id as boq_id,
      b.version,
      (SELECT COUNT(*) FROM boq_items WHERE boq_id = b.id) as boq_items,
      (SELECT COALESCE(SUM(unit_price * quantity), 0) FROM boq_items WHERE boq_id = b.id)::numeric as boq_value,
      (SELECT COUNT(DISTINCT po.id) FROM purchase_orders po WHERE po.project_id = p.id) as po_count,
      (SELECT COALESCE(SUM(poi.total_price), 0) FROM purchase_order_items poi 
       JOIN purchase_orders po ON po.id = poi.purchase_order_id 
       WHERE po.project_id = p.id)::numeric as total_ordered,
      (SELECT COALESCE(SUM(poi.total_price), 0) FROM purchase_order_items poi 
       JOIN purchase_orders po ON po.id = poi.purchase_order_id 
       WHERE po.project_id = p.id
       AND po.status IN ('received', 'partially_received', 'invoiced', 'paid'))::numeric as confirmed_spend
    FROM projects p
    JOIN boqs b ON b.project_id = p.id AND b.status = 'active'
    ORDER BY boq_value DESC
  \`;

  console.log('Project            | BOQ Value    | Ordered      | Confirmed    | % of BOQ');
  console.log('-'.repeat(85));
  for (const r of projects) {
    const boq = Number(r.boq_value);
    const ordered = Number(r.total_ordered);
    const confirmed = Number(r.confirmed_spend);
    const pct = boq > 0 ? ((confirmed / boq) * 100).toFixed(1) : '0.0';
    console.log(
      r.project_name.padEnd(19) + '| R' + (boq/1e6).toFixed(1).padStart(7) + 'M | R' +
      (ordered/1e6).toFixed(1).padStart(7) + 'M | R' +
      (confirmed/1e6).toFixed(1).padStart(7) + 'M | ' + pct + '%'
    );
  }
})();
" 2>&1

