const { neon } = require('@neondatabase/serverless');
require('dotenv').config({ path: '.env.local' });
const sql = neon(process.env.DATABASE_URL);

(async () => {
  const projects = await sql\`
    SELECT
      p.project_name,
      b.version as boq_version,
      (SELECT COUNT(*) FROM boq_items WHERE boq_id = b.id) as boq_line_count,
      (SELECT COALESCE(SUM(unit_price * quantity), 0) FROM boq_items WHERE boq_id = b.id)::numeric as boq_value,
      (
        SELECT COALESCE(SUM(poi.total_price), 0)
        FROM purchase_order_items poi
        JOIN purchase_orders po ON po.id = poi.purchase_order_id
        WHERE po.project_id::text = p.id::text
      )::numeric as total_ordered,
      (
        SELECT COALESCE(SUM(poi.total_price), 0)
        FROM purchase_order_items poi
        JOIN purchase_orders po ON po.id = poi.purchase_order_id
        WHERE po.project_id::text = p.id::text
          AND po.status IN ('received', 'partially_received', 'invoiced', 'paid')
      )::numeric as confirmed_spend,
      (
        SELECT COALESCE(SUM(poi.total_price), 0)
        FROM purchase_order_items poi
        JOIN purchase_orders po ON po.id = poi.purchase_order_id
        WHERE po.project_id::text = p.id::text
          AND poi.boq_item_id IS NULL
      )::numeric as adhoc_spend
    FROM projects p
    JOIN boqs b ON b.project_id::text = p.id::text AND b.status = 'active'
    ORDER BY boq_value DESC
  \`;

  console.log('Project            | BOQ Budget   | Ordered      | Confirmed    | Ad-hoc       | Remaining');
  console.log('-'.repeat(100));
  for (const r of projects) {
    const boq = Number(r.boq_value);
    const ord = Number(r.total_ordered);
    const conf = Number(r.confirmed_spend);
    const adhoc = Number(r.adhoc_spend);
    const boqSpend = ord - adhoc;
    const remaining = Math.max(0, boq - boqSpend);
    console.log(
      r.project_name.padEnd(19) +
      '| R' + (boq/1e6).toFixed(1).padStart(7) + 'M' +
      ' | R' + (ord/1e6).toFixed(1).padStart(7) + 'M' +
      ' | R' + (conf/1e6).toFixed(1).padStart(7) + 'M' +
      ' | R' + (adhoc/1e6).toFixed(1).padStart(7) + 'M' +
      ' | R' + (remaining/1e6).toFixed(1).padStart(7) + 'M'
    );
  }
})();
