/**
 * useQFieldSync Hook
 * Custom hook for managing QField sync state and operations
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import {
  QFieldSyncDashboardData,
  SyncJob,
  SyncConflict,
  SyncDirection,
} from '../types/qfield-sync.types';
import { qfieldSyncApiService } from '../services/qfieldSyncApiService';
import { log } from '@/lib/logger';

interface UseQFieldSyncReturn {
  dashboardData: QFieldSyncDashboardData | null;
  currentJob: SyncJob | null;
  syncHistory: SyncJob[];
  isLoading: boolean;
  error: string | null;
  startSync: (type: SyncJob['type'], direction: SyncDirection) => Promise<void>;
  cancelSync: () => Promise<void>;
  resolveConflict: (conflictId: string, resolution: SyncConflict['resolution']) => Promise<void>;
  refreshData: () => void;
  updateConfig: (config: any) => Promise<void>;
}

export function useQFieldSync(): UseQFieldSyncReturn {
  const [dashboardData, setDashboardData] = useState<QFieldSyncDashboardData | null>(null);
  const [currentJob, setCurrentJob] = useState<SyncJob | null>(null);
  const [syncHistory, setSyncHistory] = useState<SyncJob[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const wsRef = useRef<WebSocket | null>(null);

  // Fetch dashboard data
  const fetchDashboardData = useCallback(async () => {
    try {
      const data = await qfieldSyncApiService.getDashboardData();
      setDashboardData(data);
      setError(null);
    } catch (err) {
      log.error('useQFieldSync', { action: 'fetchDashboardData', error: err });
      setError(err instanceof Error ? err.message : 'Failed to fetch dashboard data');
    }
  }, []);

  // Fetch current job status
  const fetchCurrentJob = useCallback(async () => {
    try {
      const job = await qfieldSyncApiService.getCurrentJob();
      if (job) {
        setCurrentJob({
          ...job,
          errors: job.errors || []
        });
      } else {
        setCurrentJob(null);
      }
    } catch (err) {
      log.error('useQFieldSync', { action: 'fetchCurrentJob', error: err });
    }
  }, []);

  // Fetch sync history
  const fetchSyncHistory = useCallback(async () => {
    try {
      const response = await qfieldSyncApiService.getSyncHistory();
      setSyncHistory(response.jobs.map(job => ({
        ...job,
        errors: job.errors || []
      })));
    } catch (err) {
      log.error('useQFieldSync', { action: 'fetchSyncHistory', error: err });
    }
  }, []);

  // Refresh all data
  const refreshData = useCallback(() => {
    setIsLoading(true);
    Promise.all([
      fetchDashboardData(),
      fetchCurrentJob(),
      fetchSyncHistory(),
    ]).finally(() => {
      setIsLoading(false);
    });
  }, [fetchDashboardData, fetchCurrentJob, fetchSyncHistory]);

  // Start a sync job
  const startSync = useCallback(async (type: SyncJob['type'], direction: SyncDirection) => {
    try {
      setError(null);
      const job = await qfieldSyncApiService.startSync(type, direction);
      setCurrentJob({
        ...job,
        errors: job.errors || []
      });

      // Refresh data after starting sync
      setTimeout(() => {
        fetchCurrentJob();
        fetchSyncHistory();
      }, 1000);
    } catch (err) {
      log.error('useQFieldSync', { action: 'startSync', type, direction, error: err });
      setError(err instanceof Error ? err.message : 'Failed to start sync');
      throw err;
    }
  }, [fetchCurrentJob, fetchSyncHistory]);

  // Cancel current sync job
  const cancelSync = useCallback(async () => {
    try {
      await qfieldSyncApiService.cancelSync();
      setCurrentJob(null);
      refreshData();
    } catch (err) {
      log.error('useQFieldSync', { action: 'cancelSync', error: err });
      setError(err instanceof Error ? err.message : 'Failed to cancel sync');
      throw err;
    }
  }, [refreshData]);

  // Resolve a conflict
  const resolveConflict = useCallback(async (
    conflictId: string,
    resolution: NonNullable<SyncConflict['resolution']>
  ) => {
    try {
      await qfieldSyncApiService.resolveConflict(conflictId, resolution);

      // Update local state
      if (dashboardData) {
        const updatedConflicts = dashboardData.conflicts.map(c =>
          c.id === conflictId
            ? { ...c, resolution, resolvedAt: new Date().toISOString() }
            : c
        );
        setDashboardData({
          ...dashboardData,
          conflicts: updatedConflicts.filter(c => !c.resolution),
        });
      }
    } catch (err) {
      log.error('useQFieldSync', { action: 'resolveConflict', conflictId, resolution, error: err });
      setError(err instanceof Error ? err.message : 'Failed to resolve conflict');
      throw err;
    }
  }, [dashboardData]);

  // Update configuration
  const updateConfig = useCallback(async (config: any) => {
    try {
      await qfieldSyncApiService.updateConfig(config);
      if (dashboardData) {
        setDashboardData({
          ...dashboardData,
          config,
        });
      }
    } catch (err) {
      log.error('useQFieldSync', { action: 'updateConfig', error: err });
      setError(err instanceof Error ? err.message : 'Failed to update configuration');
      throw err;
    }
  }, [dashboardData]);

  // Set up WebSocket connection for real-time updates
  useEffect(() => {
    // Temporarily disable WebSocket until backend implementation is ready
    const ENABLE_WEBSOCKET = false;

    if (!ENABLE_WEBSOCKET) {
      log.debug('useQFieldSync', { action: 'websocketCheck', status: 'disabled', message: 'Using polling for updates' });
      return;
    }

    const connectWebSocket = () => {
      try {
        const ws = qfieldSyncApiService.connectWebSocket(
          (event) => {
            try {
              const data = JSON.parse(event.data);
              log.debug('useQFieldSync', { action: 'websocketMessage', messageType: data.type, data });

              switch (data.type) {
                case 'sync_started':
                  setCurrentJob({
                    ...data.data,
                    errors: data.data.errors || []
                  });
                  break;
                case 'sync_progress':
                  setCurrentJob({
                    ...data.data,
                    errors: data.data.errors || []
                  });
                  break;
                case 'sync_completed':
                  setCurrentJob(null);
                  fetchSyncHistory();
                  fetchDashboardData();
                  break;
                case 'sync_error':
                  setCurrentJob(null);
                  setError(data.data.message);
                  fetchSyncHistory();
                  break;
                default:
                  break;
              }
            } catch (parseError) {
              log.error('useQFieldSync', { action: 'websocketMessageParse', error: parseError });
            }
          },
          (error) => {
            log.error('useQFieldSync', { action: 'websocketError', error });
          }
        );

        if (ws) {
          wsRef.current = ws;
        }
      } catch (err) {
        log.error('useQFieldSync', { action: 'websocketConnect', error: err });
      }
    };

    // Only connect WebSocket in browser environment
    if (typeof window !== 'undefined') {
      connectWebSocket();
    }

    // Cleanup on unmount
    return () => {
      if (wsRef.current) {
        wsRef.current.close();
      }
    };
  }, [fetchDashboardData, fetchSyncHistory]);

  // Initial data load
  useEffect(() => {
    refreshData();
  }, [refreshData]);

  // Polling for current job updates
  useEffect(() => {
    if (currentJob && currentJob.status === 'syncing') {
      const interval = setInterval(fetchCurrentJob, 2000);
      return () => clearInterval(interval);
    }
  }, [currentJob, fetchCurrentJob]);

  return {
    dashboardData,
    currentJob,
    syncHistory,
    isLoading,
    error,
    startSync,
    cancelSync,
    resolveConflict,
    refreshData,
    updateConfig,
  };
}/**
 * QField Sync Module Type Definitions
 * Handles synchronization between QFieldCloud and FibreFlow
 */

// Sync Status Types
export type SyncStatus = 'idle' | 'syncing' | 'completed' | 'error';
export type SyncDirection = 'qfield_to_fibreflow' | 'fibreflow_to_qfield' | 'bidirectional';
export type SyncMode = 'manual' | 'automatic' | 'scheduled';

// QFieldCloud Data Types
export interface QFieldProject {
  id: string;
  name: string;
  description: string;
  owner: string;
  isPublic: boolean;
  lastModified: string;
  layers: QFieldLayer[];
  status: 'active' | 'inactive' | 'error';
}

export interface QFieldLayer {
  id: string;
  name: string;
  type: 'point' | 'line' | 'polygon';
  featureCount: number;
  fields: QFieldField[];
  lastSync?: string;
}

export interface QFieldField {
  name: string;
  type: 'string' | 'number' | 'date' | 'boolean' | 'geometry';
  alias?: string;
  required: boolean;
}

// Fiber Cable Data from QFieldCloud
export interface QFieldFiberCable {
  featureId: string;
  cableId: string;
  cableType: string;
  cableSize: number;
  fiberCount: number;
  startPole: string;
  endPole: string;
  geometry: GeoJSONLineString;
  length: number; // Calculated from geometry
  installationStatus: 'planned' | 'in_progress' | 'completed';
  installedBy?: string;
  installationDate?: string;
  splicingComplete: boolean;
  testingComplete: boolean;
  notes?: string;
  photos?: string[];
  lastModified: string;
}

// GeoJSON Types
export interface GeoJSONLineString {
  type: 'LineString';
  coordinates: number[][];
}

export interface GeoJSONPoint {
  type: 'Point';
  coordinates: number[];
}

// Sync Configuration
export interface QFieldSyncConfig {
  qfieldcloud: {
    url: string;
    projectId: string;
    apiKey: string;
    pollingInterval: number; // in seconds
  };
  fibreflow: {
    databaseUrl: string;
    targetTable: string;
  };
  mapping: FieldMapping[];
  syncMode: SyncMode;
  syncDirection: SyncDirection;
  autoResolveConflicts: boolean;
}

// Field Mapping Configuration
export interface FieldMapping {
  source: string; // QField field name
  target: string; // FibreFlow column name
  transform?: 'none' | 'uppercase' | 'lowercase' | 'date' | 'number' | 'boolean' | 'json';
  defaultValue?: any;
}

// Sync Job Types
export interface SyncJob {
  id: string;
  type: 'fiber_cables' | 'poles' | 'splice_closures' | 'test_points';
  status: SyncStatus;
  direction: SyncDirection;
  startedAt: string;
  completedAt?: string;
  recordsProcessed: number;
  recordsCreated: number;
  recordsUpdated: number;
  recordsFailed: number;
  errors: SyncError[];
  duration?: number; // in milliseconds
}

export interface SyncError {
  recordId: string;
  field?: string;
  message: string;
  timestamp: string;
}

// Sync Statistics
export interface SyncStats {
  lastSync: string | null;
  totalSyncs: number;
  successfulSyncs: number;
  failedSyncs: number;
  totalRecordsSynced: number;
  averageSyncDuration: number; // in milliseconds
  nextScheduledSync?: string;
}

// Conflict Resolution
export interface SyncConflict {
  id: string;
  recordId: string;
  field: string;
  qfieldValue: any;
  fibreflowValue: any;
  detectedAt: string;
  resolution?: 'use_qfield' | 'use_fibreflow' | 'merge' | 'skip';
  resolvedAt?: string;
  resolvedBy?: string;
}

// Dashboard Display Types
export interface QFieldSyncDashboardData {
  connectionStatus: {
    qfieldcloud: 'connected' | 'disconnected' | 'error';
    fibreflow: 'connected' | 'disconnected' | 'error';
  };
  projects: QFieldProject[];
  currentJob?: SyncJob;
  recentJobs: SyncJob[];
  stats: SyncStats;
  conflicts: SyncConflict[];
  config: QFieldSyncConfig;
}

// API Response Types
export interface SyncResponse {
  success: boolean;
  data?: any;
  message?: string;
  errors?: SyncError[];
}

export interface ProjectListResponse {
  success: boolean;
  projects: QFieldProject[];
  timestamp: string;
}

export interface SyncHistoryResponse {
  success: boolean;
  jobs: SyncJob[];
  totalCount: number;
  page: number;
  pageSize: number;
}

// WebSocket Event Types for Real-time Updates
export interface SyncWebSocketEvent {
  type: 'sync_started' | 'sync_progress' | 'sync_completed' | 'sync_error' | 'record_synced';
  jobId: string;
  data: any;
  timestamp: string;
}

// Transformation Functions
export interface DataTransformer {
  qfieldToFibreflow: (data: QFieldFiberCable) => any;
  fibreflowToQfield: (data: any) => QFieldFiberCable;
}

// Validation Rules
export interface ValidationRule {
  field: string;
  type: 'required' | 'min' | 'max' | 'regex' | 'custom';
  value?: any;
  message: string;
  validate?: (value: any) => boolean;
}

export interface ValidationResult {
  valid: boolean;
  errors: Array<{
    field: string;
    message: string;
  }>;
}/**
 * QField Sync API Service
 * Frontend service for communicating with QField sync endpoints
 */

import {
  QFieldProject,
  SyncJob,
  SyncStats,
  SyncConflict,
  SyncResponse,
  ProjectListResponse,
  SyncHistoryResponse,
  QFieldSyncDashboardData,
  SyncDirection,
} from '../types/qfield-sync.types';
import { log } from '@/lib/logger';

class QFieldSyncApiService {
  /**
   * Generic request handler
   */
  private async request<T>(
    endpoint: string,
    options: RequestInit = {}
  ): Promise<T> {
    const url = endpoint;

    const response = await fetch(url, {
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });

    if (!response.ok) {
      const error = await response.json().catch(() => ({
        message: `Request failed with status ${response.status}`,
      }));
      throw new Error(error.message || `HTTP ${response.status}`);
    }

    const data = await response.json();
    return data.data || data;
  }

  /**
   * Get dashboard data
   */
  async getDashboardData(): Promise<QFieldSyncDashboardData> {
    return this.request<QFieldSyncDashboardData>('/api/qfield-sync-dashboard');
  }

  /**
   * Get list of QFieldCloud projects
   */
  async getProjects(): Promise<QFieldProject[]> {
    const response = await this.request<ProjectListResponse>('/api/qfield-sync-projects');
    return response.projects;
  }

  /**
   * Get project details
   */
  async getProject(projectId: string): Promise<QFieldProject> {
    return this.request<QFieldProject>(`/api/qfield-sync-projects?id=${projectId}`);
  }

  /**
   * Start a sync job
   */
  async startSync(
    type: SyncJob['type'],
    direction: SyncDirection = 'bidirectional'
  ): Promise<SyncJob> {
    return this.request<SyncJob>('/api/qfield-sync-start', {
      method: 'POST',
      body: JSON.stringify({ type, direction }),
    });
  }

  /**
   * Get current sync job status
   */
  async getCurrentJob(): Promise<SyncJob | null> {
    return this.request<SyncJob | null>('/api/qfield-sync-current');
  }

  /**
   * Get sync history
   */
  async getSyncHistory(
    page = 1,
    pageSize = 20
  ): Promise<SyncHistoryResponse> {
    return this.request<SyncHistoryResponse>(
      `/api/qfield-sync-history?page=${page}&pageSize=${pageSize}`
    );
  }

  /**
   * Get sync statistics
   */
  async getSyncStats(): Promise<SyncStats> {
    return this.request<SyncStats>('/api/qfield-sync-stats');
  }

  /**
   * Get unresolved conflicts
   */
  async getConflicts(): Promise<SyncConflict[]> {
    return this.request<SyncConflict[]>('/api/qfield-sync-conflicts');
  }

  /**
   * Resolve a conflict
   */
  async resolveConflict(
    conflictId: string,
    resolution: 'use_qfield' | 'use_fibreflow' | 'merge' | 'skip'
  ): Promise<SyncResponse> {
    return this.request<SyncResponse>('/api/qfield-sync-conflicts-resolve', {
      method: 'POST',
      body: JSON.stringify({ conflictId, resolution }),
    });
  }

  /**
   * Test QFieldCloud connection
   */
  async testQFieldConnection(): Promise<SyncResponse> {
    return this.request<SyncResponse>('/api/qfield-sync-test-qfield');
  }

  /**
   * Test FibreFlow database connection
   */
  async testDatabaseConnection(): Promise<SyncResponse> {
    return this.request<SyncResponse>('/api/qfield-sync-test-database');
  }

  /**
   * Update sync configuration
   */
  async updateConfig(config: any): Promise<SyncResponse> {
    return this.request<SyncResponse>('/api/qfield-sync-config', {
      method: 'PUT',
      body: JSON.stringify(config),
    });
  }

  /**
   * Get sync configuration
   */
  async getConfig(): Promise<any> {
    return this.request<any>('/api/qfield-sync-config');
  }

  /**
   * Trigger manual sync
   */
  async triggerManualSync(
    type: SyncJob['type'] = 'fiber_cables'
  ): Promise<SyncJob> {
    return this.request<SyncJob>('/api/qfield-sync-manual', {
      method: 'POST',
      body: JSON.stringify({ type }),
    });
  }

  /**
   * Cancel current sync job
   */
  async cancelSync(): Promise<SyncResponse> {
    return this.request<SyncResponse>('/api/qfield-sync-cancel', {
      method: 'POST',
    });
  }

  /**
   * Get sync job details
   */
  async getSyncJob(jobId: string): Promise<SyncJob> {
    return this.request<SyncJob>(`/api/qfield-sync-jobs?id=${jobId}`);
  }

  /**
   * Export sync history as CSV
   */
  async exportSyncHistory(): Promise<Blob> {
    const response = await fetch('/api/qfield-sync-export', {
      method: 'GET',
      headers: {
        'Accept': 'text/csv',
      },
    });

    if (!response.ok) {
      throw new Error(`Export failed with status ${response.status}`);
    }

    return response.blob();
  }

  /**
   * WebSocket connection for real-time updates
   */
  connectWebSocket(
    onMessage: (event: MessageEvent) => void,
    onError?: (event: Event) => void
  ): WebSocket | null {
    // Check if we're in a browser environment
    if (typeof window === 'undefined') {
      log.debug('qfieldSyncApiService', { action: 'connectWebSocket', status: 'unavailable', message: 'WebSocket not available in server-side rendering' });
      return null;
    }

    try {
      const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
      const host = window.location.host;
      const ws = new WebSocket(`${protocol}//${host}/ws/qfield-sync`);

      ws.onmessage = onMessage;
      ws.onerror = onError || ((error) => log.error('qfieldSyncApiService', { action: 'websocketDefaultError', error }));

      ws.onopen = () => {
        log.debug('qfieldSyncApiService', { action: 'websocketOpen', status: 'connected' });
      };

      ws.onclose = () => {
        log.debug('qfieldSyncApiService', { action: 'websocketClose', status: 'disconnected' });
      };

      return ws;
    } catch (error) {
      log.error('qfieldSyncApiService', { action: 'websocketCreate', error });
      return null;
    }
  }

  /**
   * Get fiber cable records from QFieldCloud
   */
  async getQFieldFiberCables(projectId: string): Promise<any[]> {
    return this.request<any[]>(`/api/qfield-sync-fiber-cables?projectId=${projectId}&source=qfield`);
  }

  /**
   * Get fiber cable records from FibreFlow
   */
  async getFibreFlowFiberCables(): Promise<any[]> {
    return this.request<any[]>('/api/qfield-sync-fiber-cables?source=fibreflow');
  }

  /**
   * Compare records between systems
   */
  async compareRecords(type: string): Promise<any> {
    return this.request<any>(`/api/qfield-sync-compare?type=${type}`);
  }

  /**
   * Batch update multiple records
   */
  async batchUpdate(records: any[]): Promise<SyncResponse> {
    return this.request<SyncResponse>('/api/qfield-sync-batch-update', {
      method: 'POST',
      body: JSON.stringify({ records }),
    });
  }

  /**
   * Get sync logs
   */
  async getSyncLogs(
    jobId?: string,
    level?: 'info' | 'warning' | 'error'
  ): Promise<any[]> {
    const params = new URLSearchParams();
    if (jobId) params.append('jobId', jobId);
    if (level) params.append('level', level);

    const query = params.toString() ? `?${params.toString()}` : '';
    return this.request<any[]>(`/api/qfield-sync-logs${query}`);
  }

  /**
   * Health check endpoint
   */
  async healthCheck(): Promise<{
    status: string;
    qfieldConnection: boolean;
    databaseConnection: boolean;
    lastSync: string | null;
  }> {
    return this.request('/api/qfield-sync-health');
  }
}

// Export singleton instance
export const qfieldSyncApiService = new QFieldSyncApiService();/**
 * QField Sync Service
 * Core business logic for QFieldCloud synchronization
 */

import { log } from '@/lib/logger';
import {
  QFieldProject,
  QFieldFiberCable,
  SyncJob,
  SyncStatus,
  SyncDirection,
  SyncError,
  SyncConflict,
  SyncStats,
  DataTransformer,
  ValidationResult,
} from '../types/qfield-sync.types';
import {
  DEFAULT_SYNC_CONFIG,
  STATUS_MAPPING,
  FIBER_CABLE_VALIDATION,
  MAX_RETRY_ATTEMPTS,
  BATCH_SIZE,
} from '../config/sync-config';

export class QFieldSyncService {
  private currentJob: SyncJob | null = null;
  private syncInProgress: boolean = false;
  private retryCount: Map<string, number> = new Map();

  /**
   * Initialize a new sync job
   */
  async startSync(
    type: SyncJob['type'],
    direction: SyncDirection
  ): Promise<SyncJob> {
    if (this.syncInProgress) {
      throw new Error('A sync operation is already in progress');
    }

    this.syncInProgress = true;

    const job: SyncJob = {
      id: this.generateJobId(),
      type,
      status: 'syncing',
      direction,
      startedAt: new Date().toISOString(),
      recordsProcessed: 0,
      recordsCreated: 0,
      recordsUpdated: 0,
      recordsFailed: 0,
      errors: [],
    };

    this.currentJob = job;

    try {
      switch (type) {
        case 'fiber_cables':
          await this.syncFiberCables(job, direction);
          break;
        case 'poles':
          await this.syncPoles(job, direction);
          break;
        case 'splice_closures':
          await this.syncSpliceClosures(job, direction);
          break;
        case 'test_points':
          await this.syncTestPoints(job, direction);
          break;
      }

      job.status = 'completed';
      job.completedAt = new Date().toISOString();
      job.duration = new Date(job.completedAt).getTime() - new Date(job.startedAt).getTime();

    } catch (error) {
      job.status = 'error';
      job.completedAt = new Date().toISOString();
      job.duration = new Date(job.completedAt).getTime() - new Date(job.startedAt).getTime();
      job.errors.push({
        recordId: 'system',
        message: error instanceof Error ? error.message : 'Unknown error',
        timestamp: new Date().toISOString(),
      });
    } finally {
      this.syncInProgress = false;
      this.currentJob = null;
    }

    return job;
  }

  /**
   * Sync fiber cables between QFieldCloud and FibreFlow
   */
  private async syncFiberCables(
    job: SyncJob,
    direction: SyncDirection
  ): Promise<void> {
    if (direction === 'qfield_to_fibreflow' || direction === 'bidirectional') {
      await this.syncQFieldToFibreFlow(job);
    }

    if (direction === 'fibreflow_to_qfield' || direction === 'bidirectional') {
      await this.syncFibreFlowToQField(job);
    }
  }

  /**
   * Sync from QFieldCloud to FibreFlow
   */
  private async syncQFieldToFibreFlow(job: SyncJob): Promise<void> {
    // Fetch data from QFieldCloud
    const qfieldCables = await this.fetchQFieldFiberCables();

    // Process in batches
    const batches = this.createBatches(qfieldCables, BATCH_SIZE.MEDIUM);

    for (const batch of batches) {
      for (const cable of batch) {
        try {
          // Validate data
          const validation = this.validateFiberCable(cable);
          if (!validation.valid) {
            job.recordsFailed++;
            validation.errors.forEach(error => {
              job.errors.push({
                recordId: cable.cableId,
                field: error.field,
                message: error.message,
                timestamp: new Date().toISOString(),
              });
            });
            continue;
          }

          // Transform data
          const transformed = this.transformQFieldToFibreFlow(cable);

          // Check for conflicts
          const existingRecord = await this.fetchFibreFlowRecord(cable.cableId);

          if (existingRecord) {
            const conflicts = this.detectConflicts(cable, existingRecord);
            if (conflicts.length > 0 && !DEFAULT_SYNC_CONFIG.autoResolveConflicts) {
              // Store conflicts for manual resolution
              await this.storeConflicts(conflicts);
              job.recordsFailed++;
              continue;
            }

            // Update existing record
            await this.updateFibreFlowRecord(cable.cableId, transformed);
            job.recordsUpdated++;
          } else {
            // Create new record
            await this.createFibreFlowRecord(transformed);
            job.recordsCreated++;
          }

          job.recordsProcessed++;

        } catch (error) {
          job.recordsFailed++;
          job.errors.push({
            recordId: cable.cableId,
            message: error instanceof Error ? error.message : 'Processing error',
            timestamp: new Date().toISOString(),
          });

          // Retry logic
          const retryCount = this.retryCount.get(cable.cableId) || 0;
          if (retryCount < MAX_RETRY_ATTEMPTS) {
            this.retryCount.set(cable.cableId, retryCount + 1);
            // Add to retry queue (implementation needed)
          }
        }
      }

      // Small delay between batches to avoid overwhelming the system
      await this.delay(100);
    }
  }

  /**
   * Sync from FibreFlow to QFieldCloud
   */
  private async syncFibreFlowToQField(job: SyncJob): Promise<void> {
    // Implementation for reverse sync
    // Similar structure to syncQFieldToFibreFlow but in reverse
    log.debug('qfieldSyncService', { message: 'Syncing from FibreFlow to QField' });
    // TODO: Implement reverse sync logic
  }

  /**
   * Validate fiber cable data
   */
  private validateFiberCable(cable: QFieldFiberCable): ValidationResult {
    const errors: Array<{ field: string; message: string }> = [];

    // Validate cable ID
    if (!cable.cableId) {
      errors.push({ field: 'cableId', message: 'Cable ID is required' });
    } else if (!FIBER_CABLE_VALIDATION.cable_id.pattern.test(cable.cableId)) {
      errors.push({ field: 'cableId', message: FIBER_CABLE_VALIDATION.cable_id.message });
    }

    // Validate cable type
    if (!cable.cableType) {
      errors.push({ field: 'cableType', message: 'Cable type is required' });
    } else if (!FIBER_CABLE_VALIDATION.cable_type.options.includes(cable.cableType)) {
      errors.push({ field: 'cableType', message: FIBER_CABLE_VALIDATION.cable_type.message });
    }

    // Validate length
    if (cable.length !== undefined) {
      if (cable.length < FIBER_CABLE_VALIDATION.length.min ||
          cable.length > FIBER_CABLE_VALIDATION.length.max) {
        errors.push({ field: 'length', message: FIBER_CABLE_VALIDATION.length.message });
      }
    }

    // Validate fiber count
    if (cable.fiberCount !== undefined) {
      if (!FIBER_CABLE_VALIDATION.fiber_count.options.includes(cable.fiberCount)) {
        errors.push({ field: 'fiberCount', message: FIBER_CABLE_VALIDATION.fiber_count.message });
      }
    }

    return {
      valid: errors.length === 0,
      errors,
    };
  }

  /**
   * Transform QField data to FibreFlow format
   */
  private transformQFieldToFibreFlow(cable: QFieldFiberCable): any {
    const statusMap = STATUS_MAPPING.qfieldToFibreflow as any;

    return {
      cable_id: cable.cableId,
      cable_type: cable.cableType?.toUpperCase(),
      cable_size: cable.cableSize,
      fiber_count: cable.fiberCount,
      start_location: cable.startPole,
      end_location: cable.endPole,
      start_latitude: cable.geometry.coordinates[0][1],
      start_longitude: cable.geometry.coordinates[0][0],
      end_latitude: cable.geometry.coordinates[cable.geometry.coordinates.length - 1][1],
      end_longitude: cable.geometry.coordinates[cable.geometry.coordinates.length - 1][0],
      length: cable.length,
      installation_method: 'aerial', // Default
      status: statusMap[cable.installationStatus] || cable.installationStatus,
      installation_date: cable.installationDate,
      installed_by: cable.installedBy,
      splicing_complete: cable.splicingComplete,
      testing_complete: cable.testingComplete,
      notes: cable.notes,
      route_map: cable.geometry,
      metadata: {
        qfield_feature_id: cable.featureId,
        last_synced: new Date().toISOString(),
      },
    };
  }

  /**
   * Detect conflicts between QField and FibreFlow data
   */
  private detectConflicts(
    qfieldData: QFieldFiberCable,
    fibreflowData: any
  ): SyncConflict[] {
    const conflicts: SyncConflict[] = [];
    const fieldsToCheck = ['cableType', 'status', 'installedBy', 'installationDate'];

    for (const field of fieldsToCheck) {
      const qfieldValue = (qfieldData as any)[field];
      const fibreflowValue = fibreflowData[this.mapFieldName(field)];

      if (qfieldValue !== undefined && fibreflowValue !== undefined &&
          qfieldValue !== fibreflowValue) {
        conflicts.push({
          id: this.generateConflictId(),
          recordId: qfieldData.cableId,
          field,
          qfieldValue,
          fibreflowValue,
          detectedAt: new Date().toISOString(),
        });
      }
    }

    return conflicts;
  }

