    return <div className="text-center py-8 text-[var(--ff-text-tertiary)] text-sm">No active BOQs found.</div>;
  }

  const overallOrdPct = totals.boqValue > 0 ? Math.round((totals.totalOrdered / totals.boqValue) * 100) : 0;
